const diagnoseRehydrateFailure = (rawItem) => {
  const details = {
    reasons: [],
    lookup: {
      resourceId: Number(rawItem?.resourceId || 0),
      definitionId: Number(rawItem?.definitionId || 0),
      eaId: Number(rawItem?.eaId || 0),
      id: Number(rawItem?.id || 0),
    },
    rawRating: Number(rawItem?.rating || 0),
    factoryAvailable: !!globalThis.UTItemEntityFactory,
  };

  if (!rawItem) {
    details.reasons.push("rawEntryMissing");
    return details;
  }

  const defId = Number(
    rawItem?.resourceId || rawItem?.definitionId || rawItem?.eaId || 0,
  );
  if (!Number.isFinite(defId) || defId <= 0) {
    details.reasons.push("invalidDefinitionId");
    return details;
  }

  const factoryPayload = {
    id: Number(rawItem?.id || 0),
    resourceId: defId,
    itemType: rawItem?.itemType || globalThis.ItemType?.PLAYER || 1,
    owners: 0,
    untrade: 1,
    loans: Number.isFinite(Number(rawItem?.loans)) ? Number(rawItem.loans) : -1,
  };

  const entity = createUtItemEntity(factoryPayload);
  if (!entity) {
    details.reasons.push("createUtItemEntityReturnedNull");
    return details;
  }

  details.entityHasPrototypeMethods = hasUtItemEntityFunctions(entity);
  if (!details.entityHasPrototypeMethods) {
    details.reasons.push("missingUtItemEntityPrototypeMethods");
  }

  if (!Number(entity?.definitionId)) {
    entity.definitionId = defId;
  }

  const staticData = entity?._staticData || {};
  const entityRatingBefore = Number(entity?.rating || 0);
  const staticRatingBefore = Number(staticData?.rating || 0);

  const derivedRating = Number(
    entity?.rating || staticData?.rating || rawItem?.rating || 0,
  );
  const derivedDefinitionId = Number(entity?.definitionId || defId || 0);

  if (derivedRating > 0 && Number(entity?.rating || 0) <= 0) {
    entity.rating = derivedRating;
  }
  if (derivedRating > 0 && Number(staticData?.rating || 0) <= 0) {
    staticData.rating = derivedRating;
  }

  const entityRatingAfter = Number(entity?.rating || 0);
  const staticRatingAfter = Number(staticData?.rating || 0);

  details.derived = {
    definitionId: derivedDefinitionId,
    rating: derivedRating,
    entityRatingBefore,
    staticRatingBefore,
    entityRatingAfter,
    staticRatingAfter,
    hasCoreDataGatePassed: derivedDefinitionId > 0 && derivedRating > 0,
  };

  if (derivedDefinitionId <= 0) {
    details.reasons.push("definitionIdMissingAfterRehydrate");
  }
  if (derivedRating <= 0) {
    details.reasons.push("ratingMissingAfterRehydrate");
  }
  if (!(derivedDefinitionId > 0 && derivedRating > 0)) {
    details.reasons.push("coreDataGateFailed");
  }
  if (derivedRating > 0 && entityRatingAfter <= 0 && staticRatingAfter <= 0) {
    details.reasons.push("ratingWriteDidNotStickOnEntity");
  }

  return details;
};

// Build one UTItemEntity from cache by id/definitionId/resourceId.
// Usage: await createutitemfromcache(239085)
const createUtItemFromCache = async (id) => {
  const lookupId = Number(id);
  if (!Number.isFinite(lookupId) || lookupId <= 0) {
    console.warn("[concepts-cache] createUtItemFromCache: invalid id", id);
    return null;
  }

  try {
    const db = await openConceptsDb();
    const cacheHit = await new Promise((resolve) => {
      const tx = db.transaction(["conceptsStore"], "readonly");
      const store = tx.objectStore("conceptsStore");
      const getRequest = store.get("allConcepts");

      getRequest.onsuccess = function (event) {
        const all = event.target.result?.data || [];
        const matchedIndex = all.findIndex((r) => {
          return (
            Number(r?.resourceId) === lookupId ||
            Number(r?.definitionId) === lookupId ||
            Number(r?.eaId) === lookupId
          );
        });
        if (matchedIndex < 0) {
          resolve({ rawEntry: null });
          return;
        }
        resolve({ rawEntry: all[matchedIndex] });
      };

      getRequest.onerror = function () {
        resolve({ rawEntry: null });
      };
    });

    const rawEntry = cacheHit.rawEntry;

    if (!rawEntry) {
      console.warn(`[concepts-cache] createUtItemFromCache: id ${lookupId} not found in cache`);
      return null;
    }

    const entity = rehydrateConceptEntity(rawEntry);
    if (!entity) {
      const diagnostics = diagnoseRehydrateFailure(rawEntry);
      console.warn(
        `[concepts-cache] createUtItemFromCache: id ${lookupId} found in cache but failed rehydration`,
        diagnostics,
      );
      return null;
    }

    return entity;
  } catch (err) {
    console.warn("[concepts-cache] createUtItemFromCache failed:", err);
    return null;
  }
};

if (typeof window !== "undefined") {
  window.createUtItemFromCache = createUtItemFromCache;
  window.createutitemfromcache = createUtItemFromCache;
  window.fetchNewPlayersFromFutgg = fetchNewPlayersFromFutgg;
}

// Diagnostic: compare a cached/rehydrated entity vs one returned by searchConceptItems.
// Usage: window.diffConceptEntity(defId) — e.g. diffConceptEntity(239085)
window.diffConceptEntity = async (defId) => {
  const numId = Number(defId);
  if (!numId) { console.error("[diffConceptEntity] invalid defId"); return; }

  // 1. Find the raw serialized entry from IndexedDB
  const db = await openConceptsDb();
  const rawEntry = await new Promise((resolve) => {
    const tx = db.transaction(["conceptsStore"], "readonly");
    tx.objectStore("conceptsStore").get("allConcepts").onsuccess = (e) => {
      const all = e.target.result?.data || [];
      resolve(all.find((r) => Number(r?.resourceId) === numId || Number(r?.id) === numId) || null);
    };
  });

  // 2. Rehydrate from cache (what the system currently does)
  const cached = rawEntry ? rehydrateConceptEntity(rawEntry) : null;

  // 3. Fetch live from searchConceptItems
  const live = await new Promise((resolve) => {
    if (!services?.Item?.searchConceptItems || typeof UTSearchCriteriaDTO === "undefined") {
      return resolve(null);
    }
    const dto = new UTSearchCriteriaDTO();
    dto.offset = 0;
    dto.count = 5;
    dto.defId = [numId];
    if (typeof SearchType !== "undefined") dto.type = SearchType.PLAYER;
    const ctx = getControllerInstance?.() || globalThis;
    services.Item.searchConceptItems(dto).observe(ctx, function (sender, response) {
      try { sender?.unobserve?.(ctx); } catch {}
      const items = response?.response?.items || [];
      resolve(items[0] || null);
    });
  });

  const snapshot = (item) => {
    if (!item) return null;
    const sd = item?._staticData || {};
    return {
      definitionId: item?.definitionId,
      rating: item?.rating,
      nationId: item?.nationId,
      teamId: item?.teamId,
      leagueId: item?.leagueId,
      _rareflag: item?._rareflag,
      name: item?.name || sd?.name,
      firstName: sd?.firstName,
      lastName: sd?.lastName,
      _staticData: { ...sd },
      hasGetSearchType: typeof item?.getSearchType === "function",
      hasIsPlayer: typeof item?.isPlayer === "function",
      hasIsTradeable: typeof item?.isTradeable === "function",
    };
  };

  const cachedSnap = snapshot(cached);
  const liveSnap = snapshot(live);

  // Find fields where cached differs from live
  const diff = {};
  if (cachedSnap && liveSnap) {
    const allKeys = new Set([...Object.keys(cachedSnap), ...Object.keys(liveSnap)]);
    for (const key of allKeys) {
      if (key === "_staticData") continue;
      const c = cachedSnap[key];
      const l = liveSnap[key];
      if (JSON.stringify(c) !== JSON.stringify(l)) diff[key] = { cached: c, live: l };
    }
    // Also diff _staticData fields
    const sdKeys = new Set([
      ...Object.keys(cachedSnap._staticData || {}),
      ...Object.keys(liveSnap._staticData || {}),
    ]);
    for (const k of sdKeys) {
      const c = cachedSnap._staticData?.[k];
      const l = liveSnap._staticData?.[k];
      if (JSON.stringify(c) !== JSON.stringify(l)) diff[`_staticData.${k}`] = { cached: c, live: l };
    }
  }

  console.log("[diffConceptEntity] defId:", numId);
  console.log("[diffConceptEntity] rawCached:", rawEntry);
  console.log("[diffConceptEntity] cachedEntity:", cachedSnap);
  console.log("[diffConceptEntity] liveEntity:", liveSnap);
  console.log("[diffConceptEntity] DIFF (fields that differ):", diff);

  return { rawEntry, cached: cachedSnap, live: liveSnap, diff };
};
const packVisibilityStore = (() => {
  const storageKey = "sbcPackVisibilityState";
  return {
    load() {
      try {
        const raw = localStorage.getItem(storageKey);
        return raw ? JSON.parse(raw) : {};
      } catch {
        return {};
      }
    },
    save(state) {
      localStorage.setItem(storageKey, JSON.stringify(state));
    },
    get(id) {
      const state = this.load();
      return id in state ? state[id] : true;
    },
    set(id, value) {
      const state = this.load();
      state[id] = value;
      this.save(state);
    },
  };
})();
// Collection Book — data layer.
//
// Lazily fetches fut.gg "Collections" and their players, caching each result in
// localStorage so a collection's players are only fetched the first time the user
// scrolls it into view. The CLUB is the source of truth for what has been
// collected: ownership + per-player copy counts are derived from
// window.__clubPlayersEntries (populated by setClubPlayersFromItems on every club
// search), and collectionBookUpdateFromClub() is invoked whenever a club search runs.
//
// Network calls go directly to fut.gg via the shared makeGetRequest helper
// (GM_xmlhttpRequest), the same transport the pricing module already uses.

const COLLECTION_BOOK_GAME_YEAR = 27;
const COLLECTION_BOOK_ORIGIN = "https://www.fut.gg";

const COLLECTION_BOOK_LIST_URL = `${COLLECTION_BOOK_ORIGIN}/api/fut/collections/${COLLECTION_BOOK_GAME_YEAR}/`;
const COLLECTION_BOOK_PLAYERS_URL = (slug) =>
  `${COLLECTION_BOOK_ORIGIN}/api/fut/collections/${COLLECTION_BOOK_GAME_YEAR}/${slug}/players/`;

// Cache keys + TTLs.
const COLLECTION_BOOK_LIST_KEY = "collectionBook.list.v1";
const COLLECTION_BOOK_PLAYERS_KEY = (slug) => `collectionBook.players.v1.${slug}`;
const COLLECTION_BOOK_LIST_TTL_MS = 6 * 60 * 60 * 1000; // 6h
const COLLECTION_BOOK_PLAYERS_TTL_MS = 24 * 60 * 60 * 1000; // 24h

// In-flight de-duplication so concurrent scrolls don't double-fetch.
const _collectionBookPlayersInFlight = new Map();
let _collectionBookListInFlight = null;

// --- low level HTTP -------------------------------------------------------

const _collectionBookGetJson = async (url) => {
  // Prefer the GM transport (cross-origin to fut.gg is granted for pricing).
  if (typeof makeGetRequest === "function") {
    const text = await makeGetRequest(url);
    return JSON.parse(text);
  }
  // Fallback for environments where GM_xmlhttpRequest is unavailable.
  const resp = await fetch(url, { headers: { Accept: "application/json" } });
  if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
  return resp.json();
};

// --- cache helpers --------------------------------------------------------

const _collectionBookReadCache = (key, ttlMs) => {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return null;
    if (ttlMs && Date.now() - Number(parsed.ts || 0) > ttlMs) return null;
    return parsed.data;
  } catch {
    return null;
  }
};

const _collectionBookWriteCache = (key, data) => {
  try {
    localStorage.setItem(key, JSON.stringify({ ts: Date.now(), data }));
  } catch (err) {
    console.warn("[CollectionBook] cache write failed", key, err);
  }
};

// --- slim mappers ---------------------------------------------------------

const _collectionBookSlimPlayer = (p) => {
  const name =
    p?.cardName ||
    p?.nickname ||
    [p?.firstName, p?.lastName].filter(Boolean).join(" ") ||
    String(p?.eaId);
  return {
    eaId: Number(p?.eaId),
    name,
    overall: p?.overall ?? null,
    position: p?.position ?? null,
    positionId: p?.positionId ?? null,
    rarityEaId: p?.rarityEaId ?? null,
    rarityName: p?.rarityName ?? null,
    isIcon: !!p?.isIcon,
    isHero: !!p?.isHero,
    clubEaId: p?.uniqueClubEaId ?? null,
    nationEaId: p?.nation?.eaId ?? null,
    leagueEaId: p?.league?.eaId ?? null,
    cardImageUrl: p?.cardImageUrl || null,
  };
};

// --- collections list -----------------------------------------------------

// Fetch (all pages of) the collections index: name, slug, and full eaId list.
// Cached; call with { force:true } to bypass the cache.
const collectionBookFetchList = async ({ force = false } = {}) => {
  if (!force) {
    const cached = _collectionBookReadCache(
      COLLECTION_BOOK_LIST_KEY,
      COLLECTION_BOOK_LIST_TTL_MS,
    );
    if (cached) return cached;
  }
  if (_collectionBookListInFlight) return _collectionBookListInFlight;

  _collectionBookListInFlight = (async () => {
    const collections = [];
    let page = 1;
    let totalPages = 1;
    try {
      while (page <= totalPages) {
        const url = `${COLLECTION_BOOK_LIST_URL}?page=${page}&page_size=20`;
        const payload = await _collectionBookGetJson(url);
        totalPages = Number(payload?.totalPages || 1);
        for (const item of payload?.data || []) {
          if (!item?.slug) continue;
          collections.push({
            id: item.id,
            name: item.name || item.slug,
            slug: item.slug,
            description: item.description || "",
            total: (item.allPlayerItemEaIds || []).length,
            allPlayerItemEaIds: (item.allPlayerItemEaIds || []).map(Number),
            highlightedPlayerItemEaIds: (
              item.highlightedPlayerItemEaIds || []
            ).map(Number),
          });
        }
        page += 1;
      }
    } catch (err) {
      console.warn("[CollectionBook] list fetch failed", err);
      // Fall back to any stale cache rather than nothing.
      const stale = _collectionBookReadCache(COLLECTION_BOOK_LIST_KEY, 0);
      if (stale) return stale;
      throw err;
    }
    _collectionBookWriteCache(COLLECTION_BOOK_LIST_KEY, collections);
    return collections;
  })();

  try {
    return await _collectionBookListInFlight;
  } finally {
    _collectionBookListInFlight = null;
  }
};

// --- per-collection players (lazy) ---------------------------------------

// Fetch (all pages of) one collection's players. Cached per slug and
// de-duplicated so repeated scroll events resolve to a single network run.
const collectionBookFetchPlayers = async (slug, { force = false } = {}) => {
  if (!slug) return [];
  if (!force) {
    const cached = _collectionBookReadCache(
      COLLECTION_BOOK_PLAYERS_KEY(slug),
      COLLECTION_BOOK_PLAYERS_TTL_MS,
    );
    if (cached) return cached;
  }
  if (_collectionBookPlayersInFlight.has(slug)) {
    return _collectionBookPlayersInFlight.get(slug);
  }

  const run = (async () => {
    const players = [];
    let page = 1;
    let totalPages = 1;
    try {
      while (page <= totalPages) {
        const url = `${COLLECTION_BOOK_PLAYERS_URL(slug)}?page=${page}`;
        const payload = await _collectionBookGetJson(url);
        totalPages = Number(payload?.totalPages || 1);
        for (const p of payload?.data || []) {
          if (p?.eaId == null) continue;
          players.push(_collectionBookSlimPlayer(p));
        }
        page += 1;
      }
    } catch (err) {
      console.warn(`[CollectionBook] players fetch failed (${slug})`, err);
      const stale = _collectionBookReadCache(
        COLLECTION_BOOK_PLAYERS_KEY(slug),
        0,
      );
      if (stale) return stale;
      throw err;
    }
    _collectionBookWriteCache(COLLECTION_BOOK_PLAYERS_KEY(slug), players);
    return players;
  })();

  _collectionBookPlayersInFlight.set(slug, run);
  try {
    return await run;
  } finally {
    _collectionBookPlayersInFlight.delete(slug);
  }
};

// --- background prefetch (fetch-on-init) ---------------------------------

let _collectionBookPrefetchInFlight = null;

// Fetch the collections list, then fetch players for every collection that is
// not already cached (fresh). Mirrors the concept-fetch pattern: runs in the
// background on init and keeps going through all collections until each one has
// been fetched (or a cached copy exists). Safe to call repeatedly — cached and
// in-flight collections are skipped, so it only fills in what is missing.
const collectionBookPrefetchAll = async ({ force = false } = {}) => {
  if (_collectionBookPrefetchInFlight) return _collectionBookPrefetchInFlight;

  _collectionBookPrefetchInFlight = (async () => {
    let list = [];
    try {
      list = await collectionBookFetchList({ force });
    } catch (err) {
      console.warn("[CollectionBook] prefetch: list failed", err);
      return;
    }

    let fetched = 0;
    let skipped = 0;
    for (const col of list) {
      const cached = _collectionBookReadCache(
        COLLECTION_BOOK_PLAYERS_KEY(col.slug),
        force ? 0 : COLLECTION_BOOK_PLAYERS_TTL_MS,
      );
      if (cached && !force) {
        skipped += 1;
        continue;
      }
      try {
        await collectionBookFetchPlayers(col.slug, { force });
        fetched += 1;
        // Let the (optional) open page fill in this section as it arrives.
        if (typeof window.__collectionBookOnSectionFetched === "function") {
          window.__collectionBookOnSectionFetched(col.slug);
        }
      } catch (err) {
        console.warn(
          `[CollectionBook] prefetch: players failed (${col.slug})`,
          err,
        );
      }
    }
    console.log(
      `[CollectionBook] prefetch complete — ${fetched} fetched, ${skipped} cached, ${list.length} total`,
    );
    // All collection players are now loaded — make the Collection Book tab
    // available (it is injected hidden until this point).
    window.__collectionBookAllLoaded = true;
    try {
      document
        .querySelectorAll(".collection-book-tab-deferred")
        .forEach((el) => {
          el.style.display = "";
          el.classList.remove("collection-book-tab-deferred");
        });
    } catch {}
  })();

  try {
    return await _collectionBookPrefetchInFlight;
  } finally {
    _collectionBookPrefetchInFlight = null;
  }
};

// --- club ownership (source of truth) ------------------------------------

// Persisted ownership cache (backend). The club is the live source of truth,
// but a player passes through the unassigned pile (freshly packed / picked)
// before it reaches the club, and can be sent to the transfer list or storage.
// To count a collection player as owned as soon as it is seen — and to keep
// counting duplicates by distinct entity (instance) id — every observed
// {definitionId, entityId} pair is persisted to a backend file. The count per
// definitionId is the number of distinct entity ids recorded for it, so
// multiple entity ids against the same definitionId increment the counter.
const COLLECTION_BOOK_OWNERSHIP_API_URL =
  "http://127.0.0.1:8000/api/collection-book-ownership";

// definitionId(number) -> count(number), hydrated from the backend.
let _collectionBookOwnershipCounts = new Map();

const _collectionBookApplyOwnershipCounts = (counts) => {
  if (!counts || typeof counts !== "object") return;
  const next = new Map();
  for (const [defId, n] of Object.entries(counts)) {
    const id = Number(defId);
    const count = Number(n);
    if (Number.isFinite(id) && id > 0 && Number.isFinite(count) && count > 0) {
      next.set(id, count);
    }
  }
  _collectionBookOwnershipCounts = next;
};

// Load persisted ownership counts from the backend into memory.
const collectionBookFetchOwnership = async () => {
  try {
    const resp = await fetch(COLLECTION_BOOK_OWNERSHIP_API_URL, {
      headers: { Accept: "application/json" },
    });
    if (!resp.ok) return;
    const json = await resp.json();
    _collectionBookApplyOwnershipCounts(json?.counts);
  } catch (err) {
    console.warn("[CollectionBook] ownership fetch failed", err);
  }
};

// Extract {definitionId, entityId} pairs from raw EA items. entityId is the
// unique instance id (item.id), which persists as a player moves between piles.
const _collectionBookOwnershipPairs = (items) => {
  const pairs = [];
  for (const item of items || []) {
    const defId = Number(item?.definitionId);
    const entityId = item?.id;
    if (!Number.isFinite(defId) || defId <= 0) continue;
    if (entityId == null) continue;
    pairs.push({ definitionId: defId, entityId: String(entityId) });
  }
  return pairs;
};

// Record ownership for a batch of EA items (club search / unassigned search),
// then refresh the Collection Book counters with the merged counts. The backend
// dedupes by entity id, so repeated searches never inflate the count.
const collectionBookRecordOwnership = async (items) => {
  try {
    const pairs = _collectionBookOwnershipPairs(items);
    if (!pairs.length) return;
    const resp = await fetch(COLLECTION_BOOK_OWNERSHIP_API_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ pairs }),
    });
    if (!resp.ok) return;
    const json = await resp.json();
    _collectionBookApplyOwnershipCounts(json?.counts);
    if (typeof window.__collectionBookOnClubUpdate === "function") {
      window.__collectionBookOnClubUpdate(collectionBookGetOwnedCounts());
    }
  } catch (err) {
    console.warn("[CollectionBook] ownership record failed", err);
  }
};

// Map definitionId -> number of copies owned. Merges the live club-players
// entries (setClubPlayersFromItems) with the persisted backend ownership cache,
// taking the larger count per definitionId so the counter reflects every
// distinct entity id seen across club + unassigned, even before a player lands
// in the club.
const collectionBookGetOwnedCounts = () => {
  const counts = new Map();
  const entries = Array.isArray(window.__clubPlayersEntries)
    ? window.__clubPlayersEntries
    : [];
  for (const entry of entries) {
    const defId = Number(entry?.definitionId);
    if (!Number.isFinite(defId) || defId <= 0) continue;
    counts.set(defId, (counts.get(defId) || 0) + 1);
  }
  if (_collectionBookOwnershipCounts instanceof Map) {
    for (const [defId, cached] of _collectionBookOwnershipCounts.entries()) {
      counts.set(defId, Math.max(counts.get(defId) || 0, cached));
    }
  }
  return counts;
};

// Map definitionId -> copies currently in the *club* (live __clubPlayersEntries
// only, excluding the persisted seen-before cache). Used to colour the copy
// counter green (in club) vs red (seen before but not currently in the club).
const collectionBookGetClubCounts = () => {
  const counts = new Map();
  const entries = Array.isArray(window.__clubPlayersEntries)
    ? window.__clubPlayersEntries
    : [];
  for (const entry of entries) {
    const defId = Number(entry?.definitionId);
    if (!Number.isFinite(defId) || defId <= 0) continue;
    counts.set(defId, (counts.get(defId) || 0) + 1);
  }
  return counts;
};

// Console diagnostic: explain why a given player is / isn't counted as owned.
// Pass an eaId (number) or a name substring. Prints the collection player's
// eaId, whether the club ownership map has that id, and any club entries whose
// name matches — so an eaId<->definitionId mismatch is obvious at a glance.
// Usage:  collectionBookDebugOwnership("Bellerin")  or  collectionBookDebugOwnership(12345)
const collectionBookDebugOwnership = (query) => {
  const counts = collectionBookGetOwnedCounts();
  const entries = Array.isArray(window.__clubPlayersEntries)
    ? window.__clubPlayersEntries
    : [];
  const cached = (typeof collectionBookGetAllCachedPlayers === "function"
    ? collectionBookGetAllCachedPlayers()
    : []) || [];

  const isNum = typeof query === "number" || /^\d+$/.test(String(query || ""));
  const wanted = isNum ? Number(query) : String(query || "").toLowerCase();

  const collectionMatches = cached.filter((p) =>
    isNum
      ? Number(p.eaId) === wanted
      : String(p.name || "").toLowerCase().includes(wanted),
  );
  const clubMatches = entries.filter((e) =>
    isNum
      ? Number(e.definitionId) === wanted
      : String(e.name || "").toLowerCase().includes(wanted),
  );

  console.group(`[CollectionBook] ownership debug: ${query}`);
  console.log(`club entries loaded: ${entries.length}`);
  console.table(
    collectionMatches.map((p) => ({
      name: p.name,
      "collection.eaId": Number(p.eaId),
      "ownedCount(eaId)": counts.get(Number(p.eaId)) || 0,
      countedAsOwned: (counts.get(Number(p.eaId)) || 0) > 0,
    })),
  );
  console.table(
    clubMatches.map((e) => ({
      name: e.name,
      "club.definitionId": Number(e.definitionId),
      "club.assetId": Number(e.assetId),
      rating: e.rating,
    })),
  );
  console.groupEnd();
  return { collectionMatches, clubMatches, counts };
};

// EA concept entities (window.getAutoSbcConceptPlayers) are the EA-native source
// of truth for both market price and face stats. Index them by definitionId so
// a collection player (keyed by eaId == definitionId) can be joined to its real
// EA item. The index is rebuilt whenever the concept count changes.
let _collectionBookConceptIndex = null;
let _collectionBookConceptIndexSize = -1;
const collectionBookGetConceptIndex = () => {
  try {
    const list =
      (typeof window.getAutoSbcConceptPlayers === "function" &&
        window.getAutoSbcConceptPlayers()) ||
      window.autoSbcConceptPlayers ||
      [];
    if (
      _collectionBookConceptIndex &&
      _collectionBookConceptIndexSize === list.length
    ) {
      return _collectionBookConceptIndex;
    }
    const map = new Map();
    for (const item of list) {
      const defId = Number(item?.definitionId);
      if (Number.isFinite(defId) && defId > 0 && !map.has(defId)) {
        map.set(defId, item);
      }
    }
    _collectionBookConceptIndex = map;
    _collectionBookConceptIndexSize = list.length;
    return map;
  } catch {
    return _collectionBookConceptIndex || new Map();
  }
};

// Market price for a collection player, using EA's own data only (no network /
// HTML fetch). Prefers pricing the real EA concept entity via getPrice — which
// returns the cached price if it is there — then falls back to the entity's EA
// market data, then to a direct definitionId lookup in the EA price cache.
// Returns a number, or null when the price is unknown.
// Pull a positive price out of an EA UTValueBandVO (getPriceLimits) regardless
// of the obfuscated getter/field names by scanning its numeric values and
// taking the smallest positive one (the min bid limit).
const collectionBookReadPriceBand = (band) => {
  if (!band || typeof band !== "object") return null;
  const candidates = [];
  try {
    if (typeof band.getMinValue === "function") candidates.push(band.getMinValue());
    if (typeof band.getStartValue === "function") candidates.push(band.getStartValue());
  } catch {}
  for (const value of Object.values(band)) {
    if (typeof value === "number") candidates.push(value);
  }
  const positives = candidates
    .map(Number)
    .filter((n) => Number.isFinite(n) && n > 0);
  return positives.length ? Math.min(...positives) : null;
};

const collectionBookGetPrice = (player) => {
  const defId = Number(player?.eaId);
  if (!Number.isFinite(defId) || defId <= 0) return null;
  try {
    const concept = collectionBookGetConceptIndex().get(defId);
    if (concept) {
      if (typeof getPrice === "function") {
        const p = getPrice(concept);
        if (Number.isFinite(Number(p)) && Number(p) > 0) return Number(p);
      }
      // EA-native market value: getMarketAverage()/_marketAverage (defaults to
      // -1 when unknown).
      const marketAverage =
        typeof concept.getMarketAverage === "function"
          ? Number(concept.getMarketAverage())
          : Number(concept._marketAverage ?? concept.marketAverage);
      if (Number.isFinite(marketAverage) && marketAverage > 0) {
        return marketAverage;
      }
      // EA-native price limits band (getPriceLimits()/_itemPriceLimits).
      const band =
        (typeof concept.getPriceLimits === "function" &&
          concept.getPriceLimits()) ||
        concept._itemPriceLimits ||
        concept.itemPriceLimits ||
        null;
      const bandPrice = collectionBookReadPriceBand(band);
      if (bandPrice != null) return bandPrice;
    }
    if (typeof getPrice === "function") {
      const p = getPrice({ definitionId: defId, concept: true });
      if (Number.isFinite(Number(p)) && Number(p) > 0) return Number(p);
    }
    if (typeof getPriceItems === "function") {
      const items = getPriceItems() || {};
      const entry = items[defId] || items[String(defId)];
      const p = entry?.price;
      if (Number.isFinite(Number(p)) && Number(p) > 0) return Number(p);
    }
  } catch {}
  return null;
};

// Players whose price we've already asked fut.gg for, so a section re-render
// doesn't re-queue the same definitionIds.
const _collectionBookPriceRequested = new Set();

// For any collection players missing an EA price, fetch a fut.gg price so the
// card doesn't show 0. Prefers the real concept entity (correct search type),
// otherwise falls back to a concept-like stub keyed by definitionId. Runs the
// shared fetchPlayerPrices pipeline (which populates the EA price cache that
// collectionBookGetPrice reads). Returns the number of players queued.
const collectionBookFetchMissingPrices = async (players) => {
  if (typeof fetchPlayerPrices !== "function") return 0;
  const index = collectionBookGetConceptIndex();
  const toFetch = [];
  for (const p of players || []) {
    const defId = Number(p?.eaId);
    if (!Number.isFinite(defId) || defId <= 0) continue;
    if (_collectionBookPriceRequested.has(defId)) continue;
    if (collectionBookGetPrice(p) != null) continue;
    _collectionBookPriceRequested.add(defId);
    const concept = index.get(defId);
    toFetch.push(concept || { definitionId: defId, concept: true });
  }
  if (!toFetch.length) return 0;
  try {
    await fetchPlayerPrices(toFetch, {
      throttleProfile: "concept",
      suppressNotification: true,
      waitForCompletion: true,
    });
  } catch (err) {
    console.warn("[CollectionBook] fut.gg price fetch failed", err);
  }
  return toFetch.length;
};

// EA-native face stats (6 values, FUT card order) for a collection player,
// sourced from the matching concept entity. Returns [] when unavailable so the
// caller can fall back to a stat-less card.
const collectionBookGetFaceStats = (eaId) => {
  const defId = Number(eaId);
  if (!Number.isFinite(defId) || defId <= 0) return [];
  try {
    const concept = collectionBookGetConceptIndex().get(defId);
    if (!concept) return [];
    const attrs =
      (typeof concept.getAttributes === "function" && concept.getAttributes()) ||
      concept.attributes ||
      concept.attributeArray ||
      [];
    if (Array.isArray(attrs) && attrs.length >= 6) {
      return attrs.slice(0, 6).map((v) => Number(v) || 0);
    }
  } catch {}
  return [];
};

// Return a REAL EA item entity for a collection player (keyed by
// eaId == definitionId), so cards render with the game's own rating + face
// stats instead of the fut.gg metadata (which frequently has overall == null,
// producing 0-rating / 0-stat concept cards). Preference order:
//   1. the live club item (owned copy) from the EA club repo,
//   2. the concept-pool entity (EA-native, already indexed by definitionId).
// Returns null when neither is available so the caller can fall back to the
// synthetic payload path.
const collectionBookGetItemEntity = (eaId) => {
  const defId = Number(eaId);
  if (!Number.isFinite(defId) || defId <= 0) return null;

  // 1. Live club item — the actual owned card, full stats + correct rating.
  try {
    const collection =
      services?.Item?.itemDao?.itemRepo?.club?.items?._collection;
    if (collection && typeof collection === "object") {
      for (const key of Object.keys(collection)) {
        const item = collection[key];
        if (item && Number(item.definitionId) === defId) {
          return item;
        }
      }
    }
  } catch {}

  // 2. Concept-pool entity — EA-native item with real face stats.
  try {
    const concept = collectionBookGetConceptIndex().get(defId);
    if (concept) return concept;
  } catch {}

  return null;
};


// Every collection player, de-duplicated by eaId, gathered from the cached
// per-collection player lists (populated by the prefetch). Used to build the
// rarity batches. Returns [] until at least one collection has been cached.
const collectionBookGetAllCachedPlayers = () => {
  const list = _collectionBookReadCache(COLLECTION_BOOK_LIST_KEY, 0) || [];
  const byEaId = new Map();
  for (const col of list) {
    const players = _collectionBookReadCache(
      COLLECTION_BOOK_PLAYERS_KEY(col.slug),
      0,
    );
    if (!Array.isArray(players)) continue;
    for (const p of players) {
      const id = Number(p?.eaId);
      if (!Number.isFinite(id) || id <= 0 || byEaId.has(id)) continue;
      byEaId.set(id, p);
    }
  }
  return Array.from(byEaId.values());
};

// Synthetic "batches" grouping every collected player by rarity type, so the
// book can be viewed one rarity at a time in addition to the fut.gg collections.
// Each batch mirrors the collection shape ({ slug, name, total, players }) with
// an isRarityBatch flag and a bundled players list (no network fetch needed).
const collectionBookBuildRarityBatches = () => {
  const players = collectionBookGetAllCachedPlayers();
  const groups = new Map();
  for (const p of players) {
    const rid = p?.rarityEaId == null ? "unknown" : p.rarityEaId;
    const key = `rarity:${rid}`;
    let g = groups.get(key);
    if (!g) {
      g = {
        slug: key,
        name: p?.rarityName || `Rarity ${rid}`,
        rarityEaId: rid,
        players: [],
      };
      groups.set(key, g);
    }
    g.players.push(p);
  }
  const batches = Array.from(groups.values()).map((g) => ({
    slug: g.slug,
    name: g.name,
    rarityEaId: g.rarityEaId,
    total: g.players.length,
    players: g.players,
    isRarityBatch: true,
  }));
  batches.sort((a, b) => b.total - a.total);
  return batches;
};

// Given a collection's players, compute per-player ownership + collection totals
// using the club as the source of truth.
const collectionBookComputeProgress = (players, ownedCounts) => {
  const counts = ownedCounts || collectionBookGetOwnedCounts();
  const clubCounts = collectionBookGetClubCounts();
  let owned = 0;
  const rows = (players || []).map((p) => {
    const copies = counts.get(Number(p.eaId)) || 0;
    // In the club right now vs merely seen before (persisted ownership cache).
    // Both render colourful (not concept); the counter colour distinguishes them.
    const inClub = (clubCounts.get(Number(p.eaId)) || 0) > 0;
    if (copies > 0) owned += 1;
    return {
      player: p,
      owned: copies > 0,
      inClub,
      copies,
      price: collectionBookGetPrice(p),
    };
  });
  // Sort each batch by price descending (unknown prices sink to the bottom).
  rows.sort((a, b) => (b.price ?? -1) - (a.price ?? -1));
  return { rows, owned, total: rows.length };
};

// --- new-player detection + notifications --------------------------------

// Persisted baseline of collection-player defIds already seen as owned, so we
// only notify when something NEW appears (not on the first club sync).
const COLLECTION_BOOK_SEEN_KEY = "collectionBook.ownedSeen.v1";

const _collectionBookReadSeen = () => {
  try {
    const raw = localStorage.getItem(COLLECTION_BOOK_SEEN_KEY);
    if (!raw) return null;
    const arr = JSON.parse(raw);
    return Array.isArray(arr) ? new Set(arr.map(Number)) : null;
  } catch {
    return null;
  }
};

const _collectionBookWriteSeen = (set) => {
  try {
    localStorage.setItem(COLLECTION_BOOK_SEEN_KEY, JSON.stringify([...set]));
  } catch {}
};

// Diff the currently-owned collection players against the persisted baseline.
// Returns [{ eaId, collection }] for players collected since the last sync.
// On the very first run it silently seeds the baseline (returns []).
const collectionBookDetectNewlyCollected = () => {
  // Membership + collection name come from the list cache (stale is fine —
  // collection membership is stable).
  const memberToCollection = _collectionBookMemberToCollection();
  if (!memberToCollection.size) return [];

  const counts = collectionBookGetOwnedCounts();
  const ownedMembers = [];
  for (const defId of counts.keys()) {
    if (memberToCollection.has(defId)) ownedMembers.push(defId);
  }

  const seen = _collectionBookReadSeen();
  if (!seen) {
    // First run: establish the baseline silently, don't notify.
    _collectionBookWriteSeen(new Set(ownedMembers));
    return [];
  }

  const newly = ownedMembers.filter((id) => !seen.has(id));
  if (newly.length) {
    for (const id of newly) seen.add(id);
    _collectionBookWriteSeen(seen);
  }
  return newly.map((id) => ({
    eaId: id,
    collection: memberToCollection.get(id),
  }));
};

// Build defId -> collection name from the (stale-ok) list cache. Collection
// membership is stable, so a stale list is fine.
const _collectionBookMemberToCollection = () => {
  const map = new Map();
  const list = _collectionBookReadCache(COLLECTION_BOOK_LIST_KEY, 0);
  if (!Array.isArray(list)) return map;
  for (const c of list) {
    for (const id of c.allPlayerItemEaIds || []) {
      const defId = Number(id);
      if (!map.has(defId)) map.set(defId, c.name);
    }
  }
  return map;
};

// Detect newly collected Collection Book players from an arbitrary set of item
// definitionIds (e.g. items just pulled in the unassigned fetch after a pack
// open), not just those already in the club. Updates the persisted baseline so
// the same player isn't re-notified when it later lands in the club. Skips
// entirely until the baseline exists (the club detection seeds it), to avoid a
// flood on the very first run.
const collectionBookDetectNewFromIds = (defIds) => {
  const memberToCollection = _collectionBookMemberToCollection();
  if (!memberToCollection.size) return [];

  const seen = _collectionBookReadSeen();
  if (!seen) return []; // baseline is established by collectionBookDetectNewlyCollected

  const newly = [];
  for (const raw of defIds || []) {
    const defId = Number(raw);
    if (
      Number.isFinite(defId) &&
      memberToCollection.has(defId) &&
      !seen.has(defId)
    ) {
      seen.add(defId);
      newly.push(defId);
    }
  }
  if (!newly.length) return [];
  _collectionBookWriteSeen(seen);
  return newly.map((id) => ({
    eaId: id,
    collection: memberToCollection.get(id),
  }));
};

// Scan a list of EA items (e.g. the unassigned fetch result) for newly
// collected Collection Book players and notify. Safe no-op when nothing new.
const collectionBookScanItems = (items) => {
  try {
    const defIds = (items || [])
      .map((it) =>
        Number(
          it?.definitionId ?? it?.resourceId ?? it?._staticData?.id ?? NaN,
        ),
      )
      .filter((n) => Number.isFinite(n) && n > 0);
    if (!defIds.length) return;
    const newly = collectionBookDetectNewFromIds(defIds);
    if (newly.length) collectionBookNotifyNewlyCollected(newly);
  } catch (err) {
    console.warn("[CollectionBook] item scan failed", err);
  }
};

// Resolve player display names for a set of eaIds from any cached players list.
const _collectionBookResolveNames = (ids) => {
  const want = new Set(ids.map(Number));
  const names = new Map();
  const list = _collectionBookReadCache(COLLECTION_BOOK_LIST_KEY, 0) || [];
  for (const c of list) {
    if (!want.size) break;
    const players = _collectionBookReadCache(
      COLLECTION_BOOK_PLAYERS_KEY(c.slug),
      0,
    );
    if (!Array.isArray(players)) continue;
    for (const p of players) {
      const id = Number(p.eaId);
      if (want.has(id)) {
        names.set(id, p.name || String(id));
        want.delete(id);
      }
    }
  }
  return names;
};

// Show an EA in-app notification for newly collected Collection Book players.
const collectionBookNotifyNewlyCollected = (newly) => {
  if (!newly?.length || typeof showNotification !== "function") return;
  const type =
    (typeof UINotificationType !== "undefined" && UINotificationType.POSITIVE) ||
    0;
  if (newly.length <= 3) {
    const names = _collectionBookResolveNames(newly.map((n) => n.eaId));
    for (const n of newly) {
      const nm = names.get(Number(n.eaId)) || `#${n.eaId}`;
      const where = n.collection ? ` (${n.collection})` : "";
      showNotification(`Collection Book: ${nm} collected!${where}`, type);
    }
  } else {
    showNotification(
      `Collection Book: ${newly.length} new players collected!`,
      type,
    );
  }
};

// Invoked whenever a club search runs. Recomputes progress from the club,
// notifies about any newly collected players, and asks the (optional)
// Collection Book view to refresh its counters/styling.
const collectionBookUpdateFromClub = () => {
  try {
    const newly = collectionBookDetectNewlyCollected();
    if (newly.length) collectionBookNotifyNewlyCollected(newly);
    if (typeof window.__collectionBookOnClubUpdate === "function") {
      window.__collectionBookOnClubUpdate(collectionBookGetOwnedCounts());
    }
  } catch (err) {
    console.warn("[CollectionBook] club update failed", err);
  }
};

try {
  window.collectionBookFetchList = collectionBookFetchList;
  window.collectionBookFetchPlayers = collectionBookFetchPlayers;
  window.collectionBookPrefetchAll = collectionBookPrefetchAll;
  window.collectionBookGetOwnedCounts = collectionBookGetOwnedCounts;
  window.collectionBookDebugOwnership = collectionBookDebugOwnership;
  window.collectionBookFetchOwnership = collectionBookFetchOwnership;
  window.collectionBookRecordOwnership = collectionBookRecordOwnership;
  window.collectionBookGetPrice = collectionBookGetPrice;
  window.collectionBookFetchMissingPrices = collectionBookFetchMissingPrices;
  window.collectionBookGetConceptIndex = collectionBookGetConceptIndex;
  window.collectionBookGetFaceStats = collectionBookGetFaceStats;
  window.collectionBookGetItemEntity = collectionBookGetItemEntity;
  window.collectionBookGetAllCachedPlayers = collectionBookGetAllCachedPlayers;
  window.collectionBookBuildRarityBatches = collectionBookBuildRarityBatches;
  window.collectionBookComputeProgress = collectionBookComputeProgress;
  window.collectionBookDetectNewlyCollected = collectionBookDetectNewlyCollected;
  window.collectionBookDetectNewFromIds = collectionBookDetectNewFromIds;
  window.collectionBookScanItems = collectionBookScanItems;
  window.collectionBookUpdateFromClub = collectionBookUpdateFromClub;
} catch {}
const refreshUnassignedPrices = async (items = [], refreshAll = false) => {
  if (!Array.isArray(items) || !items.length) return;

  const startedAt = Date.now();
  let processed = 0;
  let timedOut = 0;
  let failed = 0;

  const filtered = (items || []).filter((item) => {
    const price = getPrice(item);
    const isConceptLike = !!item?.concept || Number(item?.owners) === 0;
    const include = refreshAll || (!isConceptLike && price == null);
    return include;
  });

  const uniqueItemsWithoutPrice = Array.from(
    new Map(filtered.map((item) => [item.definitionId, item])).values(),
  );

  if (!uniqueItemsWithoutPrice.length) {
    return;
  }

  const uniqueSuffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const containerId = `unassigned-prices-progress-container-${uniqueSuffix}`;
  const progressBarId = `unassigned-prices-progress-bar-${uniqueSuffix}`;
  createProgressBar(progressBarId, containerId, "Refreshing Unassigned Prices");
  updateProgressBar(progressBarId, 0);

  const total = uniqueItemsWithoutPrice.length;

  const withTimeout = (promise, ms, label) => {
    let timeoutId;
    const timeoutPromise = new Promise((_, reject) => {
      timeoutId = setTimeout(() => reject(new Error(`Timeout: ${label}`)), ms);
    });
    return Promise.race([promise, timeoutPromise]).finally(() =>
      clearTimeout(timeoutId),
    );
  };

  const configuredBatchSize = Number(getSettings(0, 0, "futggPriceBatchSize"));
  const batchSize =
    Number.isFinite(configuredBatchSize) && configuredBatchSize > 0
      ? Math.min(50, Math.max(1, Math.floor(configuredBatchSize)))
      : 30;

  try {
    for (let idx = 0; idx < uniqueItemsWithoutPrice.length; idx += batchSize) {
      const batch = uniqueItemsWithoutPrice.slice(idx, idx + batchSize);
      try {
        if (typeof fetchPlayerPrices === "function") {
          // Batch refresh is significantly faster than sequential per-item lookup.
          await withTimeout(
            fetchPlayerPrices(batch, {
              waitForCompletion: true,
              suppressNotification: true,
            }),
            45000,
            `fetchPlayerPrices(batch ${idx / batchSize + 1})`,
          );
        } else {
          for (const item of batch) {
            const defId = item?.definitionId;
            await withTimeout(
              fetchLivePlayerPrice(item),
              25000,
              `fetchLivePlayerPrice(${defId})`,
            );
          }
        }

        try {
          getCurrentViewController()
            .getCurrentController()
            .leftController.renderView();
          getCurrentViewController()
            .getCurrentController()
            .rightController.currentController.renderView();
        } catch (error) {
          getCurrentViewController()
            .getCurrentController()
            .leftController.refreshList();
        }
      } catch (error) {
        const msg = String(error?.message || error);
        if (msg.includes("Timeout:")) {
          timedOut += batch.length;
        } else {
          failed += batch.length;
        }
      } finally {
        processed += batch.length;
        updateProgressBar(progressBarId, (processed / total) * 100);
      }
    }

    updateProgressBar(progressBarId, 100);
  } finally {
    removeProgressBar(containerId);
    const ms = Date.now() - startedAt;

  }
};
const SBC_QUEUE_HISTORY_LIMIT = 300;

const getQueueHistoryStorageKey = (panelKey) => `sbc.queueHistory.${panelKey}`;

const getQueueItemKey = (item) => {
  if (!item) return null;

  const itemId = Number(item?.id);
  if (Number.isFinite(itemId) && itemId > 0) {
    return `item:${itemId}`;
  }

  const tradeId = Number(item?._auction?.tradeId ?? item?._auction?.id);
  if (Number.isFinite(tradeId) && tradeId > 0) {
    return `trade:${tradeId}`;
  }

  return null;
};

const getQueuePendingKeySet = (panelKey) => {
  if (!window.__sbcQueueRuntime) {
    window.__sbcQueueRuntime = {};
  }
  if (!window.__sbcQueueRuntime[panelKey]) {
    window.__sbcQueueRuntime[panelKey] = {
      pendingBatches: 0,
      closeTimeoutId: null,
      stopRequested: false,
      stopHandlers: new Set(),
    };
  }

  const runtime = window.__sbcQueueRuntime[panelKey];
  if (!(runtime.pendingItemKeys instanceof Set)) {
    runtime.pendingItemKeys = new Set();
  }

  return runtime.pendingItemKeys;
};

const reserveQueuedItems = (panelKey, items = []) => {
  const pendingItemKeys = getQueuePendingKeySet(panelKey);
  const seenInThisCall = new Set();
  const queuedItems = [];
  let skippedCount = 0;

  (Array.isArray(items) ? items : []).forEach((item) => {
    const itemKey = getQueueItemKey(item);

    if (!itemKey) {
      queuedItems.push(item);
      return;
    }

    if (pendingItemKeys.has(itemKey) || seenInThisCall.has(itemKey)) {
      skippedCount += 1;
      return;
    }

    pendingItemKeys.add(itemKey);
    seenInThisCall.add(itemKey);
    queuedItems.push(item);
  });

  return { queuedItems, skippedCount };
};

const releaseQueuedItems = (panelKey, items = []) => {
  const pendingItemKeys = getQueuePendingKeySet(panelKey);
  (Array.isArray(items) ? items : []).forEach((item) => {
    const itemKey = getQueueItemKey(item);
    if (itemKey) {
      pendingItemKeys.delete(itemKey);
    }
  });
};

const readQueueHistory = (panelKey) => {
  try {
    const raw = localStorage.getItem(getQueueHistoryStorageKey(panelKey));
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
};

const writeQueueHistory = (panelKey, entries = []) => {
  try {
    localStorage.setItem(
      getQueueHistoryStorageKey(panelKey),
      JSON.stringify(entries),
    );
  } catch {}
};

const trimQueueHistoryEntries = (entries = []) => {
  if (!Array.isArray(entries) || !entries.length) return [];

  let rowCount = 0;
  const trimmed = [];

  for (let idx = entries.length - 1; idx >= 0; idx -= 1) {
    const entry = entries[idx];
    if (entry?.type === "row") {
      if (rowCount >= SBC_QUEUE_HISTORY_LIMIT) continue;
      rowCount += 1;
    }
    trimmed.push(entry);
  }

  return trimmed.reverse();
};

const appendQueueHistoryEntry = (panelKey, entry) => {
  const id =
    entry?.id ||
    `${panelKey}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const history = readQueueHistory(panelKey);
  history.push({ ...entry, id });
  const trimmed = trimQueueHistoryEntries(history);
  writeQueueHistory(panelKey, trimmed);
  return id;
};

const updateQueueHistoryEntry = (panelKey, id, patch = {}) => {
  if (!id) return;
  const history = readQueueHistory(panelKey);
  const index = history.findIndex((entry) => entry?.id === id);
  if (index < 0) return;

  history[index] = {
    ...history[index],
    ...patch,
    id,
  };

  const trimmed = trimQueueHistoryEntries(history);
  writeQueueHistory(panelKey, trimmed);
};

const createHistoryRow = ({ columns = [], statusColor = "" } = {}) => {
  const row = document.createElement("div");
  row.style.display = "grid";
  row.style.gridTemplateColumns = "2fr 1fr 1fr 1fr";
  row.style.gap = "0.5rem";
  row.style.alignItems = "center";

  const spans = [0, 1, 2, 3].map(() => document.createElement("span"));
  spans.forEach((span, idx) => {
    span.textContent = columns[idx] ?? "—";
    row.appendChild(span);
  });

  if (statusColor) {
    spans[3].style.color = statusColor;
  }

  return {
    row,
    col1Span: spans[0],
    col2Span: spans[1],
    col3Span: spans[2],
    statusSpan: spans[3],
  };
};

const restoreQueueHistoryRows = (panelKey, rowsRoot) => {
  if (!rowsRoot) return;
  const history = readQueueHistory(panelKey);
  if (!history.length) return;

  history.forEach((entry) => {
    if (entry?.type === "divider") {
      appendQueueBatchDivider(rowsRoot, entry.label || "Batch");
      return;
    }

    if (entry?.type === "row") {
      const { row } = createHistoryRow({
        columns: entry.columns,
        statusColor: entry.statusColor,
      });
      rowsRoot.appendChild(row);
    }
  });
};

const createOrGetQueueStatusPanel = ({ panelKey, title, headers }) => {
  const rootId = "sbc-status-stack-root";
  let root = document.getElementById(rootId);

  if (!root) {
    root = document.createElement("div");
    root.id = rootId;
    root.style.position = "fixed";
    root.style.right = "2rem";
    root.style.bottom = "1.5rem";
    root.style.zIndex = "9999";
    root.style.display = "flex";
    root.style.flexDirection = "column-reverse";
    root.style.gap = "0.75rem";
    root.style.alignItems = "flex-end";
    root.style.pointerEvents = "none";
    document.body.appendChild(root);
  }

  if (!window.__sbcQueueStatusPanels) {
    window.__sbcQueueStatusPanels = new Map();
  }
  if (!window.__sbcQueueRuntime) {
    window.__sbcQueueRuntime = {};
  }
  if (!window.__sbcQueueRuntime[panelKey]) {
    window.__sbcQueueRuntime[panelKey] = {
      pendingBatches: 0,
      closeTimeoutId: null,
      stopRequested: false,
      stopHandlers: new Set(),
    };
  }

  const existing = window.__sbcQueueStatusPanels.get(panelKey);
  if (existing?.container?.isConnected) {
    return existing;
  }

  const container = document.createElement("div");
  container.className = "quick-buy-squad-status sbc-status-instance";
  container.style.padding = "0.75rem";
  container.style.background = "rgba(17, 24, 39, 0.9)";
  container.style.border = "1px solid rgba(255, 255, 255, 0.15)";
  container.style.borderRadius = "10px";
  container.style.display = "flex";
  container.style.flexDirection = "column";
  container.style.gap = "0.35rem";
  container.style.maxHeight = "45vh";
  container.style.overflow = "hidden";
  container.style.minWidth = "320px";
  container.style.boxSizing = "border-box";
  container.style.boxShadow = "0 12px 24px rgba(0, 0, 0, 0.45)";
  container.style.position = "relative";
  container.style.pointerEvents = "auto";

  const closeButton = document.createElement("button");
  closeButton.type = "button";
  closeButton.textContent = "×";
  closeButton.setAttribute("aria-label", "Close status panel");
  closeButton.style.position = "absolute";
  closeButton.style.top = "0.35rem";
  closeButton.style.right = "0.5rem";
  closeButton.style.background = "transparent";
  closeButton.style.border = "none";
  closeButton.style.color = "#ffffff";
  closeButton.style.fontSize = "1.2rem";
  closeButton.style.cursor = "pointer";
  closeButton.style.lineHeight = "1";
  closeButton.style.padding = "0";

  const content = document.createElement("div");
  content.className = "quick-buy-squad-content";
  content.style.display = "flex";
  content.style.flexDirection = "column";
  content.style.gap = "0.35rem";
  content.style.overflowY = "auto";
  content.style.maxHeight = "420px";

  const footer = document.createElement("div");
  footer.className = "quick-buy-squad-footer";
  footer.style.marginTop = "0.5rem";
  footer.style.fontSize = "0.85rem";
  footer.style.opacity = "0.85";
  footer.style.minHeight = "1.2rem";
  footer.style.textAlign = "center";

  const titleBlock = document.createElement("div");
  titleBlock.textContent = title;
  titleBlock.style.fontWeight = "bold";
  titleBlock.style.marginBottom = "0.35rem";

  const headerRow = document.createElement("div");
  headerRow.style.display = "grid";
  headerRow.style.gridTemplateColumns = "2fr 1fr 1fr 1fr";
  headerRow.style.gap = "0.5rem";
  headerRow.style.fontWeight = "bold";
  headerRow.style.borderBottom = "1px solid rgba(255, 255, 255, 0.1)";
  headerRow.style.position = "sticky";
  headerRow.style.top = "0";
  headerRow.style.zIndex = "2";
  headerRow.style.background = "rgba(17, 24, 39, 0.96)";
  headerRow.style.padding = "0.2rem 0";
  headers.forEach((label) => {
    const span = document.createElement("span");
    span.textContent = label;
    headerRow.appendChild(span);
  });

  const rowsRoot = document.createElement("div");
  rowsRoot.className = "sbc-status-rows-root";
  rowsRoot.style.display = "flex";
  rowsRoot.style.flexDirection = "column";
  rowsRoot.style.gap = "0.35rem";

  const dispose = () => {
    try {
      window.__sbcQueueStatusPanels?.delete?.(panelKey);
      container.remove();
      if (root && !root.children.length) {
        root.remove();
      }
    } catch {}
  };

  closeButton.addEventListener("click", () => {
    requestQueueStop(panelKey);
  });
  content.append(titleBlock, headerRow, rowsRoot);
  container.append(closeButton, content, footer);
  root.appendChild(container);

  const panel = { container, content, footer, rowsRoot, dispose };
  window.__sbcQueueStatusPanels.set(panelKey, panel);
  restoreQueueHistoryRows(panelKey, rowsRoot);
  return panel;
};

const cancelQueueCloseCountdown = (panelKey) => {
  const runtime = window.__sbcQueueRuntime?.[panelKey];
  if (!runtime) return;
  if (runtime.closeTimeoutId) {
    clearTimeout(runtime.closeTimeoutId);
    runtime.closeTimeoutId = null;
  }
};

const isQueueStopRequested = (panelKey) =>
  window.__sbcQueueRuntime?.[panelKey]?.stopRequested === true;

const registerQueueStopHandler = (panelKey, handler) => {
  if (typeof handler !== "function") return () => {};

  const runtime = window.__sbcQueueRuntime?.[panelKey];
  if (!runtime) return () => {};

  runtime.stopHandlers ||= new Set();
  runtime.stopHandlers.add(handler);

  return () => {
    try {
      runtime.stopHandlers?.delete(handler);
    } catch {}
  };
};

const requestQueueStop = (panelKey) => {
  const runtime = window.__sbcQueueRuntime?.[panelKey];
  const panel = window.__sbcQueueStatusPanels?.get(panelKey);
  if (!runtime) return;

  runtime.stopRequested = true;
  cancelQueueCloseCountdown(panelKey);

  if (panel?.footer) {
    panel.footer.textContent = "Stopping...";
  }

  const handlers = Array.from(runtime.stopHandlers || []);
  handlers.forEach((handler) => {
    try {
      handler();
    } catch {}
  });

  panel?.dispose?.();
};

const queueSleep = (ms) =>
  new Promise((resolve) => {
    setTimeout(resolve, ms);
  });

const runCancellableDelay = async (
  panelKey,
  delayMs,
  footer,
  label = "Waiting",
) => {
  const total = Math.max(0, Number(delayMs) || 0);
  if (!total) return !isQueueStopRequested(panelKey);

  let remaining = total;
  while (remaining > 0) {
    if (isQueueStopRequested(panelKey)) {
      if (footer) footer.textContent = "Stopped";
      return false;
    }

    if (footer) {
      footer.textContent = `${label} ${Math.ceil(remaining / 1000)}s`;
    }

    const chunk = Math.min(250, remaining);
    await queueSleep(chunk);
    remaining -= chunk;
  }

  if (footer) {
    footer.textContent = "";
  }
  return !isQueueStopRequested(panelKey);
};

const scheduleQueueCloseCountdown = (panelKey, panel, seconds = 3) => {
  const runtime = window.__sbcQueueRuntime?.[panelKey];
  if (!runtime || !panel?.footer) return;

  cancelQueueCloseCountdown(panelKey);

  const tick = () => {
    if (!window.__sbcQueueRuntime?.[panelKey]) return;
    if (window.__sbcQueueRuntime[panelKey].pendingBatches > 0) {
      panel.footer.textContent = "";
      return;
    }

    if (seconds <= 0) {
      panel.dispose?.();
      return;
    }

    panel.footer.textContent = `Closing in ${seconds}s`;
    seconds -= 1;
    runtime.closeTimeoutId = setTimeout(tick, 1000);
  };

  tick();
};

const appendQueueBatchDivider = (rowsRoot, label) => {
  if (!rowsRoot) return;

  const divider = document.createElement("div");
  divider.style.display = "flex";
  divider.style.alignItems = "center";
  divider.style.gap = "0.5rem";
  divider.style.margin = "0.35rem 0";

  const leftLine = document.createElement("span");
  leftLine.style.flex = "1";
  leftLine.style.height = "1px";
  leftLine.style.background = "rgba(255, 255, 255, 0.18)";

  const text = document.createElement("span");
  text.textContent = label;
  text.style.fontSize = "0.75rem";
  text.style.opacity = "0.8";
  text.style.whiteSpace = "nowrap";

  const rightLine = document.createElement("span");
  rightLine.style.flex = "1";
  rightLine.style.height = "1px";
  rightLine.style.background = "rgba(255, 255, 255, 0.18)";

  divider.append(leftLine, text, rightLine);
  rowsRoot.appendChild(divider);
};

const appendQueueBatchDividerWithHistory = (panelKey, rowsRoot, label) => {
  appendQueueBatchDivider(rowsRoot, label);
  appendQueueHistoryEntry(panelKey, {
    type: "divider",
    label,
  });
};

const clearSoldItemsBeforeListing = async () => {
  if (typeof clearSoldItems !== "function") {
    return;
  }

  try {
    await clearSoldItems();
  } catch (error) {
    console.warn("[quickListItems] clearSoldItems failed", error);
  }
};

const fetchTransferListItemsForListing = async () => {
  await clearSoldItemsBeforeListing();

  if (typeof getTransferItems === "function") {
    const items = await getTransferItems();
    return Array.isArray(items) ? items : [];
  }

  if (typeof fetchTransferList === "function") {
    const items = await fetchTransferList();
    return Array.isArray(items) ? items : [];
  }

  if (services?.Item?.requestTransferItems) {
    return await new Promise((resolve, reject) => {
      try {
        services.Item.requestTransferItems().observe(null, (obs, event) => {
          try {
            obs?.unobserve?.(null);
            const items = event?.response?.items;
            resolve(Array.isArray(items) ? items : []);
          } catch (err) {
            reject(err);
          }
        });
      } catch (err) {
        reject(err);
      }
    });
  }

  return [];
};

const getTransferListCountForListing = async () => {
  const items = await fetchTransferListItemsForListing();
  return Array.isArray(items) ? items.length : 0;
};

const getTransferListIdentityKey = (item) => {
  if (!item) return null;

  const tradeId = Number(item?._auction?.tradeId ?? item?._auction?.id);
  if (Number.isFinite(tradeId) && tradeId > 0) {
    return `trade:${tradeId}`;
  }

  const itemId = Number(item?.id);
  if (Number.isFinite(itemId) && itemId > 0) {
    return `item:${itemId}`;
  }

  return null;
};

const isLikelyOnTransferList = (item) => {
  const tradeState = String(
    item?._auction?.tradeState || item?._auction?._tradeState || "",
  ).toLowerCase();

  if (
    tradeState === "active" ||
    tradeState === "expired" ||
    tradeState === "closed"
  ) {
    return true;
  }

  const tradeId = Number(item?._auction?.tradeId ?? item?._auction?.id);
  return Number.isFinite(tradeId) && tradeId > 0;
};

const setQuickListRowStopped = (row) => {
  if (!row?.statusSpan) return;
  const statusText = row.statusSpan.textContent;
  if (
    statusText === "Listed" ||
    statusText === "Failed" ||
    statusText === "No price" ||
    statusText === "Not tradable" ||
    statusText === "Price dropped (skipped)"
  ) {
    return;
  }

  row.statusSpan.textContent = "Stopped";
  row.statusSpan.style.color = "#f59e0b";
  updateQueueHistoryEntry("quick-list", row.historyId, {
    columns: [
      row.name,
      row.buyNowSpan?.textContent || "—",
      row.minSpan?.textContent || "—",
      "Stopped",
    ],
    statusColor: "#f59e0b",
  });
};

const setRefreshRowStopped = (row) => {
  if (!row?.statusSpan) return;
  const statusText = row.statusSpan.textContent;
  if (
    statusText === "Updated" ||
    statusText === "No price" ||
    statusText === "Error"
  ) {
    return;
  }

  row.statusSpan.textContent = "Stopped";
  row.statusSpan.style.color = "#f59e0b";
  updateQueueHistoryEntry("refresh-prices", row.historyId, {
    columns: [
      row.name,
      row.oldPriceSpan?.textContent || "—",
      row.newPriceSpan?.textContent || "—",
      "Stopped",
    ],
    statusColor: "#f59e0b",
  });
};

const quickListItems = async (
  items = [],
  {
    context = {},
    durationSeconds = 60 * 60,
    minDelayMs = 1000,
    maxDelayMs = 1000,
    suppressNotifications = false,
    min = -1,
    max = -1,
  } = {},
) => {
  const notify = (message, type) => {
    if (!suppressNotifications) showNotification(message, type);
  };

  if (!Array.isArray(items) || items.length === 0) {
    notify("No items to list", UINotificationType.NEGATIVE);
    return { success: false, reason: "noItems" };
  }

  const {
    queuedItems: uniqueQueuedItems,
    skippedCount: skippedAlreadyQueuedCount,
  } = reserveQueuedItems("quick-list", items);

  if (!uniqueQueuedItems.length) {
    notify(
      "Selected items are already queued for quick list",
      UINotificationType.NEUTRAL,
    );
    return {
      success: false,
      reason: "alreadyQueued",
      skipped: skippedAlreadyQueuedCount,
    };
  }

  if (skippedAlreadyQueuedCount > 0) {
    notify(
      `Skipped ${skippedAlreadyQueuedCount} already queued quick list item(s)`,
      UINotificationType.NEUTRAL,
    );
  }

  const {
    content: statusContent,
    footer: timerFooter,
    rowsRoot,
  } = createOrGetQueueStatusPanel({
    panelKey: "quick-list",
    title: "Quick List Items",
    headers: ["Item", "Buy Now", "Min", "Status"],
  });

  window.__sbcQueueRuntime["quick-list"].stopRequested = false;
  window.__sbcQueueRuntime["quick-list"].pendingBatches += 1;
  cancelQueueCloseCountdown("quick-list");

  const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
  const randomDelay = () => {
    const lo = clamp(Number(minDelayMs) || 1000, 0, 60000);
    const hi = clamp(Number(maxDelayMs) || 1000, lo, 60000);
    return lo + Math.floor(Math.random() * (hi - lo + 1));
  };

  let transferItemsSnapshot = [];
  try {
    transferItemsSnapshot = await fetchTransferListItemsForListing();
  } catch {}

  const knownTransferIdentityKeys = new Set(
    (transferItemsSnapshot || [])
      .map((item) => getTransferListIdentityKey(item))
      .filter(Boolean),
  );

  const isItemAlreadyOnTransferList = (item) => {
    const identityKey = getTransferListIdentityKey(item);
    if (identityKey && knownTransferIdentityKeys.has(identityKey)) {
      return true;
    }
    return isLikelyOnTransferList(item);
  };

  const rows = uniqueQueuedItems.map((item) => {
    const name = formatPlayerName(item);
    const {
      row,
      col2Span: buyNowSpan,
      col3Span: minSpan,
      statusSpan,
    } = createHistoryRow({ columns: [name, "—", "—", "Queued"] });

    rowsRoot.appendChild(row);

    const historyId = appendQueueHistoryEntry("quick-list", {
      type: "row",
      columns: [name, "—", "—", "Queued"],
      statusColor: "",
    });

    return {
      item,
      buyNowSpan,
      minSpan,
      statusSpan,
      historyId,
      name,
      onTransferList: isItemAlreadyOnTransferList(item),
    };
  });

  const stopRows = () => {
    rows.forEach(setQuickListRowStopped);
    timerFooter.textContent = "Stopped";
  };

  const unregisterStopHandler = registerQueueStopHandler(
    "quick-list",
    stopRows,
  );

  statusContent.scrollTop = statusContent.scrollHeight;

  // Move all tradable items to the transfer list first so this doesn't block
  // other processes while individual listings are processed one by one.
  const tradableRowsToMove = rows.filter(
    (row) => row?.item?.tradable !== false && !row?.onTransferList,
  );
  if (tradableRowsToMove.length) {
    try {
      const transferListCount = await getTransferListCountForListing();
      const availableSlots = Math.max(0, 100 - transferListCount);

      if (availableSlots <= 0) {
        notify(
          `Transfer list full (${transferListCount}/100) - skipping move to transfer list`,
          UINotificationType.NEUTRAL,
        );
      } else {
        const tradableItemsToMove = tradableRowsToMove.slice(0, availableSlots);
        if (tradableItemsToMove.length > 0) {
          services.Item.move(
            tradableItemsToMove.map((row) => row.item),
            5,
          );
          tradableItemsToMove.forEach((row) => {
            row.onTransferList = true;
            const identityKey = getTransferListIdentityKey(row.item);
            if (identityKey) {
              knownTransferIdentityKeys.add(identityKey);
            }
          });
        }
      }
    } catch (err) {
      console.warn("[quickListItems] bulk move to transfer list failed", err);
    }
  }

  let successCount = 0;

  const runBatch = async () => {
    let transferListCount = 0;
    try {
      transferListCount = await getTransferListCountForListing();
    } catch (err) {
      console.warn("[quickListItems] transfer list read failed", err);
      notify(
        "Failed to read transfer list - skipping listing",
        UINotificationType.NEGATIVE,
      );
      rows.forEach((row) => {
        if (row?.statusSpan?.textContent !== "Queued") return;
        row.statusSpan.textContent = "Transfer list read failed";
        row.statusSpan.style.color = "#f40727";
        updateQueueHistoryEntry("quick-list", row.historyId, {
          columns: [
            row.name,
            row.buyNowSpan?.textContent || "—",
            row.minSpan?.textContent || "—",
            "Transfer list read failed",
          ],
          statusColor: "#f40727",
        });
      });
      return {
        success: false,
        reason: "transferListReadFailed",
        listed: successCount,
        total: rows.length,
      };
    }

    if (transferListCount >= 100) {
      const queueNeedingSlots = rows.filter(
        (row) =>
          row?.statusSpan?.textContent === "Queued" && !row?.onTransferList,
      );
      if (queueNeedingSlots.length > 0) {
        notify(
          `Transfer list full (${transferListCount}/100) - only relisting existing transfer items`,
          UINotificationType.NEUTRAL,
        );
      }
    }

    if (isQueueStopRequested("quick-list")) {
      stopRows();
      return {
        success: false,
        reason: "stopped",
        listed: successCount,
        total: rows.length,
      };
    }

    appendQueueBatchDividerWithHistory(
      "quick-list",
      rowsRoot,
      `Quick List Batch • ${new Date().toLocaleTimeString()}`,
    );

    let currentTransferCount = transferListCount;

    for (let idx = 0; idx < rows.length; idx += 1) {
      const row = rows[idx];
      const {
        item,
        buyNowSpan,
        minSpan,
        statusSpan,
        historyId,
        name,
        onTransferList,
      } = row;

      if (!onTransferList && currentTransferCount >= 100) {
        statusSpan.textContent = "Transfer list full";
        statusSpan.style.color = "#f40727";
        updateQueueHistoryEntry("quick-list", historyId, {
          columns: [
            name,
            buyNowSpan?.textContent || "—",
            minSpan?.textContent || "—",
            "Transfer list full",
          ],
          statusColor: "#f40727",
        });
        continue;
      }

      if (isQueueStopRequested("quick-list")) {
        for (let stopIdx = idx; stopIdx < rows.length; stopIdx += 1) {
          setQuickListRowStopped(rows[stopIdx]);
        }
        timerFooter.textContent = "Stopped";
        return {
          success: false,
          reason: "stopped",
          listed: successCount,
          total: rows.length,
        };
      }

      statusSpan.textContent = "Listing...";
      statusSpan.style.color = "";
      updateQueueHistoryEntry("quick-list", historyId, {
        columns: [
          name,
          buyNowSpan.textContent || "—",
          minSpan.textContent || "—",
          "Listing...",
        ],
        statusColor: "",
      });

      const res = await quickListItem(item, {
        context,
        durationSeconds,
        suppressNotifications: true,
        min,
        max,
      });

      if (res?.success) {
        successCount += 1;
        if (!row.onTransferList) {
          row.onTransferList = true;
          currentTransferCount += 1;
        }
        buyNowSpan.textContent = Number(res.buyNow)?.toLocaleString?.() ?? "—";
        minSpan.textContent = Number(res.minPrice)?.toLocaleString?.() ?? "—";
        statusSpan.textContent = "Listed";
        statusSpan.style.color = "#07f468";
        updateQueueHistoryEntry("quick-list", historyId, {
          columns: [
            name,
            buyNowSpan.textContent || "—",
            minSpan.textContent || "—",
            "Listed",
          ],
          statusColor: "#07f468",
        });
      } else {
        const failedStatus =
          res?.reason === "notTradable"
            ? "Not tradable"
            : res?.reason === "priceDecreased"
              ? "Price dropped (skipped)"
              : res?.reason === "noPrice"
                ? "No price"
                : "Failed";
        statusSpan.textContent = failedStatus;
        statusSpan.style.color = "#f40727";
        updateQueueHistoryEntry("quick-list", historyId, {
          columns: [
            name,
            buyNowSpan.textContent || "—",
            minSpan.textContent || "—",
            failedStatus,
          ],
          statusColor: "#f40727",
        });
      }

      try {
        getControllerInstance()?.applyDataChange?.();
      } catch {}

      if (idx < rows.length - 1) {
        const delay = randomDelay();
        const shouldContinue = await runCancellableDelay(
          "quick-list",
          delay,
          timerFooter,
          "Next listing in",
        );
        if (!shouldContinue) {
          for (let stopIdx = idx + 1; stopIdx < rows.length; stopIdx += 1) {
            setQuickListRowStopped(rows[stopIdx]);
          }
          return {
            success: false,
            reason: "stopped",
            listed: successCount,
            total: rows.length,
          };
        }
      } else {
        timerFooter.textContent = "";
      }
    }

    if (!isQueueStopRequested("quick-list")) {
      notify(
        `Quick list complete: ${successCount}/${rows.length} listed`,
        successCount === rows.length
          ? UINotificationType.POSITIVE
          : UINotificationType.NEGATIVE,
      );
    }

    return { success: true, listed: successCount, total: rows.length };
  };

  if (!window.__sbcQueueRunners) {
    window.__sbcQueueRunners = {};
  }
  if (!window.__sbcQueueRunners.quickList) {
    window.__sbcQueueRunners.quickList = Promise.resolve();
  }

  const chained = window.__sbcQueueRunners.quickList.then(runBatch, runBatch);
  window.__sbcQueueRunners.quickList = chained.catch(() => {});

  try {
    return await chained;
  } catch (error) {
    console.error("quickListItems error", error);
    notify("Quick list encountered an error", UINotificationType.NEGATIVE);
    return { success: false, reason: "error", error };
  } finally {
    releaseQueuedItems("quick-list", uniqueQueuedItems);
    unregisterStopHandler();
    window.__sbcQueueRuntime["quick-list"].pendingBatches = Math.max(
      0,
      window.__sbcQueueRuntime["quick-list"].pendingBatches - 1,
    );
    if (window.__sbcQueueRuntime["quick-list"].pendingBatches === 0) {
      const panel = window.__sbcQueueStatusPanels?.get("quick-list");
      if (panel?.footer) {
        panel.footer.textContent = isQueueStopRequested("quick-list")
          ? "Stopped"
          : "";
      }
      window.__sbcQueueRuntime["quick-list"].stopRequested = false;
      scheduleQueueCloseCountdown("quick-list", panel, 3);
    }
  }
};

const parseValidPrice = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
};

const getKnownItemPrice = (item) => {
  if (!item) return null;

  const directPrice = parseValidPrice(item?.getPrice?.());
  if (directPrice !== null) return directPrice;

  try {
    if (typeof getPrice === "function") {
      const cached = parseValidPrice(getPrice(item));
      if (cached !== null) return cached;
    }
  } catch {}

  try {
    if (typeof getPriceItems === "function") {
      const priceRecord = getPriceItems()?.[item?.definitionId];
      const mapPrice = parseValidPrice(priceRecord?.price);
      if (mapPrice !== null) return mapPrice;
    }
  } catch {}

  return null;
};

const formatPriceCell = (value, fallback = "—") => {
  const parsed = parseValidPrice(value);
  return parsed === null ? fallback : parsed.toLocaleString();
};

const formatRefreshItemName = (item) => {
  if (!item) return "Unknown item";

  try {
    if (typeof formatPlayerName === "function") {
      const formatted = formatPlayerName(item);
      if (formatted && formatted !== "undefined") {
        return formatted;
      }
    }
  } catch {}

  return (
    item?._staticData?.name ||
    item?._staticData?.lastName ||
    item?.name ||
    item?.assetId ||
    item?.definitionId ||
    "Unknown item"
  );
};

const refreshLivePrice = async (item, { showUi = true, onCandidate } = {}) => {
  if (!item) {
    if (showUi) {
      showNotification("No item to refresh", UINotificationType.NEGATIVE);
    }
    return { success: false, reason: "noItem", oldPrice: null, newPrice: null };
  }

  if (showUi) {
    return refreshItemsLivePrices([item]);
  }

  const canFetchLive = typeof fetchLivePlayerPrice === "function";
  const canFetchBatch = typeof fetchPlayerPrices === "function";

  if (!canFetchLive && !canFetchBatch) {
    return {
      success: false,
      reason: "noFunction",
      oldPrice: getKnownItemPrice(item),
      newPrice: null,
    };
  }

  const oldPrice = getKnownItemPrice(item);
  let listing = null;

  if (canFetchLive) {
    listing = await fetchLivePlayerPrice(item, {
      suppressNotification: true,
      onCandidate,
    });
  }

  if (!listing && canFetchBatch) {
    await fetchPlayerPrices([item]);
  }

  const listingPrice = parseValidPrice(listing?._auction?.buyNowPrice);
  const newPrice = listingPrice ?? getKnownItemPrice(item);

  return {
    success: newPrice !== null,
    reason: newPrice === null ? "noPrice" : null,
    oldPrice,
    newPrice,
  };
};

const refreshItemsLivePrices = async (items = []) => {
  if (!Array.isArray(items) || items.length === 0) {
    showNotification("No items to refresh", UINotificationType.NEGATIVE);
    return { success: false, reason: "noItems" };
  }

  const {
    queuedItems: uniqueQueuedItems,
    skippedCount: skippedAlreadyQueuedCount,
  } = reserveQueuedItems("refresh-prices", items);

  if (!uniqueQueuedItems.length) {
    showNotification(
      "Selected items are already queued for price refresh",
      UINotificationType.NEUTRAL,
    );
    return {
      success: false,
      reason: "alreadyQueued",
      skipped: skippedAlreadyQueuedCount,
    };
  }

  if (skippedAlreadyQueuedCount > 0) {
    showNotification(
      `Skipped ${skippedAlreadyQueuedCount} already queued refresh item(s)`,
      UINotificationType.NEUTRAL,
    );
  }

  const {
    content: statusContent,
    footer: timerFooter,
    rowsRoot,
  } = createOrGetQueueStatusPanel({
    panelKey: "refresh-prices",
    title: "Refresh Item Prices",
    headers: ["Item", "Old Price", "New Price", "Status"],
  });

  window.__sbcQueueRuntime["refresh-prices"].stopRequested = false;
  window.__sbcQueueRuntime["refresh-prices"].pendingBatches += 1;
  cancelQueueCloseCountdown("refresh-prices");

  const rows = uniqueQueuedItems.map((item) => {
    const name = formatRefreshItemName(item);
    const initialOldPrice = getKnownItemPrice(item);
    const initialOldPriceText = formatPriceCell(initialOldPrice);

    const {
      row,
      col2Span: oldPriceSpan,
      col3Span: newPriceSpan,
      statusSpan,
    } = createHistoryRow({
      columns: [name, initialOldPriceText, "—", "Queued"],
    });

    rowsRoot.appendChild(row);

    const historyId = appendQueueHistoryEntry("refresh-prices", {
      type: "row",
      columns: [name, initialOldPriceText, "—", "Queued"],
      statusColor: "",
    });

    return {
      item,
      oldPriceSpan,
      newPriceSpan,
      statusSpan,
      historyId,
      name,
      initialOldPrice,
    };
  });

  const stopRows = () => {
    rows.forEach(setRefreshRowStopped);
    timerFooter.textContent = "Stopped";
  };

  const unregisterStopHandler = registerQueueStopHandler(
    "refresh-prices",
    stopRows,
  );

  statusContent.scrollTop = statusContent.scrollHeight;

  let refreshedCount = 0;
  let failedCount = 0;

  const configuredRefreshBatchSize = Number(
    getSettings(0, 0, "futggPriceBatchSize"),
  );
  const refreshBatchSize =
    Number.isFinite(configuredRefreshBatchSize) && configuredRefreshBatchSize > 0
      ? Math.min(50, Math.max(1, Math.floor(configuredRefreshBatchSize)))
      : 30;

  const runBatch = async () => {
    if (isQueueStopRequested("refresh-prices")) {
      stopRows();
      return {
        success: false,
        reason: "stopped",
        refreshed: refreshedCount,
        failed: failedCount,
        total: rows.length,
      };
    }

    appendQueueBatchDividerWithHistory(
      "refresh-prices",
      rowsRoot,
      `Refresh Batch • ${new Date().toLocaleTimeString()}`,
    );

    for (let idx = 0; idx < rows.length; idx += refreshBatchSize) {
      const batchRows = rows.slice(idx, idx + refreshBatchSize);

      if (isQueueStopRequested("refresh-prices")) {
        for (let stopIdx = idx; stopIdx < rows.length; stopIdx += 1) {
          setRefreshRowStopped(rows[stopIdx]);
        }
        timerFooter.textContent = "Stopped";
        return {
          success: false,
          reason: "stopped",
          refreshed: refreshedCount,
          failed: failedCount,
          total: rows.length,
        };
      }

      batchRows.forEach(
        ({ oldPriceSpan, newPriceSpan, statusSpan, historyId, name }, batchIdx) => {
          statusSpan.textContent = "Searching...";
          statusSpan.style.color = "";
          newPriceSpan.textContent = "Searching...";
          updateQueueHistoryEntry("refresh-prices", historyId, {
            columns: [
              name,
              oldPriceSpan.textContent || "—",
              "Searching...",
              `Searching... (${idx + batchIdx + 1}/${rows.length})`,
            ],
            statusColor: "",
          });
        },
      );

      timerFooter.textContent = `Refreshing ${Math.min(
        idx + batchRows.length,
        rows.length,
      )}/${rows.length}`;

      try {
        // Always hit the live transfer market search per item (falls back to
        // the fut.gg batch index only when no live listing is found) so
        // "Refresh Price" never just re-serves a stale cached value.
        await Promise.all(
          batchRows.map(({ item }) =>
            refreshLivePrice(item, { showUi: false }).catch((err) => {
              console.warn("[sbc] refreshLivePrice failed", item?.id, err);
              return null;
            }),
          ),
        );

        batchRows.forEach(
          ({
            item,
            oldPriceSpan,
            newPriceSpan,
            statusSpan,
            historyId,
            name,
            initialOldPrice,
          }) => {
            const oldPrice = parseValidPrice(initialOldPrice);
            const newPrice = getKnownItemPrice(item);

            oldPriceSpan.textContent = formatPriceCell(oldPrice);

            if (newPrice !== null) {
              newPriceSpan.textContent = formatPriceCell(newPrice);
              if (oldPrice !== null && newPrice !== oldPrice) {
                const diff = newPrice - oldPrice;
                const priceDiff = document.createElement("span");
                priceDiff.textContent =
                  diff > 0
                    ? `(+${diff.toLocaleString()})`
                    : `(${diff.toLocaleString()})`;
                priceDiff.style.fontSize = "0.85em";
                priceDiff.style.opacity = "0.8";
                newPriceSpan.appendChild(document.createElement("br"));
                newPriceSpan.appendChild(priceDiff);
              }

              statusSpan.textContent = "Updated";
              statusSpan.style.color = "#07f468";
              updateQueueHistoryEntry("refresh-prices", historyId, {
                columns: [
                  name,
                  oldPriceSpan.textContent || "—",
                  newPriceSpan.textContent || "—",
                  "Updated",
                ],
                statusColor: "#07f468",
              });
              refreshedCount += 1;
            } else {
              newPriceSpan.textContent = "—";
              statusSpan.textContent = "No price";
              statusSpan.style.color = "#f40727";
              updateQueueHistoryEntry("refresh-prices", historyId, {
                columns: [name, oldPriceSpan.textContent || "—", "—", "No price"],
                statusColor: "#f40727",
              });
              failedCount += 1;
            }
          },
        );
      } catch (err) {
        console.warn("[sbc] Error refreshing price batch", err);
        batchRows.forEach(({ oldPriceSpan, newPriceSpan, statusSpan, historyId, name, item }) => {
          newPriceSpan.textContent = "—";
          statusSpan.textContent = "Error";
          statusSpan.style.color = "#f40727";
          updateQueueHistoryEntry("refresh-prices", historyId, {
            columns: [name, oldPriceSpan.textContent || "—", "—", "Error"],
            statusColor: "#f40727",
          });
          console.warn("[sbc] Error updating price for item", item?.id, err);
          failedCount += 1;
        });
      }

      statusContent.scrollTop = statusContent.scrollHeight;

      try {
        getControllerInstance()?.applyDataChange?.();
      } catch {}

      if (idx + refreshBatchSize < rows.length) {
        const shouldContinue = await runCancellableDelay(
          "refresh-prices",
          60,
          timerFooter,
          "Next refresh in",
        );
        if (!shouldContinue) {
          for (
            let stopIdx = idx + refreshBatchSize;
            stopIdx < rows.length;
            stopIdx += 1
          ) {
            setRefreshRowStopped(rows[stopIdx]);
          }
          return {
            success: false,
            reason: "stopped",
            refreshed: refreshedCount,
            failed: failedCount,
            total: rows.length,
          };
        }
      }
    }

    timerFooter.textContent = "";

    if (!isQueueStopRequested("refresh-prices")) {
      showNotification(
        `Refreshed prices: ${refreshedCount}/${rows.length} updated`,
        refreshedCount === rows.length
          ? UINotificationType.POSITIVE
          : UINotificationType.NEGATIVE,
      );
    }

    return {
      success: true,
      refreshed: refreshedCount,
      failed: failedCount,
      total: rows.length,
    };
  };

  if (!window.__sbcQueueRunners) {
    window.__sbcQueueRunners = {};
  }
  if (!window.__sbcQueueRunners.refreshPrices) {
    window.__sbcQueueRunners.refreshPrices = Promise.resolve();
  }

  const chained = window.__sbcQueueRunners.refreshPrices.then(
    runBatch,
    runBatch,
  );
  window.__sbcQueueRunners.refreshPrices = chained.catch(() => {});

  try {
    return await chained;
  } catch (error) {
    console.error("refreshItemsLivePrices error", error);
    showNotification(
      "Price refresh encountered an error",
      UINotificationType.NEGATIVE,
    );
    return { success: false, reason: "error", error };
  } finally {
    releaseQueuedItems("refresh-prices", uniqueQueuedItems);
    unregisterStopHandler();
    window.__sbcQueueRuntime["refresh-prices"].pendingBatches = Math.max(
      0,
      window.__sbcQueueRuntime["refresh-prices"].pendingBatches - 1,
    );
    if (window.__sbcQueueRuntime["refresh-prices"].pendingBatches === 0) {
      const panel = window.__sbcQueueStatusPanels?.get("refresh-prices");
      if (panel?.footer) {
        panel.footer.textContent = isQueueStopRequested("refresh-prices")
          ? "Stopped"
          : "";
      }
      window.__sbcQueueRuntime["refresh-prices"].stopRequested = false;
      scheduleQueueCloseCountdown("refresh-prices", panel, 3);
    }
  }
};

window.quickListItems = quickListItems;
window.refreshItemsLivePrices = refreshItemsLivePrices;
window.refreshLivePrice = refreshLivePrice;
const getUnassignedActionGroups = () => {
  if (Array.isArray(window.UNASSIGNED_GROUPS)) {
    return window.UNASSIGNED_GROUPS;
  }
  return [
    { id: "sendToClub", label: "Send to club" },
    { id: "sendToTransferList", label: "Send to transfer list" },
    { id: "quickSell", label: "Quick sell" },
    { id: "listOnTransferMarket", label: "List on transfer market" },
    { id: "sendToStorage", label: "Send to storage" },
  ];
};

const getUnassignedActionLabels = () => {
  const groups = getUnassignedActionGroups();
  const map = new Map(groups.map((g) => [g.id, g.label]));
  map.set("doNothing", "No Rule Match");
  map.set("freeItems", "Free Items");
  return map;
};

const getUnassignedActionOrder = () => {
  const groups = getUnassignedActionGroups().map((g) => g.id);
  return ["freeItems", ...groups, "doNothing"];
};

const groupUnassignedItemsByRules = (items, rules, options = {}) => {
  const {
    includeFreeItems = true,
    includeDoNothing = true,
    matcherOptions = {},
  } = options;
  const normalizedRules = Array.isArray(rules) ? rules : [];
  const order = getUnassignedActionOrder();
  const labelMap = getUnassignedActionLabels();
  const buckets = new Map(order.map((action) => [action, []]));
  const matchesByRule = new Map();

  const addEntry = (action, item, rule, ruleIndex) => {
    if (!buckets.has(action)) {
      buckets.set(action, []);
    }
    const entry = { item, rule, ruleIndex };
    buckets.get(action).push(entry);

    if (ruleIndex != null && ruleIndex >= 0) {
      if (!matchesByRule.has(ruleIndex)) {
        matchesByRule.set(ruleIndex, []);
      }
      matchesByRule.get(ruleIndex).push(entry);
    }
  };

  (items || []).forEach((item) => {
    if (!item) return;

    if (item?.isFreeCoins?.() || item?.isFreePack?.()) {
      if (includeFreeItems) {
        addEntry("freeItems", item, null, -1);
      }
      return;
    }

    let matched = false;
    for (let i = 0; i < normalizedRules.length; i += 1) {
      const rule = normalizedRules[i];
      if (rule?.enabled === false) continue;
      if (matchesUnassignedRule(item, rule, matcherOptions)) {
        addEntry(rule.action || "sendToClub", item, rule, i);
        matched = true;
        break;
      }
    }

    if (!matched && includeDoNothing) {
      addEntry("doNothing", item, null, -1);
    }
  });

  const sections = order
    .map((action) => {
      const entries = buckets.get(action) || [];
      const groupedItems = entries.map((entry) => entry.item).filter(Boolean);
      return {
        action,
        label: labelMap.get(action) || action,
        entries,
        items: groupedItems,
      };
    })
    .filter((section) => section.items.length > 0);

  return {
    order,
    labelMap,
    buckets,
    matchesByRule,
    sections,
  };
};
const getUnassignedHistoryEntries = () => {
  if (!window.__unassignedHistoryEntries) {
    try {
      const raw = localStorage.getItem("unassignedHistoryEntries");
      window.__unassignedHistoryEntries = raw ? JSON.parse(raw) : [];
    } catch {
      window.__unassignedHistoryEntries = [];
    }
  }
  return window.__unassignedHistoryEntries;
};

const saveUnassignedHistoryEntries = (entries) => {
  try {
    localStorage.setItem(
      "unassignedHistoryEntries",
      JSON.stringify(entries || []),
    );
  } catch {}
};

const clearUnassignedHistoryEntries = () => {
  window.__unassignedHistoryEntries = [];
  saveUnassignedHistoryEntries([]);
};

const appendUnassignedHistoryRows = (entries, timestamp) => {
  if (!Array.isArray(entries) || !entries.length) return;

  const localizeAndTrimName = (value) => {
    if (typeof value !== "string") return "";
    const raw = value.trim();
    if (!raw) return "";
    try {
      const localized = services?.Localization?.localize?.(raw);
      if (typeof localized === "string" && localized.trim()) {
        return localized.trim();
      }
    } catch {}
    return raw;
  };

  const formatName = (item) => {
    const staticData = item?._staticData;
    const isPlayerItem =
      (typeof item?.isPlayer === "function" && item.isPlayer()) ||
      item?.isPlayer === true;

    const staticName = localizeAndTrimName(
      staticData?.name || staticData?.knownAs || "",
    );

    if (isPlayerItem && typeof staticData?.getFullName === "function") {
      const fullName = localizeAndTrimName(staticData.getFullName());
      if (fullName) {
        return fullName;
      }
    }

    const fullNameFallback =
      typeof staticData?.getFullName === "function"
        ? localizeAndTrimName(staticData.getFullName())
        : "";

    return (
      staticName ||
      fullNameFallback ||
      localizeAndTrimName(staticData?.lastName || "") ||
      localizeAndTrimName(item?.name || "") ||
      item?.definitionId ||
      "Unknown"
    );
  };

  const formatType = (item) => {
    if (typeof item?.getSearchType === "function") {
      const searchType = item.getSearchType();
      return String(searchType || "—");
    }
    return "—";
  };

  const formatPrice = (item) => {
    const price = Number(getPrice(item));
    return Number.isFinite(price) && price > 0 ? price.toLocaleString() : "—";
  };

  const getAssetId = (item) =>
    item?._metaData?.id ?? item?.assetId ?? item?.definitionId ?? null;

  const isTradableItem = (item) =>
    item?.tradable === true ||
    (typeof item?.isTradeable === "function" && item.isTradeable());

  const historyEntries = getUnassignedHistoryEntries();
  const nowLabel = timestamp;
  const nowMs = Date.now();

  entries.forEach(({ item, action, ruleNumber, ruleColor }) => {
    const assetId = getAssetId(item);
    const rating = item?.rating ?? item?._staticData?.rating ?? null;
    const rarityLabel = getItemRarityLabel(item);
    const isDuplicate =
      Number(item?.duplicateId ?? 0) > 0 || item?.isDuplicate?.();
    const isFodderValue =
      typeof isFodder === "function" ? isFodder(item) : false;
    const isTradableValue = isTradableItem(item);
    const priceValue = Number(getPrice(item));

    const nextEntry = {
      timestamp: nowMs,
      timestampLabel: nowLabel,
      ruleNumber: ruleNumber ?? null,
      action: action || null,
      name: formatName(item),
      type: formatType(item),
      assetId,
      rating: rating ?? null,
      price: Number.isFinite(priceValue) ? priceValue : null,
      priceDisplay: formatPrice(item),
      rarityLabel,
      isTradable: Boolean(isTradableValue),
      isFodder: Boolean(isFodderValue),
      isDuplicate: Boolean(isDuplicate),
      ruleColor: ruleColor || null,
    };

    if (assetId != null) {
      const existingIndex = historyEntries.findIndex(
        (existing) => existing?.assetId != null && existing.assetId == assetId,
      );
      if (existingIndex >= 0) {
        historyEntries[existingIndex] = {
          ...historyEntries[existingIndex],
          ...nextEntry,
        };
        return;
      }
    }

    historyEntries.push(nextEntry);
  });

  if (historyEntries.length > 300) {
    historyEntries.splice(0, historyEntries.length - 300);
  }

  saveUnassignedHistoryEntries(historyEntries);
};

const getUnassignedHistoryState = () => {
  return {
    entries: getUnassignedHistoryEntries(),
  };
};

const RECENT_SPECIALS_MAX = 10;
const RECENT_SPECIALS_STRIP_ID = "autosbc-recent-specials-strip";
const RECENT_SPECIALS_TRACK_ID = "autosbc-recent-specials-track";
const RECENT_SPECIALS_TITLE_ID = "autosbc-recent-specials-title";
const RECENT_SPECIALS_TOGGLE_ID = "autosbc-recent-specials-toggle";
const RECENT_SPECIALS_UNASSIGNED_STORAGE_KEY =
  "autoSbcRecentPackedSpecialsUnassigned.v1";
const RECENT_SPECIALS_COLLAPSED_STORAGE_KEY =
  "autoSbcRecentPackedSpecialsCollapsed.v1";
const RECENT_SPECIALS_TIMEAGO_REFRESH_MS = 60 * 1000;
const RECENT_SPECIALS_SNAKE_STAGGER_MS = 36;
let recentSpecialsClubReadyPromise = null;
let recentClubSpecialsLoadPromise = null;
let recentSpecialsTimeAgoIntervalId = null;

const getRecentSpecialEntryKey = (item, fallbackSeed = "") => {
  const itemId = Number(item?.id);
  if (Number.isFinite(itemId) && itemId > 0) {
    return `item-${itemId}`;
  }

  const definitionId = Number(item?.definitionId);
  if (Number.isFinite(definitionId) && definitionId > 0) {
    return `def-${definitionId}-${fallbackSeed || "0"}`;
  }

  return `unknown-${fallbackSeed || Date.now()}`;
};

const isRecentPackedSpecialsEnabled = () => {
  if (typeof getSettings !== "function") {
    return true;
  }
  return getSettings(0, 0, "showRecentPackedSpecials") !== false;
};

const ensureRecentSpecialsStyles = () => {
  if (document.getElementById("autosbc-recent-specials-style")) return;
  const style = document.createElement("style");
  style.id = "autosbc-recent-specials-style";
  style.textContent = `
    #${RECENT_SPECIALS_STRIP_ID} {
      position: fixed;
      left: 8px;
      right: 8px;
      bottom: 8px;
      z-index: 9998;
      pointer-events: none;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }
    #${RECENT_SPECIALS_STRIP_ID}.is-hidden {
      display: none;
    }
    #${RECENT_SPECIALS_STRIP_ID}.is-collapsed #${RECENT_SPECIALS_TRACK_ID} {
      display: none;
      pointer-events: none;
    }
    #${RECENT_SPECIALS_STRIP_ID}.is-collapsed #${RECENT_SPECIALS_TOGGLE_ID} {
      opacity: 0.9;
    }
    #${RECENT_SPECIALS_TRACK_ID} {
      --autosbc-card-count: 10;
      --autosbc-recent-card-width: 154px;
      --autosbc-overlap: 74px;
      --autosbc-card-step: calc(var(--autosbc-recent-card-width) - var(--autosbc-overlap));
      --autosbc-natural-track-width: calc(var(--autosbc-recent-card-width) + ((var(--autosbc-card-count) - 1) * var(--autosbc-card-step)) + 16px);
      --autosbc-track-width: min(calc(100vw - 16px), var(--autosbc-natural-track-width));
      pointer-events: auto;
      display: flex;
      align-items: flex-end;
      gap: 0;
      width: var(--autosbc-track-width);
      max-width: var(--autosbc-track-width);
      overflow: hidden;
      padding: 8px;
      border-radius: 10px;
      background: rgba(8, 11, 18, 0.82);
      border: 1px solid rgba(255, 255, 255, 0.12);
      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
      backdrop-filter: blur(6px);
    }
    #${RECENT_SPECIALS_TITLE_ID} {
      pointer-events: auto;
      display: inline-flex;
      align-items: center;
      gap: 8px;
      margin-bottom: 4px;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.3px;
      color: rgba(255, 255, 255, 0.9);
      text-transform: uppercase;
      text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
    }
    #${RECENT_SPECIALS_TITLE_ID} .autosbc-recent-specials-title-text {
      pointer-events: none;
    }
    #${RECENT_SPECIALS_TOGGLE_ID} {
      pointer-events: auto;
      border: 1px solid rgba(255, 255, 255, 0.22);
      background: rgba(14, 20, 34, 0.86);
      color: rgba(255, 255, 255, 0.94);
      font-size: 10px;
      font-weight: 700;
      line-height: 1;
      padding: 3px 7px;
      border-radius: 999px;
      cursor: pointer;
      text-transform: uppercase;
      letter-spacing: 0.35px;
    }
    #${RECENT_SPECIALS_TOGGLE_ID}:hover {
      background: rgba(21, 30, 50, 0.95);
    }
    .autosbc-recent-special-card {
      width: var(--autosbc-recent-card-width);
      min-width: var(--autosbc-recent-card-width);
      overflow: visible;
      transform: translateX(0) scale(1);
      opacity: 1;
      transition: transform 560ms cubic-bezier(0.22, 0.61, 0.36, 1), opacity 520ms ease;
      will-change: transform, opacity;
      transition-delay: 0ms;
    }
    .autosbc-recent-special-meta {
      margin-top: 2px;
      text-align: center;
      font-size: 12px;
      font-weight: 600;
      letter-spacing: 0.2px;
      color: rgba(255, 255, 255, 0.9);
      text-shadow: 0 1px 2px rgba(0, 0, 0, 0.45);
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .autosbc-recent-special-card + .autosbc-recent-special-card {
      margin-left: calc(-1 * var(--autosbc-overlap));
    }
    .autosbc-recent-special-card > * {
      opacity: 1 !important;
      filter: none !important;
      max-width: 100%;
    }
    .autosbc-recent-special-card img,
    .autosbc-recent-special-card canvas {
      max-width: 100% !important;
      height: auto !important;
    }
    .autosbc-recent-special-card .ut-item-player-state-indicator-view.loan {
      background: #38c172;
      color: #04150c;
    }
    .autosbc-recent-special-card .ut-item-player-state-indicator-view.loan.cb-counter-seen {
      background: #e3342f;
      color: #fff;
    }
    .autosbc-recent-special-card.is-enter {
      transform: translateY(46px) scale(0.96);
      opacity: 0;
    }
    .autosbc-recent-special-card.is-enter-active {
      transform: translateY(0) scale(1);
      opacity: 1;
    }
    .autosbc-recent-special-card.is-exit {
      transform: translateY(46px) scale(0.96);
      opacity: 0;
    }
    .autosbc-recent-special-empty {
      color: rgba(255, 255, 255, 0.85);
      font-size: 12px;
      letter-spacing: 0.2px;
      white-space: nowrap;
    }
  `;
  document.head.appendChild(style);
};

const ensureRecentSpecialsStripRoot = () => {
  if (!document?.body) {
    return null;
  }

  ensureRecentSpecialsStyles();

  let root = document.getElementById(RECENT_SPECIALS_STRIP_ID);
  if (!root) {
    root = document.createElement("div");
    root.id = RECENT_SPECIALS_STRIP_ID;

    const title = document.createElement("div");
    title.id = RECENT_SPECIALS_TITLE_ID;
    const titleText = document.createElement("span");
    titleText.className = "autosbc-recent-specials-title-text";
    titleText.textContent = "HISTORY";

    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.id = RECENT_SPECIALS_TOGGLE_ID;
    toggle.textContent = "Collapse";
    toggle.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const nextCollapsed = !isRecentSpecialsCollapsed();
      setRecentSpecialsCollapsed(nextCollapsed);
      renderRecentSpecialsStrip({ animatedKeys: new Set() });
    });

    title.appendChild(titleText);
    title.appendChild(toggle);
    root.appendChild(title);

    const track = document.createElement("div");
    track.id = RECENT_SPECIALS_TRACK_ID;
    root.appendChild(track);
    document.body.appendChild(root);
  }

  let title = document.getElementById(RECENT_SPECIALS_TITLE_ID);
  if (!title) {
    title = document.createElement("div");
    title.id = RECENT_SPECIALS_TITLE_ID;
    const titleText = document.createElement("span");
    titleText.className = "autosbc-recent-specials-title-text";
    titleText.textContent = "HISTORY";

    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.id = RECENT_SPECIALS_TOGGLE_ID;
    toggle.textContent = "Collapse";
    toggle.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const nextCollapsed = !isRecentSpecialsCollapsed();
      setRecentSpecialsCollapsed(nextCollapsed);
      renderRecentSpecialsStrip({ animatedKeys: new Set() });
    });

    title.appendChild(titleText);
    title.appendChild(toggle);
    root.insertBefore(title, root.firstChild || null);
  }

  const existingToggle = document.getElementById(RECENT_SPECIALS_TOGGLE_ID);
  if (!existingToggle && title) {
    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.id = RECENT_SPECIALS_TOGGLE_ID;
    toggle.textContent = "Collapse";
    toggle.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      const nextCollapsed = !isRecentSpecialsCollapsed();
      setRecentSpecialsCollapsed(nextCollapsed);
      renderRecentSpecialsStrip({ animatedKeys: new Set() });
    });
    title.appendChild(toggle);
  }

  let track = document.getElementById(RECENT_SPECIALS_TRACK_ID);
  if (!track) {
    track = document.createElement("div");
    track.id = RECENT_SPECIALS_TRACK_ID;
    root.appendChild(track);
  }

  return { root, track };
};

const loadRecentSpecialsCollapsed = () => {
  try {
    return localStorage.getItem(RECENT_SPECIALS_COLLAPSED_STORAGE_KEY) === "1";
  } catch {
    return false;
  }
};

const saveRecentSpecialsCollapsed = (collapsed) => {
  try {
    localStorage.setItem(
      RECENT_SPECIALS_COLLAPSED_STORAGE_KEY,
      collapsed ? "1" : "0",
    );
  } catch {}
};

const isRecentSpecialsCollapsed = () =>
  !!window.__autoSbcRecentSpecialsCollapsed;

const setRecentSpecialsCollapsed = (collapsed) => {
  window.__autoSbcRecentSpecialsCollapsed = !!collapsed;
  saveRecentSpecialsCollapsed(!!collapsed);
};

const isSpecialPlayerItem = (item) => {
  if (!item) return false;
  const isPlayer =
    (typeof item?.isPlayer === "function" && item.isPlayer()) ||
    item?.isPlayer === true;
  if (!isPlayer) return false;

  
    return !isFodder(item) && (item.isSpecial()) && getPrice(item)>=50000;
  

  // Fallback: treat non-gold-common (rareflag > 3) as non-fodder
  const rareFlag = Number(item?.rareflag ?? item?._staticData?.rareflag ?? 0);
  return Number.isFinite(rareFlag) && rareFlag > 3;
};

const getRecentSpecialDefinitionId = (entryOrItem) =>
  Number(
    entryOrItem?.definitionId ??
      entryOrItem?.item?.definitionId ??
      entryOrItem?._staticData?.id,
  ) || 0;

const toEpochMsFromUnknown = (value) => {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return 0;
  if (n < 1e11) return Math.floor(n * 1000); // likely seconds
  if (n > 1e15) return Math.floor(n / 1000); // likely microseconds
  return Math.floor(n); // likely milliseconds
};

const getEaRecencyTimestampMs = (item, fallbackMs = 0) => {
  const candidates = [
    item?.timestamp,
    item?._metaData?.timestamp,
    item?._staticData?.timestamp,
    item?.lastModified,
    item?._metaData?.lastModified,
  ];

  for (const raw of candidates) {
    const epochMs = toEpochMsFromUnknown(raw);
    if (epochMs > 0) return epochMs;
  }

  const fb = Number(fallbackMs);
  return Number.isFinite(fb) && fb > 0 ? fb : Date.now();
};

const formatRecentSpecialTimeAgo = (timestampMs) => {
  const seenMs = Number(timestampMs);
  if (!Number.isFinite(seenMs) || seenMs <= 0) {
    return "just now";
  }

  const elapsedMs = Math.max(0, Date.now() - seenMs);
  const totalMinutes = Math.floor(elapsedMs / (60 * 1000));
  if (totalMinutes <= 0) return "just now";
  if (totalMinutes < 60) {
    return `${totalMinutes}m ago`;
  }

  const totalHours = Math.floor(totalMinutes / 60);
  if (totalHours < 24) {
    return `${totalHours}h ago`;
  }

  const totalDays = Math.floor(totalHours / 24);
  return `${totalDays}d ago`;
};

const upsertRecentSpecialTimeAgoLabel = (wrapper, createdAt, isLeftMost = false) => {
  if (!wrapper) return;

  const ts = Number(createdAt || Date.now());
  wrapper.dataset.createdAt = String(ts);

  let meta = wrapper.querySelector(".autosbc-recent-special-meta");
  if (!meta) {
    meta = document.createElement("div");
    meta.className = "autosbc-recent-special-meta";
    wrapper.appendChild(meta);
  }

  meta.textContent = isLeftMost
    ? `seen ${formatRecentSpecialTimeAgo(ts)}`
    : formatRecentSpecialTimeAgo(ts);
};

const refreshRecentSpecialTimeAgoLabels = () => {
  const cards = document.querySelectorAll(
    `#${RECENT_SPECIALS_TRACK_ID} .autosbc-recent-special-card`,
  );
  cards.forEach((card, index) => {
    const createdAt = Number(card?.dataset?.createdAt || 0);
    upsertRecentSpecialTimeAgoLabel(card, createdAt, index === 0);
  });
};

const ensureRecentSpecialTimeAgoTicker = () => {
  if (recentSpecialsTimeAgoIntervalId) return;
  recentSpecialsTimeAgoIntervalId = setInterval(() => {
    refreshRecentSpecialTimeAgoLabels();
  }, RECENT_SPECIALS_TIMEAGO_REFRESH_MS);
};

const getClubCountsByDefinitionId = () => {
  const counts = new Map();
  const entries = Array.isArray(window.__clubPlayersEntries)
    ? window.__clubPlayersEntries
    : [];
  entries.forEach((entry) => {
    const defId = Number(entry?.definitionId);
    if (!Number.isFinite(defId) || defId <= 0) return;
    counts.set(defId, (counts.get(defId) || 0) + 1);
  });
  return counts;
};

const getPackedCountsByDefinitionId = (entries = []) => {
  const counts = new Map();
  (Array.isArray(entries) ? entries : []).forEach((entry) => {
    const defId = getRecentSpecialDefinitionId(entry);
    if (!Number.isFinite(defId) || defId <= 0) return;
    counts.set(defId, (counts.get(defId) || 0) + 1);
  });
  return counts;
};

const getRecentSpecialBottomLeftIndicator = (view) =>
  view?._bottomLeftStatusIndicator || null;

const hideRecentSpecialBottomLeftFallbackChip = (_view) => {};

const applyRecentSpecialSeenLabelFromViewState = (view) => {
  if (!view) return;
  applyRecentSpecialSeenLabel(
    view,
    view.__autoSbcRecentSeenEntry,
    view.__autoSbcRecentPackedCountsByDefinitionId,
  );
};

const ensureRecentSpecialSeenLabelRenderHook = (view) => {
  if (!view || view.__autoSbcSeenLabelRenderHooked) return;
  if (typeof view.render !== "function") return;

  const originalRender = view.render;
  view.render = function (...args) {
    const result = originalRender.apply(this, args);
    requestAnimationFrame(() => {
      applyRecentSpecialSeenLabelFromViewState(this);
    });
    return result;
  };
  view.__autoSbcSeenLabelRenderHooked = true;
};

const syncRecentSpecialSeenLabelViewState = (
  view,
  entry,
  packedCountsByDefinitionId,
) => {
  if (!view) return;
  view.__autoSbcRecentSeenEntry = entry;
  view.__autoSbcRecentPackedCountsByDefinitionId = packedCountsByDefinitionId;
  ensureRecentSpecialSeenLabelRenderHook(view);
};

const applyRecentSpecialSeenLabel = (view, entry, packedCountsByDefinitionId) => {
  if (!view) return;

  const defId = getRecentSpecialDefinitionId(entry);
  const clubCounts = getClubCountsByDefinitionId();
  const packedCount = Number(packedCountsByDefinitionId?.get?.(defId) || 0);
  const inClub = Number(clubCounts.get(defId) || 0) > 0;

  const applyOnce = () => {
    const indicator = getRecentSpecialBottomLeftIndicator(view);
    if (!indicator) return false;

    try {
      indicator.reset?.();
      const el = indicator.getRootElement?.() || indicator.__root;
      if (el) {
        el.classList.remove("cb-counter-seen");
      }
      hideRecentSpecialBottomLeftFallbackChip(view);
      return true;
    } catch {
      return true;
    }
  };

  if (applyOnce()) return;

  let attempts = 0;
  const retryApply = () => {
    attempts += 1;
    if (applyOnce()) return;
    if (attempts >= 6) return;
    requestAnimationFrame(retryApply);
  };
  requestAnimationFrame(retryApply);
};

const saveRecentSpecialsUnassignedEntries = (entries = []) => {
  try {
    const slim = (Array.isArray(entries) ? entries : [])
      .slice(0, RECENT_SPECIALS_MAX)
      .map((entry) => ({
        key: String(entry?.key || ""),
        definitionId: Number(getRecentSpecialDefinitionId(entry)) || 0,
        assetId: Number(entry?.item?._metaData?.id ?? entry?.assetId ?? 0) || 0,
        createdAt: Number(entry?.createdAt || Date.now()),
      }))
      .filter((entry) => entry.key && entry.definitionId > 0);

    localStorage.setItem(
      RECENT_SPECIALS_UNASSIGNED_STORAGE_KEY,
      JSON.stringify(slim),
    );
  } catch {}
};

const loadRecentSpecialsUnassignedEntries = () => {
  try {
    const raw = localStorage.getItem(RECENT_SPECIALS_UNASSIGNED_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map((entry) => ({
        key: String(entry?.key || ""),
        definitionId: Number(entry?.definitionId || 0),
        assetId: Number(entry?.assetId || 0),
        createdAt: Number(entry?.createdAt || Date.now()),
      }))
      .filter((entry) => entry.key && entry.definitionId > 0)
      .slice(0, RECENT_SPECIALS_MAX);
  } catch {
    return [];
  }
};

const resolveRecentSpecialEntryItem = (entry) => {
  if (entry?.item) {
    return entry.item;
  }

  const defId = getRecentSpecialDefinitionId(entry);
  if (!Number.isFinite(defId) || defId <= 0) {
    return null;
  }

  try {
    if (typeof window.collectionBookGetItemEntity === "function") {
      const entity = window.collectionBookGetItemEntity(defId);
      if (entity) return entity;
    }
  } catch {}

  return null;
};

const buildRecentSpecialCardView = (item) => {
  const Factory = globalThis.UTItemViewFactory;
  if (!Factory || typeof Factory.createLargeItem !== "function") return null;

  try {
    const view = Factory.createLargeItem(item);
    view?.init?.();
    view?.render?.(item);
    const el = view?.getRootElement?.() || null;
    return el ? { el, view } : null;
  } catch {
    return null;
  }
};

const getClubPlayerSnapshotForRecentSpecials = () => {
  try {
    const collection = services?.Item?.itemDao?.itemRepo?.club?.items?._collection;
    if (!collection || typeof collection !== "object") return [];

    return Object.entries(collection)
      .filter(([key]) => key !== "undefined")
      .map(([, item]) => item)
      .filter(
        (item) =>
          !!item &&
          ((typeof item?.isPlayer === "function" && item.isPlayer()) ||
            item?.isPlayer === true),
      );
  } catch {
    return [];
  }
};

const hasClubPlayersLoadedForRecentSpecials = () =>
  getClubPlayerSnapshotForRecentSpecials().length > 0;

const waitForClubPlayersLoadedForRecentSpecials = () => {
  if (hasClubPlayersLoadedForRecentSpecials() || window.__sbcPlayersReady) {
    return Promise.resolve(true);
  }

  return new Promise((resolve) => {
    const onReady = () => {
      try {
        window.removeEventListener("autosbc:club-players-ready", onReady);
      } catch {}
      resolve(true);
    };

    try {
      window.addEventListener("autosbc:club-players-ready", onReady, {
        once: true,
      });
    } catch {
      resolve(false);
    }
  });
};

const ensureClubPlayersLoadedThenRefreshRecentSpecials = () => {
  if (recentSpecialsClubReadyPromise) {
    return recentSpecialsClubReadyPromise;
  }

  recentSpecialsClubReadyPromise = waitForClubPlayersLoadedForRecentSpecials()
    .then((loaded) => {
      if (loaded) {
        renderRecentSpecialsStrip({ animatedKeys: new Set() });
      }
    })
    .finally(() => {
      recentSpecialsClubReadyPromise = null;
    });

  return recentSpecialsClubReadyPromise;
};

const loadRecentClubSpecialsFromEa = async (desiredCount = RECENT_SPECIALS_MAX) => {
  const count = Math.max(120, Number(desiredCount || RECENT_SPECIALS_MAX) * 25);
  const sortByRecency =
    typeof SearchSortType !== "undefined" &&
    SearchSortType &&
    typeof SearchSortType.RECENCY !== "undefined"
      ? SearchSortType.RECENCY
      : "recency";
  const sortDescending =
    typeof SearchSortOrder !== "undefined" &&
    SearchSortOrder &&
    typeof SearchSortOrder.DESCENDING !== "undefined"
      ? SearchSortOrder.DESCENDING
      : "desc";
  const playerType =
    typeof SearchType !== "undefined" && SearchType
      ? SearchType.PLAYER
      : undefined;

  let rows = [];
  try {
    if (typeof fetchClub === "function") {
      rows =
        (await fetchClub({
          count,
          sortBy: sortByRecency,
          sortOrder: sortDescending,
          type: playerType,
          showProgress: false,
        })) || [];
    }
  } catch (error) {
    console.warn("[recentSpecials] EA recency search failed", error);
    rows = [];
  }

  const seen = new Set();
  const recents = [];
  for (let idx = 0; idx < rows.length; idx += 1) {
    const item = rows[idx];
    if (!isSpecialPlayerItem(item)) continue;

    const key = getRecentSpecialEntryKey(item, `club-${idx}`);
    if (seen.has(key)) continue;
    seen.add(key);

    recents.push({
      key,
      item,
      createdAt: getEaRecencyTimestampMs(item, 0),
    });
    if (recents.length >= RECENT_SPECIALS_MAX) break;
  }

  return recents;
};

const ensureRecentClubSpecialsLoadedFromEa = () => {
  if (recentClubSpecialsLoadPromise) {
    return recentClubSpecialsLoadPromise;
  }

  recentClubSpecialsLoadPromise = waitForClubPlayersLoadedForRecentSpecials()
    .then(async (ready) => {
      if (!ready) return;
      const recents = await loadRecentClubSpecialsFromEa(RECENT_SPECIALS_MAX);
      window.__autoSbcRecentClubSpecials = Array.isArray(recents) ? recents : [];
      renderRecentSpecialsStrip({ animatedKeys: new Set() });
    })
    .finally(() => {
      recentClubSpecialsLoadPromise = null;
    });

  return recentClubSpecialsLoadPromise;
};

const getClubFallbackRecentSpecials = (limit, excludedKeys = new Set()) => {
  const cached = Array.isArray(window.__autoSbcRecentClubSpecials)
    ? window.__autoSbcRecentClubSpecials
    : [];
  if (!cached.length) return [];

  const localSeen = new Set(excludedKeys);
  const picked = [];
  for (const entry of cached) {
    if (picked.length >= limit) break;
    const key = String(entry?.key || "");
    if (!key || localSeen.has(key)) continue;
    localSeen.add(key);
    picked.push(entry);
  }
  return picked;
};

const getDisplayRecentSpecialsState = () => {
  const unassignedSource = Array.isArray(
    window.__autoSbcRecentPackedSpecialsFromUnassigned,
  )
    ? window.__autoSbcRecentPackedSpecialsFromUnassigned
    : [];

  // Once we have any unassigned-driven cards, stick with those as source of
  // truth (these are persisted separately and are independent from club state).
  const source = unassignedSource.length
    ? unassignedSource
    : Array.isArray(window.__autoSbcRecentClubSpecials)
      ? window.__autoSbcRecentClubSpecials
      : [];

  const normalized = source
    .filter((entry) => !!resolveRecentSpecialEntryItem(entry))
    .map((entry, index) => ({
      key:
        String(entry?.key || "") ||
        getRecentSpecialEntryKey(entry?.item, entry?.createdAt || index),
      item: resolveRecentSpecialEntryItem(entry),
      createdAt: Number(entry?.createdAt || Date.now()),
    }))
    .slice(0, RECENT_SPECIALS_MAX);
  return normalized;
};

const renderRecentSpecialsStrip = (options = {}) => {
  const { animatedKeys = new Set() } = options || {};
  const enabled = isRecentPackedSpecialsEnabled();
  if (!enabled) {
    const existingRoot = document.getElementById(RECENT_SPECIALS_STRIP_ID);
    if (existingRoot) {
      existingRoot.classList.add("is-hidden");
    }
    return;
  }

  const state = getDisplayRecentSpecialsState();

  // Initial mode: load via EA recency only when no unassigned-derived cards
  // exist yet. After that, we stick with the unassigned list.
  const hasUnassignedSource =
    (window.__autoSbcRecentPackedSpecialsFromUnassigned || []).length > 0;
  if (!hasUnassignedSource && !hasClubPlayersLoadedForRecentSpecials()) {
    void ensureClubPlayersLoadedThenRefreshRecentSpecials();
  }
  if (!hasUnassignedSource && state.length < RECENT_SPECIALS_MAX) {
    void ensureRecentClubSpecialsLoadedFromEa();
  }

  const stripRoot = ensureRecentSpecialsStripRoot();
  if (!stripRoot) {
    return;
  }

  const { root, track } = stripRoot;
  root.classList.remove("is-hidden");
  root.classList.toggle("is-collapsed", isRecentSpecialsCollapsed());

  const toggle = document.getElementById(RECENT_SPECIALS_TOGGLE_ID);
  if (toggle) {
    toggle.textContent = isRecentSpecialsCollapsed() ? "Expand" : "Collapse";
  }

  if (isRecentSpecialsCollapsed()) {
    return;
  }

  ensureRecentSpecialTimeAgoTicker();

  const beforeRects = new Map(
    Array.from(track.querySelectorAll(".autosbc-recent-special-card")).map((el) => [
      String(el.dataset.key || ""),
      el.getBoundingClientRect(),
    ]),
  );

  const previousNodes = new Map(
    Array.from(track.querySelectorAll(".autosbc-recent-special-card")).map((el) => [
      String(el.dataset.key || ""),
      el,
    ]),
  );
  const nextKeys = new Set(state.map((entry) => String(entry.key)));

  previousNodes.forEach((node, key) => {
    if (nextKeys.has(key)) return;
    node.classList.remove("is-enter", "is-enter-active");
    const previousIndex = Array.from(previousNodes.keys()).indexOf(key);
    node.style.transitionDelay = `${Math.max(0, previousIndex) * RECENT_SPECIALS_SNAKE_STAGGER_MS}ms`;
    // Force layout so exit transition always starts from the current rendered state.
    void node.getBoundingClientRect();
    node.classList.add("is-exit");

    let removed = false;
    const removeNode = () => {
      if (removed) return;
      removed = true;
      try {
        node.removeEventListener("transitionend", onTransitionEnd);
      } catch {}
      if (node.parentElement === track) {
        node.remove();
      }
    };

    const onTransitionEnd = (event) => {
      if (event?.target !== node) return;
      removeNode();
    };

    node.addEventListener("transitionend", onTransitionEnd);
    setTimeout(
      removeNode,
      700 + Math.max(0, previousIndex) * RECENT_SPECIALS_SNAKE_STAGGER_MS,
    );
  });

  if (!state.length) {
    track.innerHTML = "";
    const empty = document.createElement("div");
    empty.className = "autosbc-recent-special-empty";
    empty.textContent = "No special cards packed yet";
    track.appendChild(empty);
    return;
  }

  const empty = track.querySelector(".autosbc-recent-special-empty");
  if (empty) empty.remove();

  const nextIndexByKey = new Map(
    state.map((entry, index) => [String(entry?.key || ""), index]),
  );
  const packedCountsByDefinitionId = getPackedCountsByDefinitionId(state);

  state.forEach((entry, index) => {
    const key = String(entry.key || "");
    if (!key) return;

    let wrapper = previousNodes.get(key);
    if (!wrapper) {
      wrapper = document.createElement("div");
      wrapper.className = "autosbc-recent-special-card is-enter";
      wrapper.dataset.key = key;
      wrapper.style.transitionDelay = `${index * RECENT_SPECIALS_SNAKE_STAGGER_MS}ms`;
      const cardBuilt = buildRecentSpecialCardView(entry.item);
      if (cardBuilt?.el) {
        wrapper.appendChild(cardBuilt.el);
        wrapper.__recentView = cardBuilt.view || null;
        syncRecentSpecialSeenLabelViewState(
          cardBuilt.view || null,
          entry,
          packedCountsByDefinitionId,
        );
        applyRecentSpecialSeenLabel(
          cardBuilt.view || null,
          entry,
          packedCountsByDefinitionId,
        );
      } else {
        wrapper.textContent = String(entry.item?._staticData?.name || entry.item?.definitionId || "Special");
      }
      upsertRecentSpecialTimeAgoLabel(wrapper, entry.createdAt, index === 0);
      track.appendChild(wrapper);

      if (animatedKeys.has(key)) {
        requestAnimationFrame(() => {
          wrapper.classList.add("is-enter-active");
          wrapper.classList.remove("is-enter");
        });
      } else {
        wrapper.classList.remove("is-enter");
      }
    } else {
      wrapper.style.transitionDelay = `${index * RECENT_SPECIALS_SNAKE_STAGGER_MS}ms`;
      syncRecentSpecialSeenLabelViewState(
        wrapper.__recentView || null,
        entry,
        packedCountsByDefinitionId,
      );
      applyRecentSpecialSeenLabel(
        wrapper.__recentView || null,
        entry,
        packedCountsByDefinitionId,
      );
      upsertRecentSpecialTimeAgoLabel(wrapper, entry.createdAt, index === 0);
      track.appendChild(wrapper);
    }
  });

  const afterNodes = Array.from(
    track.querySelectorAll(".autosbc-recent-special-card"),
  );
  afterNodes.forEach((node) => {
    const key = String(node.dataset.key || "");
    if (!key) return;

    const nextIndex = Number(nextIndexByKey.get(key) || 0);
    node.style.transitionDelay = `${nextIndex * RECENT_SPECIALS_SNAKE_STAGGER_MS}ms`;

    if (animatedKeys.has(key)) return;

    const beforeRect = beforeRects.get(key);
    if (!beforeRect) return;
    const afterRect = node.getBoundingClientRect();
    const dx = beforeRect.left - afterRect.left;

    if (Math.abs(dx) < 1) return;

    node.style.transition = "none";
    node.style.transform = `translateX(${dx}px)`;
    requestAnimationFrame(() => {
      node.style.transition = `transform 640ms cubic-bezier(0.22, 0.61, 0.36, 1) ${nextIndex * RECENT_SPECIALS_SNAKE_STAGGER_MS}ms, opacity 520ms ease ${nextIndex * RECENT_SPECIALS_SNAKE_STAGGER_MS}ms`;
      node.style.transform = "translateX(0)";
    });
  });

  refreshRecentSpecialTimeAgoLabels();
};

const recordRecentPackedSpecials = (items = []) => {
  const enabled = isRecentPackedSpecialsEnabled();
  if (!enabled) {
    return;
  }

  const specials = (Array.isArray(items) ? items : [])
    .filter(Boolean)
    .filter((item) => isSpecialPlayerItem(item));

  if (!specials.length) {
    return;
  }

  const previous = Array.isArray(window.__autoSbcRecentPackedSpecialsFromUnassigned)
    ? window.__autoSbcRecentPackedSpecialsFromUnassigned
    : [];
  const byKey = new Map(previous.map((entry) => [String(entry.key), entry]));
  const touchedByKey = new Map();
  const animatedKeys = new Set();

  for (const item of specials) {
    const rawId = Number(item?.id);
    const definitionId = Number(item?.definitionId);
    const timestamp = getEaRecencyTimestampMs(item, Date.now());
    const key =
      Number.isFinite(rawId) && rawId > 0
        ? `item-${rawId}`
        : getRecentSpecialEntryKey(
            item,
            `${definitionId || 0}-${timestamp}-${Math.random().toString(36).slice(2, 6)}`,
          );

    const existing = byKey.get(String(key));
    const nextEntry = { key, item, createdAt: timestamp };

    byKey.set(String(key), nextEntry);
    touchedByKey.set(String(key), nextEntry);

    if (!existing) {
      animatedKeys.add(String(key));
    }
  }

  if (!touchedByKey.size) {
    return;
  }

  const touched = Array.from(touchedByKey.values()).reverse();
  const remaining = previous.filter(
    (entry) => !touchedByKey.has(String(entry?.key || "")),
  );
  const merged = [...touched, ...remaining].slice(0, RECENT_SPECIALS_MAX);
  window.__autoSbcRecentPackedSpecialsFromUnassigned = merged;
  saveRecentSpecialsUnassignedEntries(merged);
  renderRecentSpecialsStrip({ animatedKeys });
};

const refreshRecentPackedSpecialStrip = () => {
  renderRecentSpecialsStrip({ animatedKeys: new Set() });
};

if (typeof window !== "undefined") {
  window.__autoSbcRecentSpecialsCollapsed = loadRecentSpecialsCollapsed();
  const persistedUnassigned = loadRecentSpecialsUnassignedEntries();
  window.__autoSbcRecentPackedSpecialsFromUnassigned =
    window.__autoSbcRecentPackedSpecialsFromUnassigned ||
    (persistedUnassigned.length
      ? persistedUnassigned
      : window.__autoSbcRecentPackedSpecials || []);
  window.__autoSbcRecentClubSpecials = window.__autoSbcRecentClubSpecials || [];
  window.__autoSbcRecentPackedSpecials = window.__autoSbcRecentPackedSpecialsFromUnassigned;
  window.recordRecentPackedSpecials = recordRecentPackedSpecials;
  window.refreshRecentPackedSpecialStrip = refreshRecentPackedSpecialStrip;

  // Always mount the strip immediately so UI is visible even before async
  // data fetches/events complete.
  setTimeout(() => {
    renderRecentSpecialsStrip({ animatedKeys: new Set() });
  }, 0);

  // Trigger initial render source load when needed.
  if ((window.__autoSbcRecentPackedSpecialsFromUnassigned || []).length === 0) {
    void ensureRecentClubSpecialsLoadedFromEa();
  }
}
let processUnassigned = async (options = {}) => {
  const { force = false, suppressNavigation = false } = options || {};
  window.__autoSbcProcessUnassignedState ??= {
    runningPromise: null,
    lastRunAt: 0,
    lastResult: null,
    cooldownMs: 1500,
  };
  const state = window.__autoSbcProcessUnassignedState;

  if (state.runningPromise) {
    return state.runningPromise;
  }

  if (!force && Date.now() - Number(state.lastRunAt || 0) < state.cooldownMs) {
    return state.lastResult;
  }

  const runPromise = (async () => {
    ratingCountUI();
    const runId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const log = () => {};
    const processedLog = [];
    const livePriceFetchedDefinitionIds = new Set();
    const runTimestamp = new Date().toLocaleString();
    const getItemRarityIdSafe = (item) =>
      Number(item?.rareflag ?? item?._staticData?.rareflag ?? item?.rarityId) ||
      null;
    const getItemNameSafe = (item) =>
      item?._staticData?.name ||
      item?._staticData?.lastName ||
      item?.name ||
      item?.definitionId ||
      "Unknown";
    const addProcessedLog = (items, action, ruleNumber, ruleColor = null) => {
      (items || []).forEach((item) => {
        processedLog.push({
          item,
          action,
          ruleNumber,
          timestamp: runTimestamp,
          ruleColor,
        });
      });
    };
    const hasValidPrice = (item) => {
      const price = Number(getPrice(item));
      return Number.isFinite(price) && price > 0;
    };
    const getSortablePrice = (item) => {
      const price = Number(getPrice(item));
      return Number.isFinite(price) ? price : 0;
    };
    const sortItemsByPriceDesc = (items = []) =>
      [...items].sort(
        (a, b) => getSortablePrice(b) - getSortablePrice(a),
      );
    const sortEntriesByPriceDesc = (entries = []) =>
      [...entries].sort(
        (a, b) =>
          getSortablePrice(b?.item) - getSortablePrice(a?.item),
      );
    const ensureLivePrices = async (entries, options = {}) => {
      const { awaitCompletion = true } = options || {};
      const toFetch = (entries || [])
        .map((e) => e?.item)
        .filter(Boolean)
        .filter((item) => Number(item?.definitionId) > 0)
        .filter((item) => !livePriceFetchedDefinitionIds.has(item.definitionId))
        .filter((item) => !hasValidPrice(item));

      if (!toFetch.length) return null;

      log("livePrice:fetch", { count: toFetch.length });
      const refreshPromise = Promise.all(
        toFetch.map(async (item) => {
          try {
            await fetchLivePlayerPrice(item);
            if (Number(item?.definitionId) > 0) {
              livePriceFetchedDefinitionIds.add(item.definitionId);
            }
          } catch (err) {
            void err;
          }
        }),
      );

      if (awaitCompletion) {
        await refreshPromise;
      }

      return refreshPromise;
    };

    const clearSoldItemsBeforeTransferActions = async () => {
      if (typeof clearSoldItems !== "function") {
        return;
      }

      try {
        await clearSoldItems();
      } catch (error) {
        void error;
      }
    };

    const getTransferListCount = async () => {
      await clearSoldItemsBeforeTransferActions();

      try {
        if (typeof getTransferItems === "function") {
          const items = await getTransferItems();
          return Array.isArray(items) ? items.length : 0;
        }
      } catch {}

      try {
        if (typeof fetchTransferList === "function") {
          const items = await fetchTransferList();
          return Array.isArray(items) ? items.length : 0;
        }
      } catch {}

      try {
        if (services?.Item?.requestTransferItems) {
          const items = await new Promise((resolve, reject) => {
            try {
              services.Item.requestTransferItems().observe(
                null,
                (obs, event) => {
                  try {
                    obs?.unobserve?.(null);
                    resolve(
                      Array.isArray(event?.response?.items)
                        ? event.response.items
                        : [],
                    );
                  } catch (err) {
                    reject(err);
                  }
                },
              );
            } catch (err) {
              reject(err);
            }
          });
          return Array.isArray(items) ? items.length : 0;
        }
      } catch {}

      return 0;
    };

    let unsoldTransferRulesProcessed = false;
    const fetchTransferItemsForUnsoldProcessing = async () => {
      try {
        if (typeof getTransferItems === "function") {
          const items = await getTransferItems();
          if (Array.isArray(items)) return items;
        }
      } catch {}

      try {
        if (typeof fetchTransferList === "function") {
          const items = await fetchTransferList();
          if (Array.isArray(items)) return items;
        }
      } catch {}

      try {
        if (services?.Item?.requestTransferItems) {
          const items = await new Promise((resolve, reject) => {
            try {
              services.Item.requestTransferItems().observe(
                null,
                (obs, event) => {
                  try {
                    obs?.unobserve?.(null);
                    resolve(
                      Array.isArray(event?.response?.items)
                        ? event.response.items
                        : [],
                    );
                  } catch (err) {
                    reject(err);
                  }
                },
              );
            } catch (err) {
              reject(err);
            }
          });
          return Array.isArray(items) ? items : [];
        }
      } catch {}

      return [];
    };

    const processUnsoldTransferItemsByRules = async () => {
      if (unsoldTransferRulesProcessed) {
        return;
      }
      unsoldTransferRulesProcessed = true;

      try {
        if (
          typeof getUnassignedRules !== "function" ||
          typeof groupUnassignedItemsByRules !== "function"
        ) {
          return;
        }

        const rules = (getUnassignedRules() || []).filter(
          (rule) => rule?.enabled !== false,
        );
        if (!rules.length) {
          return;
        }

        const transferItems = await fetchTransferItemsForUnsoldProcessing();
        if (!transferItems.length) {
          return;
        }

        const unsoldItems = transferItems.filter((item) => {
          const state = String(
            item?._auction?._tradeState || item?._auction?.tradeState || "",
          ).toLowerCase();
          return state === "expired";
        });

        if (!unsoldItems.length) {
          return;
        }

        const grouping = groupUnassignedItemsByRules(unsoldItems, rules, {
          includeFreeItems: false,
          includeDoNothing: false,
          matcherOptions: { assumeMinPriceWhenMissing: true },
        });

        const isTradable = (item) =>
          item?.tradable === true ||
          (typeof item?.isTradeable === "function" && item.isTradeable());

        const toClub = (grouping.buckets.get("sendToClub") || [])
          .map((entry) => entry?.item)
          .filter((item) => item?.isMovable?.());
        const sortedToClub = sortItemsByPriceDesc(toClub);
        const toTransferList = (
          grouping.buckets.get("sendToTransferList") || []
        )
          .map((entry) => entry?.item)
          .filter((item) => isTradable(item));
        const sortedToTransferList = sortItemsByPriceDesc(toTransferList);
        const toStorageUnsold = (grouping.buckets.get("sendToStorage") || [])
          .map((entry) => entry?.item)
          .filter((item) => item?.isStorable?.());
        let sortedToStorage = sortItemsByPriceDesc(toStorageUnsold);

        if (getSettings(0, 0, "replaceStoragePlayers") && sortedToStorage.length) {
          const unsoldStorageSnapshot = await getStoragePlayers();
          const combined = [
            ...(unsoldStorageSnapshot || []).map((item) => ({ item, source: "storage" })),
            ...sortedToStorage.map((item) => ({ item, source: "new" })),
          ].sort((a, b) => {
            const priceDiff = getSortablePrice(b.item) - getSortablePrice(a.item);
            if (priceDiff !== 0) return priceDiff;
            return (b.item?.rating ?? 0) - (a.item?.rating ?? 0);
          });
          const keep = combined.slice(0, 100);
          const discard = combined.slice(100);
          const discardFromStorage = discard.filter((e) => e.source === "storage").map((e) => e.item);
          const discardNew = discard.filter((e) => e.source === "new").map((e) => e.item);
          sortedToStorage = keep.filter((e) => e.source === "new").map((e) => e.item);
          if (discardFromStorage.length) {
            services.Item.discard(discardFromStorage);
          }
          if (discardNew.length) {
            services.Item.discard(discardNew);
          }
          if (discardFromStorage.length && sortedToStorage.length) {
            await new Promise((r) => setTimeout(r, 2000));
          }
        }

        const toQuickSell = (grouping.buckets.get("quickSell") || [])
          .map((entry) => entry?.item)
          .filter(Boolean);
        const sortedToQuickSell = sortItemsByPriceDesc(toQuickSell);
        const toList = (grouping.buckets.get("listOnTransferMarket") || [])
          .map((entry) => entry?.item)
          .filter((item) => isTradable(item));
        const sortedToList = sortItemsByPriceDesc(toList);

        if (sortedToClub.length) {
          services.Item.move(sortedToClub, 7);
        }
        if (sortedToTransferList.length) {
          services.Item.move(sortedToTransferList, 5);
        }
        if (sortedToStorage.length) {
          services.Item.move(sortedToStorage, 10);
        }
        if (sortedToQuickSell.length) {
          services.Item.discard(sortedToQuickSell);
        }
        if (sortedToList.length) {
          await quickListItems(sortedToList, {
            suppressNotifications: true,
            minDelayMs: 1000,
            maxDelayMs: 1000,
          });
        }

        log("transferUnsold:processedByRules", {
          unsold: unsoldItems.length,
          sendToClub: toClub.length,
          sendToTransferList: toTransferList.length,
          sendToStorage: sortedToStorage.length,
          quickSell: toQuickSell.length,
          listOnTransferMarket: toList.length,
        });
      } catch (error) {
        void error;
      }
    };

    try {
      log("start");

      let storage = await getStoragePlayers();
      let ulist = await fetchUnassigned();
      let players = await fetchPlayers();

      log("fetched", {
        storageCount: storage?.length ?? 0,
        unassignedCount: ulist?.length ?? 0,
        clubCount: players?.length ?? 0,
      });

      if (!ulist || ulist.length === 0) {
        log("skip", { reason: "no-unassigned" });
        return;
      }

      const freeItems = (ulist || []).filter(
        (item) => item?.isFreeCoins?.() || item?.isFreePack?.(),
      );
      log("freeItems", { count: freeItems.length });
      freeItems.forEach((item) => services.Item.redeem(item));

      const tradableNonFodder = (ulist || [])
        .filter((item) => !item?.isFreeCoins?.() && !item?.isFreePack?.())
        .filter(
          (item) =>
            item?.tradable === true ||
            (typeof item?.isTradeable === "function" && item.isTradeable()),
        )
        .filter((item) => !isFodder(item));

      if (tradableNonFodder.length) {
        log("preRulePriceRefresh", { count: tradableNonFodder.length });
        void ensureLivePrices(
          tradableNonFodder.map((item) => ({ item })),
          {
            awaitCompletion: false,
          },
        );
      }

      if (isUnassignedGroupingEnabled()) {
        log("grouping", { enabled: true });

        const processedIds = new Set();
        const summarizeItems = (items) =>
          (items || []).map((item) => ({
            id: item?.id ?? null,
            name:
              item?._staticData?.name ||
              item?._staticData?.lastName ||
              item?.name ||
              item?.definitionId ||
              "Unknown",
            rating: item?.rating ?? item?._staticData?.rating ?? null,
            tradable:
              item?.tradable === true ||
              (typeof item?.isTradeable === "function" && item.isTradeable()) ||
              false,
            isDuplicate:
              Number(item?.duplicateId ?? 0) > 0 || item?.isDuplicate?.(),
          }));

        const rules = getUnassignedRules();
        const actionBuckets = {
          sendToClub: [],
          sendToTransferList: [],
          sendToStorage: [],
          quickSell: [],
          listOnTransferMarket: [],
        };
        const nonFreeItems = (ulist || []).filter(
          (item) => !item?.isFreeCoins?.() && !item?.isFreePack?.(),
        );
        const processedByRule = new Map();
        const pendingPriceRecheckEntries = [];
        const deferredQuickSellEntries = [];
        const isTradable = (item) =>
          item?.tradable === true ||
          (typeof item?.isTradeable === "function" && item.isTradeable());
        const isTransferAction = (action) =>
          action === "sendToTransferList" || action === "listOnTransferMarket";

        const transferListCount = await getTransferListCount();
        let remainingTransferSlots = Math.max(0, 100 - transferListCount);

        const groupingBuckets = new Map([
          ["sendToClub", []],
          ["sendToTransferList", []],
          ["sendToStorage", []],
          ["quickSell", []],
          ["listOnTransferMarket", []],
        ]);

        nonFreeItems.forEach((item) => {
          if (!item) return;

          for (let i = 0; i < (rules || []).length; i += 1) {
            const rule = rules[i];
            if (rule?.enabled === false) continue;
            if (
              !matchesUnassignedRule(item, rule, {
                assumeMinPriceWhenMissing: true,
              })
            ) {
              continue;
            }

            const action = rule.action || "sendToClub";
            if (isTransferAction(action)) {
              if (!isTradable(item)) {
                continue;
              }
              if (remainingTransferSlots <= 0) {
                continue;
              }
              remainingTransferSlots -= 1;
            }

            groupingBuckets.get(action)?.push({
              item,
              rule,
              ruleIndex: i,
            });
            break;
          }
        });

        const grouping = { buckets: groupingBuckets };

        const addProcessedEntries = (action, entries) => {
          if (!entries.length) return;
          actionBuckets[action].push(...entries);
          entries.forEach((entry) => {
            if (entry?.item?.id != null) {
              processedIds.add(entry.item.id);
            }
            if (entry?.ruleIndex != null && entry.ruleIndex >= 0) {
              if (!processedByRule.has(entry.ruleIndex)) {
                processedByRule.set(entry.ruleIndex, []);
              }
              processedByRule.get(entry.ruleIndex).push(entry);
            }
          });
        };

        const trackPendingPriceEntries = (entries) => {
          (entries || []).forEach((entry) => {
            const item = entry?.item;
            if (!item || hasValidPrice(item)) {
              return;
            }
            pendingPriceRecheckEntries.push(entry);
          });
        };

        const toClub = (grouping.buckets.get("sendToClub") || []).filter(
          (entry) => entry?.item?.isMovable?.(),
        );
        trackPendingPriceEntries(toClub);
        addProcessedEntries("sendToClub", sortEntriesByPriceDesc(toClub));

        const toTransferList = (
          grouping.buckets.get("sendToTransferList") || []
        ).filter((entry) => isTradable(entry?.item));
        trackPendingPriceEntries(toTransferList);
        addProcessedEntries(
          "sendToTransferList",
          sortEntriesByPriceDesc(toTransferList),
        );

        const toStorageAll = sortEntriesByPriceDesc(
          (
          grouping.buckets.get("sendToStorage") || []
          ).filter((entry) => entry?.item?.isStorable?.()),
        );
        const replaceStorageEnabled = getSettings(0, 0, "replaceStoragePlayers");
        let toStorage;

        if (replaceStorageEnabled && toStorageAll.length) {
          const combined = [
            ...(storage || []).map((item) => ({ item, source: "storage" })),
            ...toStorageAll.map((entry) => ({ item: entry.item, source: "new", entry })),
          ].sort((a, b) => {
            const priceDiff = getSortablePrice(b.item) - getSortablePrice(a.item);
            if (priceDiff !== 0) return priceDiff;
            return (b.item?.rating ?? 0) - (a.item?.rating ?? 0);
          });
          const keep = combined.slice(0, 100);
          const discard = combined.slice(100);
          const discardFromStorage = discard.filter((e) => e.source === "storage").map((e) => e.item);
          const discardNew = discard.filter((e) => e.source === "new").map((e) => e.item);
          toStorage = keep.filter((e) => e.source === "new").map((e) => e.entry);

          if (discardFromStorage.length) {
            log("replaceStorage:discardOld", { count: discardFromStorage.length });
            services.Item.discard(discardFromStorage);
            storage = storage.filter((item) => !discardFromStorage.includes(item));
          }
          if (discardNew.length) {
            log("replaceStorage:discardNew", { count: discardNew.length });
            services.Item.discard(discardNew);
            addProcessedLog(discardNew, "quickSell", null, null);
          }
          if (discardFromStorage.length && toStorage.length) {
            await new Promise((r) => setTimeout(r, 2000));
          }
        } else {
          const capacity = Math.max(0, 100 - (storage?.length ?? 0));
          toStorage = toStorageAll.slice(0, capacity);
        }

        if (toStorage.length) {
          storage = [
            ...(storage || []),
            ...toStorage.map((entry) => entry.item),
          ];
        }
        trackPendingPriceEntries(toStorage);
        addProcessedEntries("sendToStorage", toStorage);

        const toQuickSellAll = grouping.buckets.get("quickSell") || [];
        const toQuickSell = toQuickSellAll.filter((entry) =>
          hasValidPrice(entry?.item),
        );
        const quickSellMissingPrice = toQuickSellAll.filter(
          (entry) => !hasValidPrice(entry?.item),
        );
        if (quickSellMissingPrice.length) {
          deferredQuickSellEntries.push(...quickSellMissingPrice);
          pendingPriceRecheckEntries.push(...quickSellMissingPrice);
          quickSellMissingPrice.forEach((entry) => {
            if (entry?.item?.id != null) {
              processedIds.add(entry.item.id);
            }
          });
        }
        addProcessedEntries("quickSell", sortEntriesByPriceDesc(toQuickSell));

        const toList = (
          grouping.buckets.get("listOnTransferMarket") || []
        ).filter((entry) => isTradable(entry?.item));
        trackPendingPriceEntries(toList);
        addProcessedEntries(
          "listOnTransferMarket",
          sortEntriesByPriceDesc(toList),
        );

        rules.forEach((rule, index) => {
          const action = rule.action || "sendToClub";
          log("rule:start", {
            ruleId: rule.id,
            ruleNumber: index + 1,
            action,
            filters: rule.filters || [],
            ratingRange: rule.ratingRange,
            priceRange: rule.priceRange,
            includeLeagues: rule.includeLeagues,
            excludeLeagues: rule.excludeLeagues,
            includeNations: rule.includeNations,
            excludeNations: rule.excludeNations,
            includeTeams: rule.includeTeams,
            excludeTeams: rule.excludeTeams,
            includeRarity: rule.includeRarity,
            excludeRarity: rule.excludeRarity,
          });

          const entries = processedByRule.get(index) || [];
          if (!entries.length) {
            log("rule:match:none", { ruleId: rule.id, action });
            return;
          }

          const processed = entries.map((entry) => entry.item).filter(Boolean);
          addProcessedLog(processed, action, index + 1, rule.color || null);

          log("rule:processed", {
            ruleId: rule.id,
            ruleNumber: index + 1,
            action,
            count: processed.length,
            items: summarizeItems(processed),
          });
        });

        if (deferredQuickSellEntries.length) {
          const deferredQuickSellItems = deferredQuickSellEntries
            .map((entry) => entry?.item)
            .filter(Boolean);
          addProcessedLog(deferredQuickSellItems, "doNothing", null, null);
          log("rule:processed", {
            ruleId: null,
            ruleNumber: null,
            action: "doNothing",
            reason: "quickSell-waiting-for-price",
            count: deferredQuickSellItems.length,
            items: summarizeItems(deferredQuickSellItems),
          });
        }

        const reprocessPendingPriceEntries = async () => {
          if (!pendingPriceRecheckEntries.length) {
            return;
          }

          try {
            log("pendingPrice:refresh:start", {
              count: pendingPriceRecheckEntries.length,
            });
            await ensureLivePrices(pendingPriceRecheckEntries, {
              awaitCompletion: true,
            });

            const refreshedUnassigned = await fetchUnassigned();
            const refreshedById = new Map(
              (refreshedUnassigned || [])
                .filter((item) => item?.id != null)
                .map((item) => [item.id, item]),
            );

            const actionBuckets = {
              sendToClub: [],
              sendToTransferList: [],
              sendToStorage: [],
              quickSell: [],
              listOnTransferMarket: [],
            };
            const isTransferAction = (action) =>
              action === "sendToTransferList" ||
              action === "listOnTransferMarket";
            const transferListCount = await getTransferListCount();
            let remainingTransferSlots = Math.max(0, 100 - transferListCount);

            const addEntryToBucket = (action, item, rule) => {
              if (!item || !actionBuckets[action]) {
                return;
              }
              actionBuckets[action].push({ item, rule });
            };

            pendingPriceRecheckEntries.forEach((entry) => {
              const itemId = entry?.item?.id;
              if (itemId == null) {
                return;
              }

              const item = refreshedById.get(itemId);
              if (!item) {
                return;
              }

              let matchedRule = null;
              let matchedAction = null;

              for (let i = 0; i < (rules || []).length; i += 1) {
                const rule = rules[i];
                if (rule?.enabled === false) continue;
                if (!matchesUnassignedRule(item, rule)) continue;

                const action = rule.action || "sendToClub";
                if (isTransferAction(action)) {
                  if (!isTradable(item)) {
                    continue;
                  }
                  if (remainingTransferSlots <= 0) {
                    continue;
                  }
                  remainingTransferSlots -= 1;
                }

                matchedRule = rule;
                matchedAction = action;
                break;
              }

              if (!matchedRule) {
                return;
              }

              const action = matchedAction || "sendToClub";
              if (action === "sendToTransferList") {
                if (isTradable(item))
                  addEntryToBucket(action, item, matchedRule);
                return;
              }

              if (action === "sendToStorage") {
                if (item?.isStorable?.())
                  addEntryToBucket(action, item, matchedRule);
                return;
              }

              if (action === "sendToClub") {
                if (item?.isMovable?.())
                  addEntryToBucket(action, item, matchedRule);
                return;
              }

              if (action === "listOnTransferMarket") {
                if (isTradable(item))
                  addEntryToBucket(action, item, matchedRule);
                return;
              }

              if (action === "quickSell") {
                addEntryToBucket(action, item, matchedRule);
              }
            });

            const storageSnapshot = await getStoragePlayers();
            const replaceEnabled = getSettings(0, 0, "replaceStoragePlayers");

            if (replaceEnabled && actionBuckets.sendToStorage.length) {
              const combined = [
                ...(storageSnapshot || []).map((item) => ({ item, source: "storage" })),
                ...actionBuckets.sendToStorage.map((entry) => ({ item: entry.item, source: "new", entry })),
              ].sort((a, b) => {
                const priceDiff = getSortablePrice(b.item) - getSortablePrice(a.item);
                if (priceDiff !== 0) return priceDiff;
                return (b.item?.rating ?? 0) - (a.item?.rating ?? 0);
              });
              const keep = combined.slice(0, 100);
              const discard = combined.slice(100);
              const discardFromStorage = discard.filter((e) => e.source === "storage").map((e) => e.item);
              const discardNew = discard.filter((e) => e.source === "new").map((e) => e.item);
              actionBuckets.sendToStorage = keep.filter((e) => e.source === "new").map((e) => e.entry);
              if (discardFromStorage.length) {
                services.Item.discard(discardFromStorage);
              }
              if (discardNew.length) {
                services.Item.discard(discardNew);
              }
              if (discardFromStorage.length && actionBuckets.sendToStorage.length) {
                await new Promise((r) => setTimeout(r, 2000));
              }
            } else {
              const capacity = Math.max(0, 100 - (storageSnapshot?.length ?? 0));
              if (actionBuckets.sendToStorage.length > capacity) {
                actionBuckets.sendToStorage = actionBuckets.sendToStorage.slice(
                  0,
                  capacity,
                );
              }
            }

            const applyBucket = async (action, entries) => {
              const items = sortItemsByPriceDesc(
                (entries || [])
                .map((entry) => entry?.item)
                .filter(Boolean),
              );
              if (!items.length) {
                return 0;
              }

              if (action === "sendToClub") {
                services.Item.move(items, 7);
              } else if (action === "sendToTransferList") {
                await clearSoldItemsBeforeTransferActions();
                services.Item.move(items, 5);
              } else if (action === "sendToStorage") {
                services.Item.move(items, 10);
              } else if (action === "quickSell") {
                services.Item.discard(items);
              } else if (action === "listOnTransferMarket") {
                await clearSoldItemsBeforeTransferActions();
                await processUnsoldTransferItemsByRules();
                void quickListItems(items, {
                  suppressNotifications: true,
                  minDelayMs: 1000,
                  maxDelayMs: 1000,
                });
              }

              const actionTimestamp = new Date().toLocaleString();
              const historyRows = items.map((item) => ({
                item,
                action,
                ruleNumber: null,
                timestamp: actionTimestamp,
                ruleColor: null,
              }));
              appendUnassignedHistoryRows(historyRows, actionTimestamp);
              return items.length;
            };

            const movedToClub = await applyBucket(
              "sendToClub",
              actionBuckets.sendToClub,
            );
            const movedToTransferList = await applyBucket(
              "sendToTransferList",
              actionBuckets.sendToTransferList,
            );
            const movedToStorage = await applyBucket(
              "sendToStorage",
              actionBuckets.sendToStorage,
            );
            const quickSold = await applyBucket(
              "quickSell",
              actionBuckets.quickSell,
            );
            const listedOnMarket = await applyBucket(
              "listOnTransferMarket",
              actionBuckets.listOnTransferMarket,
            );

            log("pendingPrice:reprocessed", {
              sendToClub: movedToClub,
              sendToTransferList: movedToTransferList,
              sendToStorage: movedToStorage,
              quickSell: quickSold,
              listOnTransferMarket: listedOnMarket,
            });
          } catch (error) {
            void error;
          }
        };

        const executeBucket = async (action, entries) => {
          const items = sortItemsByPriceDesc(
            entries.map((entry) => entry.item).filter(Boolean),
          );
          if (!items.length) return;

          if (action === "sendToClub") {
            services.Item.move(items, 7);
          } else if (action === "sendToTransferList") {
            await clearSoldItemsBeforeTransferActions();
            services.Item.move(items, 5);
          } else if (action === "sendToStorage") {
            services.Item.move(items, 10);
          } else if (action === "quickSell") {
            services.Item.discard(items);
          } else if (action === "listOnTransferMarket") {
            await clearSoldItemsBeforeTransferActions();
            await processUnsoldTransferItemsByRules();
            const eligible = entries
              .filter((entry) =>
                matchesUnassignedRule(entry.item, entry.rule, {
                  assumeMinPriceWhenMissing: true,
                }),
              )
              .map((entry) => entry.item);
            const sortedEligible = sortItemsByPriceDesc(eligible);
            if (!sortedEligible.length) return;
            void quickListItems(sortedEligible, {
              suppressNotifications: true,
              minDelayMs: 1000,
              maxDelayMs: 1000,
            });
          }
        };

        const executeBucketWithRatingUi = async (action, entries) => {
          await executeBucket(action, entries);
          try {
            if (typeof ratingCountUI === "function") {
              await ratingCountUI();
            }
          } catch {}
        };

        await executeBucketWithRatingUi("sendToClub", actionBuckets.sendToClub);
        await executeBucketWithRatingUi(
          "sendToTransferList",
          actionBuckets.sendToTransferList,
        );
        await executeBucketWithRatingUi(
          "sendToStorage",
          actionBuckets.sendToStorage,
        );
        await executeBucketWithRatingUi("quickSell", actionBuckets.quickSell);
        await executeBucketWithRatingUi(
          "listOnTransferMarket",
          actionBuckets.listOnTransferMarket,
        );

        if (pendingPriceRecheckEntries.length) {
          void reprocessPendingPriceEntries();
        }

        if (
          actionBuckets.sendToTransferList.length ||
          actionBuckets.quickSell.length ||
          actionBuckets.listOnTransferMarket.length
        ) {
          if (!suppressNavigation) {
            goToUnassignedView();
          }
        }

        ulist = await fetchUnassigned();
        const unmatched = (ulist || [])
          .filter((item) => !item?.isFreeCoins?.() && !item?.isFreePack?.())
          .filter((item) => !processedIds.has(item?.id));

        if (unmatched.length) {
          addProcessedLog(unmatched, "doNothing", null, null);
          log("rule:processed", {
            ruleId: null,
            ruleNumber: null,
            action: "doNothing",
            count: unmatched.length,
            items: summarizeItems(unmatched),
          });
        }

        void ensureLivePrices(processedLog, { awaitCompletion: false });
        console.table(
          processedLog.map(({ item, action, ruleNumber, timestamp }) => ({
            timestamp,
            ruleNumber,
            name: getItemNameSafe(item),
            rating: item?.rating ?? item?._staticData?.rating ?? null,
            price: Number(getPrice(item)) || null,
            rarity: getItemRarityLabel(item),
            isFodder: typeof isFodder === "function" ? isFodder(item) : false,
            isDuplicate:
              Number(item?.duplicateId ?? 0) > 0 || item?.isDuplicate?.(),
            action,
          })),
        );

        appendUnassignedHistoryRows(processedLog, runTimestamp);

        log("done", { mode: "grouping", processed: processedLog.length });
        return { mode: "grouping", processed: processedLog.length };
      }

      // Build a quick-list queue from unassigned
      let quickListQueue = (ulist || [])
        .filter(
          (item) =>
            item && item.tradable && getPrice(item) && item.owners === 1,
        )
        .filter((item) => !item.isFreeCoins?.() && !item.isFreePack?.())
        .filter((item) => {
          if (item.isPlayer?.()) {
            return (
              Number(item.rating) < 85 &&
              !isFodder(item) &&
              !item?.isSpecial?.()
            );
          }
          return !isFodder(item);
        });
      quickListQueue = sortItemsByPriceDesc(quickListQueue);

      log("quickListQueue", {
        count: quickListQueue.length,
        sample: quickListQueue.slice(0, 5).map((it) => ({
          id: it?.id,
          definitionId: it?.definitionId,
          rating: it?.rating,
          price: getPrice(it),
        })),
      });

      if (quickListQueue.length) {
        if (!quickListQueue.length) {
          log("quickListQueue", {
            count: 0,
            reason: "no-matching-after-price",
          });
        } else {
          await clearSoldItemsBeforeTransferActions();
          await processUnsoldTransferItemsByRules();
          void quickListItems(quickListQueue, {
            suppressNotifications: true,
            minDelayMs: 1000,
            maxDelayMs: 1000,
          });
        }

        if (!suppressNavigation) {
          goToUnassignedView();
        }

        // refresh local snapshots after listing + navigation
        storage = await getStoragePlayers();
        ulist = await fetchUnassigned();
        players = await fetchPlayers();

        log("afterQuickList", {
          storageCount: storage?.length ?? 0,
          unassignedCount: ulist?.length ?? 0,
          clubCount: players?.length ?? 0,
        });
      }

      // move to team any storage players not already in club
      const storageToTeam = (storage || []).filter((item) =>
        item?.isMovable?.(),
      );
      const sortedStorageToTeam = sortItemsByPriceDesc(storageToTeam);
      log("storageToTeam", { count: storageToTeam.length });
      if (sortedStorageToTeam.length > 0) {
        services.Item.move(sortedStorageToTeam, 7);
      }

      // filter unassigned by those tradeable definitionIds and ensure uniqueness by definitionId
      const switchTradeable = (ulist || []).filter(
        (l) => l?.isTradeableDuplicate?.() && !l?.tradable,
      );
      const sortedSwitchTradeable = sortItemsByPriceDesc(switchTradeable);
      log("switchTradeable", { count: switchTradeable.length });
      if (sortedSwitchTradeable.length > 0) {
        services.Item.move(sortedSwitchTradeable, 7);
        if (!suppressNavigation) {
          goToUnassignedView();
        }

        storage = await getStoragePlayers();
        ulist = await fetchUnassigned();
        players = await fetchPlayers();

        log("afterSwitchTradeable", {
          storageCount: storage?.length ?? 0,
          unassignedCount: ulist?.length ?? 0,
          clubCount: players?.length ?? 0,
        });
      }

      void ensureLivePrices(processedLog, { awaitCompletion: false });
      console.table(
        processedLog.map(({ item, action, ruleNumber, timestamp }) => ({
          timestamp,
          ruleNumber,
          name: getItemNameSafe(item),
          rating: item?.rating ?? item?._staticData?.rating ?? null,
          price: Number(getPrice(item)) || null,
          rarity: getItemRarityLabel(item),
          isFodder: typeof isFodder === "function" ? isFodder(item) : false,
          isDuplicate:
            Number(item?.duplicateId ?? 0) > 0 || item?.isDuplicate?.(),
          action,
        })),
      );

      appendUnassignedHistoryRows(processedLog, runTimestamp);

      const toTeam = (ulist || []).filter((item) => item?.isMovable?.());
      const sortedToTeam = sortItemsByPriceDesc(toTeam);
      log("toTeam", { count: toTeam.length });
      if (sortedToTeam.length > 0) {
        services.Item.move(sortedToTeam, 7);
      }

      // discard non-player fodder
      const nonPlayerDupes = (ulist || []).filter(
        (l) => !l?.isPlayer?.() && getPrice(l) && getPrice(l) < 551,
      );
      log("nonPlayerDupes", { count: nonPlayerDupes.length });
      if (nonPlayerDupes.length > 0) {
        services.Item.discard(nonPlayerDupes);
        if (!suppressNavigation) {
          goToUnassignedView();
        }

        storage = await getStoragePlayers();
        ulist = await fetchUnassigned();
        players = await fetchPlayers();

        log("afterDiscardNonPlayerDupes", {
          storageCount: storage?.length ?? 0,
          unassignedCount: ulist?.length ?? 0,
          clubCount: players?.length ?? 0,
        });
      }

      // sendDuplicatesToStorage
      const storableDupes = (ulist || [])
        .filter(
          (item) =>
            item?.isStorable?.() &&
            !item?.isMovable?.() &&
            !item?.isTradeable?.(),
        );
      let toStorage;

      if (getSettings(0, 0, "replaceStoragePlayers") && storableDupes.length) {
        const combined = [
          ...(storage || []).map((item) => ({ item, source: "storage" })),
          ...storableDupes.map((item) => ({ item, source: "new" })),
        ].sort((a, b) => {
          const priceDiff = getSortablePrice(b.item) - getSortablePrice(a.item);
          if (priceDiff !== 0) return priceDiff;
          return (b.item?.rating ?? 0) - (a.item?.rating ?? 0);
        });
        const keep = combined.slice(0, 100);
        const discard = combined.slice(100);
        const discardFromStorage = discard.filter((e) => e.source === "storage").map((e) => e.item);
        const discardNew = discard.filter((e) => e.source === "new").map((e) => e.item);
        toStorage = keep.filter((e) => e.source === "new").map((e) => e.item);
        if (discardFromStorage.length) {
          log("replaceStorage:discardOld", { count: discardFromStorage.length });
          services.Item.discard(discardFromStorage);
        }
        if (discardNew.length) {
          log("replaceStorage:discardNew", { count: discardNew.length });
          services.Item.discard(discardNew);
        }
        if (discardFromStorage.length && toStorage.length) {
          await new Promise((r) => setTimeout(r, 2000));
        }
      } else {
        toStorage = sortItemsByPriceDesc(storableDupes)
          .slice(0, Math.max(0, 100 - (storage?.length ?? 0)));
      }

      log("toStorage", { count: toStorage.length });
      if (toStorage.length > 0) {
        services.Item.move(toStorage, 10);
      }

      // discard tradable fodder
      const tradableFodder = (ulist || []).filter(
        (l) =>
          !l?.isMovable?.() &&
          l?.owners === 1 &&
          l?.isPlayer?.() &&
          (getPrice(l) ?? 0) < 800 &&
          l?.tradable &&
          isFodder(l),
      );

      log("tradableFodder", { count: tradableFodder.length });
      if (tradableFodder.length > 0) {
        services.Item.discard(tradableFodder);
        if (!suppressNavigation) {
          goToUnassignedView();
        }
        ulist = await fetchUnassigned();
        log("afterDiscardTradableFodder", {
          unassignedCount: ulist?.length ?? 0,
        });
      }

      // send to transfer
      const transferList = (ulist || []).filter(
        (l) => l?.owners === 1 && (getPrice(l) ?? 0) >= 800 && l?.tradable,
      );
      const sortedTransferList = sortItemsByPriceDesc(transferList);

      log("transferList", { count: transferList.length });
      if (sortedTransferList.length > 0) {
        if (!suppressNavigation) {
          goToUnassignedView();
        }
        await clearSoldItemsBeforeTransferActions();
        services.Item.move(sortedTransferList, 5);
      }
      ratingCountUI();
      log("done");
      return { mode: "default", processed: processedLog.length };
    } catch (error) {
      void runId;
      return { mode: "error", error: String(error) };
    }
  })();

  state.runningPromise = runPromise;
  try {
    const result = await runPromise;
    state.lastResult = result;
    state.lastRunAt = Date.now();
    return result;
  } finally {
    state.runningPromise = null;
  }
};
let fetchUnassigned = () => {
  repositories.Item.unassigned.clear();
  repositories.Item.unassigned.reset();

  return new Promise((resolve) => {
    let result = [];
    services.Item.requestUnassignedItems().observe(
      undefined,
      async (sender, response) => {
        result = [...response.response.items];
        fetchPlayerPrices(result, {
          waitForCompletion: false,
          suppressNotification: true,
        });

        // Update the recent-special strip immediately when unassigned items are
        // fetched (don't wait for processUnassigned to run).
        if (typeof window.recordRecentPackedSpecials === "function") {
          window.recordRecentPackedSpecials(result);
        }

        // Detect any newly received Collection Book players (packs land here
        // before they reach the club).
        if (typeof collectionBookScanItems === "function") {
          collectionBookScanItems(result);
        }

        // Persist ownership (definitionId + entity id) so duplicates in the
        // unassigned pile increment the Collection Book counter.
        if (typeof collectionBookRecordOwnership === "function") {
          collectionBookRecordOwnership(result);
        }

        resolve(result);
      },
    );
  });
};

let fetchTransferList = () => {
  return new Promise((resolve) => {
    let result = [];
    services.Item.requestTransferItems().observe(
      undefined,
      async (sender, response) => {
        result = [...response.response.items];

        resolve(result);
      },
    );
  });
};
let fetchDuplicateIds = () => {
  return new Promise((resolve) => {
    const result = [];
    repositories.Store.setDirty();
    services.Item.requestUnassignedItems().observe(
      undefined,
      (sender, response) => {
        const isChemistryStyleOrManagerLeague = (item) => {
          // Use SearchType for exact classification instead of name matching
          if (typeof item?.getSearchType === "function") {
            const searchType = String(item.getSearchType() || "").toUpperCase();
            // Filter out chemistry styles and manager consumables
            return searchType.includes("CHEMISTRY") || searchType.includes("MANAGER");
          }
          
          // Fallback to name-based detection if getSearchType unavailable
          const name = String(
            item?._staticData?.name || item?.name || "",
          ).toLowerCase();
          return (
            name.includes("chemistry style") ||
            name.includes("manager league") ||
            name.includes("league manager")
          );
        };

        const duplicates = [
           ...response.response.items.filter(
            (item) =>
              item.duplicateId > 0 &&
              !isChemistryStyleOrManagerLeague(item),
           ),
        ];
        result.push(...duplicates.map((duplicate) => duplicate.duplicateId));

        resolve(result);
      },
    );
  });
};
const getPreviewSectionActionLabel = (action) => {
  const labels = {
    freeItems: "Redeem all",
    sendToClub: "Send all to club",
    sendToTransferList: "Send all to transfer list",
    quickSell: "Quick sell all",
    listOnTransferMarket: "List all on market",
    sendToStorage: "Send all to storage",
    doNothing: "Skip all",
  };

  return labels[action] || "Process all";
};

const ensureSectionHeaderButtonVisible = (sectionView) => {
  try {
    sectionView?.showBulkActionButton?.();
  } catch {}

  try {
    sectionView?.toggleHeaderButton?.(true);
  } catch {}

  try {
    sectionView?.toggleHeaderButtonEnabled?.(true);
  } catch {}

  const headerRoot = sectionView?._header?.getRootElement?.();
  const actionButtonRoot =
    sectionView?._header?._actionButton?.getRootElement?.();

  if (headerRoot) {
    headerRoot.style.display = "";
    headerRoot.style.visibility = "";
  }

  if (actionButtonRoot) {
    actionButtonRoot.style.display = "";
    actionButtonRoot.style.visibility = "";
    actionButtonRoot.style.opacity = "";
    actionButtonRoot.disabled = false;
    actionButtonRoot.removeAttribute("disabled");
  }
};

const setPreviewSectionHeaderAction = (
  sectionView,
  title,
  actionLabel,
  callback,
) => {
  if (!sectionView) {
    return;
  }

  const hasSetActionHeader = typeof sectionView.setActionHeader === "function";
  const hasSetBulkHeader = typeof sectionView.setBulkHeader === "function";

  if (hasSetActionHeader) {
    sectionView.setActionHeader(title, actionLabel, callback);
  } else if (hasSetBulkHeader) {
    sectionView.setBulkHeader(title, actionLabel, callback);
  }

  ensureSectionHeaderButtonVisible(sectionView);
};

const previewHasValidPrice = (item) => {
  const price = Number(getPrice(item));
  return Number.isFinite(price) && price > 0;
};

const reprocessPreviewMissingPriceItems = async (controller, items, rules) => {
  if (!items.length || !Array.isArray(rules) || !rules.length) {
    return;
  }

  try {
    await Promise.all(
      items
        .filter((item) => Number(item?.definitionId) > 0)
        .map(async (item) => {
          try {
            await fetchLivePlayerPrice(item);
          } catch {}
        }),
    );

    const isTradable = (item) =>
      item?.tradable === true ||
      (typeof item?.isTradeable === "function" && item.isTradeable());

    const actionBuckets = {
      sendToClub: [],
      sendToTransferList: [],
      sendToStorage: [],
      quickSell: [],
      listOnTransferMarket: [],
    };

    items.forEach((item) => {
      const matchedRule = (rules || []).find(
        (rule) => rule?.enabled !== false && matchesUnassignedRule(item, rule),
      );

      if (!matchedRule) {
        return;
      }

      const action = matchedRule.action || "sendToClub";

      if (action === "sendToClub" && item?.isMovable?.()) {
        actionBuckets.sendToClub.push(item);
      } else if (action === "sendToTransferList" && isTradable(item)) {
        actionBuckets.sendToTransferList.push(item);
      } else if (action === "sendToStorage" && item?.isStorable?.()) {
        actionBuckets.sendToStorage.push(item);
      } else if (action === "quickSell") {
        actionBuckets.quickSell.push(item);
      } else if (action === "listOnTransferMarket" && isTradable(item)) {
        actionBuckets.listOnTransferMarket.push(item);
      }
    });

    if (actionBuckets.sendToClub.length) {
      services.Item.move(actionBuckets.sendToClub, 7);
    }
    if (actionBuckets.sendToTransferList.length) {
      services.Item.move(actionBuckets.sendToTransferList, 5);
    }
    if (actionBuckets.sendToStorage.length) {
      services.Item.move(actionBuckets.sendToStorage, 10);
    }
    if (actionBuckets.quickSell.length) {
      services.Item.discard(actionBuckets.quickSell);
    }
    if (actionBuckets.listOnTransferMarket.length) {
      if (typeof quickListItems === "function") {
        void quickListItems(actionBuckets.listOnTransferMarket, {
          suppressNotifications: true,
          minDelayMs: 1000,
          maxDelayMs: 1000,
        });
      }
    }

    const total =
      actionBuckets.sendToClub.length +
      actionBuckets.sendToTransferList.length +
      actionBuckets.sendToStorage.length +
      actionBuckets.quickSell.length +
      actionBuckets.listOnTransferMarket.length;

    if (total > 0) {
      try {
        controller?.getUnassignedItems?.(false);
      } catch {}
    }

    console.log("[previewReprocess] pending price items resolved", {
      sendToClub: actionBuckets.sendToClub.length,
      sendToTransferList: actionBuckets.sendToTransferList.length,
      sendToStorage: actionBuckets.sendToStorage.length,
      quickSell: actionBuckets.quickSell.length,
      listOnTransferMarket: actionBuckets.listOnTransferMarket.length,
    });
  } catch (err) {
    console.warn("[previewReprocess] failed", err);
  }
};

const processPreviewSectionAction = async (controller, section) => {
  const items = (section?.items || []).filter(Boolean);
  const action = section?.action;
  const sectionLabel = section?.label || "section";

  if (!items.length) {
    showNotification(`No items in ${sectionLabel}`, UINotificationType.NEUTRAL);
    return;
  }

  const isTradable = (item) =>
    item?.tradable === true ||
    (typeof item?.isTradeable === "function" && item.isTradeable());

  const rules =
    typeof getUnassignedRules === "function" ? getUnassignedRules() : [];

  let processedCount = 0;
  let missingPriceItems = [];

  if (action === "freeItems") {
    const redeemable = items.filter(
      (item) => item?.isFreeCoins?.() || item?.isFreePack?.(),
    );
    redeemable.forEach((item) => services.Item.redeem(item));
    processedCount = redeemable.length;
  } else if (action === "sendToClub") {
    const movable = items.filter((item) => item?.isMovable?.());
    services.Item.move(movable, 7);
    processedCount = movable.length;
    missingPriceItems = items.filter((item) => !previewHasValidPrice(item));
  } else if (action === "sendToTransferList") {
    const tradable = items.filter((item) => isTradable(item));
    services.Item.move(tradable, 5);
    processedCount = tradable.length;
    missingPriceItems = items.filter((item) => !previewHasValidPrice(item));
  } else if (action === "sendToStorage") {
    const storable = items.filter((item) => item?.isStorable?.());
    services.Item.move(storable, 10);
    processedCount = storable.length;
    missingPriceItems = items.filter((item) => !previewHasValidPrice(item));
  } else if (action === "quickSell") {
    const priced = items.filter((item) => previewHasValidPrice(item));
    const unpriced = items.filter((item) => !previewHasValidPrice(item));
    if (priced.length) {
      services.Item.discard(priced);
    }
    processedCount = priced.length;
    missingPriceItems = unpriced;
    if (unpriced.length) {
      showNotification(
        `${unpriced.length} item(s) held — waiting for price`,
        UINotificationType.NEUTRAL,
      );
    }
  } else if (action === "listOnTransferMarket") {
    const tradable = items.filter((item) => isTradable(item));
    if (!tradable.length) {
      showNotification("No tradable items to list", UINotificationType.NEUTRAL);
      return;
    }

    if (typeof quickListItems !== "function") {
      showNotification(
        "Quick list is unavailable",
        UINotificationType.NEGATIVE,
      );
      return;
    }

    void quickListItems(tradable, {
      maxCount: tradable.length,
      showNotifications: true,
    });
    processedCount = tradable.length;
    missingPriceItems = items.filter((item) => !previewHasValidPrice(item));
  } else {
    processedCount = 0;
  }

  if (processedCount > 0) {
    showNotification(
      `${sectionLabel}: ${processedCount} processed`,
      UINotificationType.POSITIVE,
    );
  } else if (!missingPriceItems.length) {
    showNotification(
      `No items processed for ${sectionLabel}`,
      UINotificationType.NEUTRAL,
    );
  }

  if (missingPriceItems.length) {
    void reprocessPreviewMissingPriceItems(
      controller,
      missingPriceItems,
      rules,
    );
  }

  try {
    controller?.getUnassignedItems?.(false);
  } catch {}
};

const unassignedPreviewOverride = () => {
  if (UTUnassignedItemsViewController.prototype.__sbcPreviewPatched) {
    return;
  }
  UTUnassignedItemsViewController.prototype.__sbcPreviewPatched = true;

  const originalRenderView =
    UTUnassignedItemsViewController.prototype.renderView;
  UTUnassignedItemsViewController.prototype.renderView = function () {
    const rules =
      typeof getUnassignedRules === "function" ? getUnassignedRules() : [];
    if (!rules.length || !isUnassignedGroupingEnabled?.()) {
      return originalRenderView.call(this);
    }

    if (!this.viewmodel || this.viewmodel.length === 0) {
      return originalRenderView.call(this);
    }

    const view = this.getView?.();
    if (!view || typeof view.renderSection !== "function") {
      return originalRenderView.call(this);
    }

    const regular = this.viewmodel?.getRegularItemsSection?.() || [];
    const duplicates = this.viewmodel?.getDuplicateSection?.() || [];
    const untradeables =
      this.viewmodel?.getUntradeableDuplicateSection?.() || [];
    const allItems = [...regular, ...duplicates, ...untradeables];
    const { sections } = groupUnassignedItemsByRules(allItems, rules, {
      includeFreeItems: true,
      includeDoNothing: true,
      matcherOptions: { assumeMinPriceWhenMissing: true },
    });
    if (!sections.length) {
      return originalRenderView.call(this);
    }

    view.clearSections();
    sections.forEach((section, index) => {
      const sectionView = view.renderSection(
        section.items,
        index,
        this.eListRowSelected.bind(this),
      );
      if (sectionView) {
        setPreviewSectionHeaderAction(
          sectionView,
          section.label,
          getPreviewSectionActionLabel(section.action),
          async () => {
            try {
              await processPreviewSectionAction(this, section);
            } catch (error) {
              console.error("Unassigned preview section action failed", error);
              showNotification(
                "Failed to process section",
                UINotificationType.NEGATIVE,
              );
            }
          },
        );
        sectionView.removeFooter?.();
      }
    });

    if (!isPhone()) {
      const current = this.viewmodel.current?.();
      const currentId = current?.id;
      if (JSUtils.isNumber(currentId)) {
        view.selectListRow(currentId);
      }
    }
  };
};
// Loader overlay functions for displaying solver progress and status

// Helper to safely get the shield element
const getShield = () => {
  let shield = getElement(".ut-click-shield");
  if (!shield) {
    console.warn("Shield element not found");
  }
  return shield;
};

const AUTO_SBC_BACKGROUND_STATUS_ICON_ID = "autosbc-background-status-icon";

const ensureBackgroundSolveStatusIcon = () => {
  let icon = document.getElementById(AUTO_SBC_BACKGROUND_STATUS_ICON_ID);
  if (!icon) {
    icon = document.createElement("div");
    icon.id = AUTO_SBC_BACKGROUND_STATUS_ICON_ID;
    icon.classList.add("autosbc-background-status-icon");
    icon.setAttribute("aria-label", "Auto SBC background status");
    icon.setAttribute("title", "Auto SBC background run");
    document.body.appendChild(icon);
  }
  return icon;
};

const refreshBackgroundSolveStatusIcon = () => {
  const icon = ensureBackgroundSolveStatusIcon();
  if (!icon) {
    return;
  }

  const status = window.__autoSbcSolveStatus;
  const runInBackground = !!window.__autoSbcSolveRunInBackground;

  icon.classList.remove(
    "autosbc-bg-status--solving",
    "autosbc-bg-status--feasible",
    "autosbc-bg-status--optimal",
  );

  if (!runInBackground || !status) {
    icon.style.display = "none";
    return;
  }

  if (status === "solving") {
    icon.classList.add("autosbc-bg-status--solving");
  } else if (status === "feasible") {
    icon.classList.add("autosbc-bg-status--feasible");
  } else if (status === "optimal") {
    icon.classList.add("autosbc-bg-status--optimal");
  }

  icon.style.display = "flex";
};

window.refreshBackgroundSolveStatusIcon = refreshBackgroundSolveStatusIcon;

// Helper to ensure the .numCounter element exists
const ensureNumCounterExists = () => {
  let numCounter = document.querySelector(".numCounter");
  if (!numCounter) {
    const shield = getShield();
    if (shield) {
      numCounter = document.createElement("div");
      numCounter.classList.add("numCounter");
      numCounter.addEventListener("click", () => {
        if (typeof cancelActiveSolveRun === "function") {
          cancelActiveSolveRun();
        } else {
          createSbc = false;
          hideLoader();
        }
      });
      shield.appendChild(numCounter);
    }
  }
  return numCounter;
};

const addSbcInfo = (sbcName, challengeName) => {
  const shield = getShield();
  if (!shield) return;

  let existingInfo = document.getElementById("sbc-info");
  if (existingInfo) {
    existingInfo.remove();
  }

  if (!sbcName) return;

  let infoDiv = document.createElement("div");
  infoDiv.id = "sbc-info";
  infoDiv.style.position = "fixed";
  infoDiv.style.bottom = "10px";
  infoDiv.style.left = "160px";
  infoDiv.style.backgroundColor = "rgba(0, 0, 0, 0.8)";
  infoDiv.style.color = "white";
  infoDiv.style.padding = "10px 20px";
  infoDiv.style.borderRadius = "5px";
  infoDiv.style.fontSize = "1.2rem";
  infoDiv.style.fontWeight = "bold";
  infoDiv.style.textAlign = "center";
  infoDiv.style.zIndex = "9999";

  let title = document.createElement("div");
  title.textContent = sbcName || "SBC";
  infoDiv.appendChild(title);

  if (challengeName && challengeName !== sbcName) {
    let subtitle = document.createElement("div");
    subtitle.textContent = challengeName;
    subtitle.style.fontSize = "1rem";
    subtitle.style.opacity = "0.8";
    infoDiv.appendChild(subtitle);
  }

  shield.appendChild(infoDiv);
};

const clearSbcInfo = () => {
  const sbcNames = document.querySelectorAll("#sbc-info");
  sbcNames.forEach((sbcName) => {
    sbcName.remove();
  });
};

const showLoader = (countdown = false) => {
  refreshBackgroundSolveStatusIcon();

  const clickShield = document.querySelector(".ut-click-shield");
  if (clickShield) {
    clickShield.classList.add("showing");
  }

  const loaderIcon = document.querySelector(".loaderIcon");
  if (loaderIcon) {
    loaderIcon.style.display = "block";
  }

  // Only show overlay details when actively solving an SBC (countdown = true)
  if (countdown) {
    // Ensure numCounter element exists before trying to show it
    ensureNumCounterExists();

    // Show overlay UI controls
    createLogOverlayToggle();
    updateLogOverlay();
    createStopOverlayButton();

    const numCounterElement = document.querySelector(".numCounter");
    if (numCounterElement) {
      numCounterElement.style.display = "block";
    }
  } else {
    // Hide all overlay details when not solving
    clearSbcInfo();

    const stopButtons = document.querySelectorAll("#sbc-stop-overlay");
    const grindActive =
      typeof createSbcGrind !== "undefined" && createSbcGrind;
    stopButtons.forEach((stopButton) => {
      if (grindActive) return; // keep stop button visible while grind is running
      stopButton.remove();
    });

    const toggleContainers = document.querySelectorAll("#sbc-log-toggle");
    toggleContainers.forEach((toggleContainer) => {
      toggleContainer.remove();
    });

    let logOverlay = document.getElementById("sbc-log-overlay");
    if (logOverlay) {
      logOverlay.remove();
    }

    const numCounterElement = document.querySelector(".numCounter");
    if (numCounterElement) {
      numCounterElement.style.display = "none";
    }
  }
};

const hideLoader = () => {
  if (window.__autoSbcHoldLoaderUntilFinal === true) {
    return;
  }

  // Only guard against active solve run / active context when the loader hold
  // is still in effect. Once the solve has cleared the hold (by calling
  // setSolveLoaderHoldUntilFinal(false)) we must allow the loader to hide,
  // even if createSbc/activeSolveContext haven't been torn down yet.
  if (window.__autoSbcHoldLoaderUntilFinal === true) {
    // Don't hide loader during active solve runs (allows interim solutions to update UI)
    if (
      typeof window.__autoSbcIsSolveRunActive === "function" &&
      window.__autoSbcIsSolveRunActive()
    ) {
      return;
    }

    // Also keep loader visible while a solve context exists (interim squad apply
    // navigation can transiently toggle solve-active flags).
    if (
      typeof window.__autoSbcActiveSolveContext === "function" &&
      window.__autoSbcActiveSolveContext()
    ) {
      return;
    }
  }

  const stopButtons = document.querySelectorAll("#sbc-stop-overlay");
  const grindRunning =
    typeof createSbcGrind !== "undefined" && createSbcGrind;
  stopButtons.forEach((stopButton) => {
    if (grindRunning) return; // keep stop button visible while grind is running
    stopButton.remove();
  });
  clearSbcInfo();
  const toggleContainers = document.querySelectorAll("#sbc-log-toggle");
  toggleContainers.forEach((toggleContainer) => {
    toggleContainer.remove();
  });

  let logOverlay = document.getElementById("sbc-log-overlay");
  if (logOverlay) {
    logOverlay.remove();
  }

  // Only clear counter if it exists
  if (typeof counter !== "undefined" && counter !== null) {
    try {
      counter = null;
    } catch (error) {
      console.warn("Error clearing counter:", error);
    }
  }

  document.querySelectorAll(".numCounter").forEach((element) => {
    element.remove();
  });

  const clickShield = document.querySelector(".ut-click-shield");
  if (clickShield) {
    clickShield.classList.remove("showing");
  }

  const loaderIcon = document.querySelector(".loaderIcon");
  if (loaderIcon) {
    loaderIcon.style.display = "none";
  }

  refreshBackgroundSolveStatusIcon();

  // Clear intervals with null checks
  if (typeof logPollInterval !== "undefined" && logPollInterval !== null) {
    clearInterval(logPollInterval);
  }
  if (typeof countDownInterval !== "undefined" && countDownInterval !== null) {
    clearInterval(countDownInterval);
  }
};

const createStopOverlayButton = () => {
  // Don't create a duplicate if already present
  if (document.getElementById("sbc-stop-overlay")) return;

  // When auto grind is running, attach to body so the button persists
  // independently of the shield's visibility between grind cycles.
  const grindActive =
    typeof createSbcGrind !== "undefined" && createSbcGrind;
  const parent = grindActive ? document.body : getShield();
  if (!parent) return;

  const stopButtonContainer = document.createElement("div");
  stopButtonContainer.id = "sbc-stop-overlay";
  stopButtonContainer.style.position = "fixed";
  stopButtonContainer.style.bottom = "45px";
  stopButtonContainer.style.right = "130px";
  stopButtonContainer.style.backgroundColor = "rgba(0, 0, 0, 0.8)";
  stopButtonContainer.style.color = "#fff";
  stopButtonContainer.style.padding = "10px";
  stopButtonContainer.style.borderRadius = "5px";
  stopButtonContainer.style.zIndex = "9999";
  stopButtonContainer.style.fontSize = "12px";
  stopButtonContainer.style.fontFamily = "Arial, sans-serif";

  const stopButton = document.createElement("button");
  stopButton.textContent = "STOP";
  stopButton.style.marginLeft = "5px";
  stopButton.style.padding = "5px 10px";
  stopButton.style.border = "none";
  stopButton.style.borderRadius = "3px";
  stopButton.style.cursor = "pointer";
  stopButton.style.backgroundColor = "#ff0000";
  stopButton.style.color = "#000";

  stopButton.addEventListener("click", () => {
    if (typeof cancelActiveSolveRun === "function") {
      cancelActiveSolveRun();
    } else {
      createSbc = false;
      createSbcGrind = false;
      window.__autoSbcHoldLoaderUntilFinal = false;
      hideLoader();
    }
  });

  stopButtonContainer.appendChild(stopButton);
  parent.appendChild(stopButtonContainer);
};

const createLogOverlayToggle = () => {
  const shield = getShield();
  if (!shield) return;

  const toggleContainer = document.createElement("div");
  toggleContainer.id = "sbc-log-toggle";
  toggleContainer.style.position = "fixed";
  toggleContainer.style.bottom = "10px";
  toggleContainer.style.left = "10px";
  toggleContainer.style.backgroundColor = "rgba(0, 0, 0, 0.8)";
  toggleContainer.style.color = "#fff";
  toggleContainer.style.padding = "10px";
  toggleContainer.style.borderRadius = "5px";
  toggleContainer.style.zIndex = "9999";
  toggleContainer.style.fontSize = "12px";
  toggleContainer.style.fontFamily = "Arial, sans-serif";

  const toggleLabel = document.createElement("span");
  toggleLabel.textContent = "Show Solver Logs";
  toggleContainer.appendChild(toggleLabel);

  const toggleButton = document.createElement("button");
  toggleButton.textContent = getSettings(0, 0, "showLogOverlay") ? "ON" : "OFF";
  toggleButton.style.marginLeft = "5px";
  toggleButton.style.padding = "5px 10px";
  toggleButton.style.border = "none";
  toggleButton.style.borderRadius = "3px";
  toggleButton.style.cursor = "pointer";
  toggleButton.style.backgroundColor = getSettings(0, 0, "showLogOverlay")
    ? "#00ff00"
    : "#ff0000";
  toggleButton.style.color = "#000";

  toggleButton.addEventListener("click", () => {
    const currentState = getSettings(0, 0, "showLogOverlay");
    saveSettings(0, 0, "showLogOverlay", !currentState);
    toggleButton.textContent = !currentState ? "ON" : "OFF";
    toggleButton.style.backgroundColor = !currentState ? "#00ff00" : "#ff0000";
    updateLogOverlay();
  });

  toggleContainer.appendChild(toggleButton);
  shield.appendChild(toggleContainer);
};

// Create or update the log overlay
const updateLogOverlay = () => {
  const shield = getShield();
  if (!shield) return;

  let logOverlay = document.getElementById("sbc-log-overlay");

  if (getSettings(0, 0, "showLogOverlay")) {
    if (!logOverlay) {
      logOverlay = document.createElement("div");
      logOverlay.id = "sbc-log-overlay";
      logOverlay.style.position = "fixed";
      logOverlay.style.bottom = "75px";
      logOverlay.style.left = "10px";
      logOverlay.style.maxHeight = "15vh";
      logOverlay.style.width = "40vw";
      logOverlay.style.overflowY = "auto";
      logOverlay.style.backgroundColor = "rgba(0, 0, 0, 0.8)";
      logOverlay.style.color = "#00ff00";
      logOverlay.style.padding = "10px";
      logOverlay.style.fontSize = "12px";
      logOverlay.style.fontFamily = "monospace";
      logOverlay.style.zIndex = "9999";
      logOverlay.style.borderRadius = "5px";
      logOverlay.style.border = "1px solid #00ff00";

      shield.appendChild(logOverlay);
    }
    logOverlay.style.display = "block";
  } else if (logOverlay) {
    logOverlay.style.display = "none";
  }
};

// Setup a variable to track the last log we've seen
let lastLogIndex = 0;

// Function to poll for solver logs
const pollSolverLogs = async () => {
  try {
    const response = await makeGetRequest(apiUrl + "/solver-logs");
    const data = JSON.parse(response);
    const showOverlay = getSettings(0, 0, "showLogOverlay");

    // Ensure log overlay exists if we need to show logs
    if (showOverlay) {
      updateLogOverlay();
    }

    // We have new logs
    const logOverlay = document.getElementById("sbc-log-overlay");
    if (showOverlay && lastLogIndex === 0 && logOverlay) {
      while (logOverlay.firstChild) {
        logOverlay.removeChild(logOverlay.firstChild);
      }
    }

    if (data.logs && data.logs.length > lastLogIndex) {
      for (let i = lastLogIndex; i < data.logs.length; i++) {
        const log = data.logs[i];
        const resultPayload = log?.result;

        // Handle interim solutions
        if (
          resultPayload &&
          typeof resultPayload === "object" &&
          resultPayload.event === "interim_solution" &&
          typeof window.applyInterimSolverSolutionFromLog === "function"
        ) {
          try {
            await window.applyInterimSolverSolutionFromLog(resultPayload);
          } catch (error) {
            console.error("Error applying interim solution:", error);
          }
        }

        // Add log entry to overlay if visible
        if (showOverlay) {
          const logOverlay = document.getElementById("sbc-log-overlay");
          if (logOverlay) {
            try {
              const timestamp = new Date(log.time * 1000)
                .toISOString()
                .split("T")[1]
                .slice(0, -1);

              const logEntry = document.createElement("div");
              logEntry.className = "solver-log";
              logEntry.style.marginBottom = "5px";

              if (log.message) {
                logEntry.textContent = `${timestamp}: ${log.message}`;
              }

              logOverlay.insertBefore(logEntry, logOverlay.firstChild);

              // Keep only last 100 log entries to avoid performance issues
              while (logOverlay.children.length > 100) {
                logOverlay.removeChild(logOverlay.lastChild);
              }
            } catch (error) {
              console.error("Error adding log entry:", error);
            }
          }
        }
      }

      lastLogIndex = data.logs.length;
    }
  } catch (error) {
    console.error("Error polling solver logs:", error);
  }
};
// FUTsutoGrind - Auto-grind automation for running favorite SBCs in a loop
let createSbcGrind = false;
let futAutoGrindWakeLockSentinel = null;
let futAutoGrindWakeLockBound = false;
const AUTO_GRIND_SUBMIT_LIMIT_60M = 90;
const AUTO_GRIND_SUBMIT_LIMIT_24H = 2400000;
const AUTO_GRIND_SUBMIT_CHECK_INTERVAL_MS = 60 * 1000;

const autoGrindDelay = (ms) =>
  new Promise((resolve) => setTimeout(resolve, Math.max(0, ms)));

const getAutoGrindSubmitCounts = () => {
  try {
    const counts = getSbcSubmitTrackerCounts();
    return {
      last60m: Number(counts?.last60m) || 0,
      last24h: Number(counts?.last24h) || 0,
    };
  } catch {
    return { last60m: 0, last24h: 0 };
  }
};

const getAutoGrindSubmitPauseState = () => {
  const counts = getAutoGrindSubmitCounts();
  return {
    ...counts,
    shouldPause:
      counts.last60m >= AUTO_GRIND_SUBMIT_LIMIT_60M ||
      counts.last24h >= AUTO_GRIND_SUBMIT_LIMIT_24H,
  };
};

const waitForAutoGrindSubmitWindow = async (log) => {
  let notifiedPaused = false;

  while (createSbcGrind) {
    const pauseState = getAutoGrindSubmitPauseState();
    if (!pauseState.shouldPause) {
      if (notifiedPaused) {
        showNotification(
          `Auto-grind resumed (60m: ${pauseState.last60m}/${AUTO_GRIND_SUBMIT_LIMIT_60M}, 24h: ${pauseState.last24h}/${AUTO_GRIND_SUBMIT_LIMIT_24H})`,
          UINotificationType.POSITIVE,
        );
        log("submitLimit:resume", pauseState);
      }
      return true;
    }

    if (!notifiedPaused) {
      notifiedPaused = true;
      showNotification(
        `Auto-grind paused: submit limit reached (60m ${pauseState.last60m}/${AUTO_GRIND_SUBMIT_LIMIT_60M}, 24h ${pauseState.last24h}/${AUTO_GRIND_SUBMIT_LIMIT_24H}). Rechecking every minute.`,
        UINotificationType.NEUTRAL,
      );
      log("submitLimit:pause", pauseState);
    } else {
      log("submitLimit:still-paused", pauseState);
    }

    // Use short polling intervals (500ms) instead of one long 60s wait.
    // This allows the stop button to take effect immediately instead of waiting up to 60s.
    const pollInterval = 500;
    const pollCount = AUTO_GRIND_SUBMIT_CHECK_INTERVAL_MS / pollInterval;
    for (let i = 0; i < pollCount; i++) {
      if (!createSbcGrind) {
        return false; // Stop button was clicked
      }
      await autoGrindDelay(pollInterval);
    }
  }

  return false;
};

const acquireFutAutoGrindWakeLock = async () => {
  try {
    if (!createSbcGrind) return;
    if (!navigator?.wakeLock?.request) return;
    if (document.visibilityState !== "visible") return;
    if (futAutoGrindWakeLockSentinel) return;

    futAutoGrindWakeLockSentinel = await navigator.wakeLock.request("screen");
    futAutoGrindWakeLockSentinel?.addEventListener?.("release", () => {
      futAutoGrindWakeLockSentinel = null;
    });
  } catch (err) {
    console.warn("[autoGrind] wake lock request failed", err);
  }
};

const releaseFutAutoGrindWakeLock = async () => {
  try {
    if (futAutoGrindWakeLockSentinel) {
      await futAutoGrindWakeLockSentinel.release();
    }
  } catch (err) {
    console.warn("[autoGrind] wake lock release failed", err);
  } finally {
    futAutoGrindWakeLockSentinel = null;
  }
};

const bindFutAutoGrindWakeLockLifecycle = () => {
  if (futAutoGrindWakeLockBound) return;
  futAutoGrindWakeLockBound = true;

  document.addEventListener("visibilitychange", () => {
    if (!createSbcGrind) return;
    if (document.visibilityState === "visible") {
      acquireFutAutoGrindWakeLock();
    }
  });
};

const futAutoGrind = async () => {
  const runId = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  let cycle = 0;

  const log = (step, data = {}) => {
    // Keep logs consistent + searchable
    console.log(`[autoGrind:${runId}] ${step}`, {
      cycle,
      createSbcGrind,
      ...data,
    });
  };

  const safe = async (step, fn) => {
    const start = performance.now();
    log(`${step}:start`);
    try {
      const result = await fn();
      log(`${step}:ok`, { ms: Math.round(performance.now() - start) });
      return { ok: true, result };
    } catch (err) {
      log(`${step}:ERROR`, { ms: Math.round(performance.now() - start), err });
      return { ok: false, err };
    }
  };

  const processPostSbcRewards = async (contextLabel, sbcId = 0) => {
    let latestUnassigned = [];
    let pickDrainIteration = 0;
    let previousPickCount = null;
    let stagnantPickIterations = 0;

    while (createSbcGrind) {
      pickDrainIteration += 1;

      const unassignedRes = await safe(
        `fetchUnassigned() (${contextLabel}:pickDrain:${pickDrainIteration})`,
        () => fetchUnassigned(),
      );
      latestUnassigned = unassignedRes.ok ? unassignedRes.result : [];
      const pendingPicks = latestUnassigned.filter((item) =>
        item.isPlayerPickItem(),
      );

      log("unassigned:afterSolve", {
        contextLabel,
        pickDrainIteration,
        unassignedCount: latestUnassigned.length,
        pendingPicks: pendingPicks.map((p) => p.definitionId),
        autoConfirmPicks: !!getSettings(sbcId, 0, "autoConfirmPicks"),
      });

      if (!pendingPicks.length) {
        break;
      }

      if (previousPickCount !== null && pendingPicks.length >= previousPickCount) {
        stagnantPickIterations += 1;
      } else {
        stagnantPickIterations = 0;
      }
      previousPickCount = pendingPicks.length;

      if (stagnantPickIterations >= 3) {
        log("picks:break (stagnant)", {
          contextLabel,
          pendingPickCount: pendingPicks.length,
        });
        break;
      }

      for (const pick of pendingPicks) {
        if (!createSbcGrind) {
          log("picks:break (createSbcGrind turned false)", { contextLabel });
          break;
        }
        log("openPick:start", {
          contextLabel,
          pickDrainIteration,
          pickId: pick.definitionId,
        });
        await safe(`openPick(${pick.definitionId})`, () =>
          openPick(pick.definitionId, sbcId, 0),
        );
      }
    }

    const freeCoins = latestUnassigned.filter((item) => item.isFreeCoins());
    if (freeCoins.length) {
      log("freeCoins:redeem", {
        contextLabel,
        count: freeCoins.length,
      });
      for (const coin of freeCoins) {
        await safe(`services.Item.redeem(${coin.definitionId})`, () =>
          new Promise((resolve, reject) => {
            services.Item.redeem(coin).observe(null, function (obs, res) {
              obs?.unobserve?.(null);
              res?.success ? resolve(res) : reject(res);
            });
          }),
        );
      }
    } else {
      log("freeCoins:none", { contextLabel });
    }

    const shouldOpenAllPacks =
      getSettings(0, 0, "autoGrindOpenAllPacks") !== false;

    log("packs:setting", {
      contextLabel,
      autoGrindOpenAllPacks: shouldOpenAllPacks,
    });

    if (!shouldOpenAllPacks) {
      return;
    }

    const [packsRes, unassignedCountRes] = await Promise.all([
      safe(`getPacks() (${contextLabel})`, () => getPacks()),
      safe(`fetchUnassigned() (pre-pack:${contextLabel})`, () => fetchUnassigned()),
    ]);

    const packs = packsRes.ok ? packsRes.result : null;
    const unassignedCount = unassignedCountRes.ok
      ? unassignedCountRes.result
      : [];

    const myPacks = (packs?.packs || []).filter((p) => p?.isMyPack);
    const myPack = myPacks[0];

    log("packs:check", {
      contextLabel,
      ownedPackCount: myPacks.length,
      hasMyPack: !!myPack,
      myPackId: myPack?.id,
      myPackName: myPack?.packName,
      unassignedCount: unassignedCount.length,
    });

    if (!myPack) {
      return;
    }

    let i = services.Localization;
    services.Notification.queue(
      ["Opening Pack:  " + i.localize(myPack.packName)],
      UINotificationType.POSITIVE,
    );

    const openPackRes = await safe(`openPack(allMyPacks:${contextLabel})`, () =>
      openPack(myPack, 0, true),
    );

    if (!openPackRes.ok) {
      log("packs:continueAfterFailure", { contextLabel });
      return;
    }

    if (openPackRes.result?.skipped) {
      log("packs:blocked", {
        contextLabel,
        reason: openPackRes.result.reason,
      });
    }
  };

  try {
    bindFutAutoGrindWakeLockLifecycle();
    await acquireFutAutoGrindWakeLock();

    services.Notification.queue(
      ["Starting auto‐grind for favorites…"],
      UINotificationType.POSITIVE,
    );

    log("entered");

    // loop until user clicks STOP
    while (createSbcGrind) {
      const canContinue = await waitForAutoGrindSubmitWindow(log);
      if (!canContinue) {
        break;
      }

      cycle += 1;
      log("cycle:start");

      const sbcsRes = await safe("sbcSets()", () => sbcSets());
      if (!sbcsRes.ok) {
        log("cycle:stop (failed to fetch sbcSets)");
        break;
      }
      const sbcs = sbcsRes.result;

      // get favourites and run 1 sbc of each continuously, opening packs in between
      const favourites = (sbcs?.sets || [])
        .filter((f) => f.isFavourite && !f.isComplete())
        .map((m) => m.id);

      log("favourites:computed", { count: favourites.length, favourites });

      if (!favourites.length) {
        showNotification("No favorite SBCs found", UINotificationType.NEGATIVE);
        log("cycle:return (no favourites)");
        return;
      }

      for (const fav of favourites) {
        const canContinue = await waitForAutoGrindSubmitWindow(log);
        if (!canContinue) {
          break;
        }

        log("fav:start", {
          fav,
          name: sbcs?.sets?.find((s) => s.id == fav)?.name,
        });

        if (!createSbcGrind) {
          log("fav:break (createSbcGrind turned false before start)");
          break;
        }

        // Fetch storage and club players in parallel (ratingCountUI deferred to end of cycle)
        const [storageRes, playersRes] = await Promise.all([
          safe("getStoragePlayers()", () => getStoragePlayers()),
          safe("fetchPlayers()", () => fetchPlayers()),
        ]);

        const storageNow = storageRes.ok ? storageRes.result : [];
        const players = playersRes.ok ? playersRes.result : [];

        const midCount = storageNow.filter(
          (p) => p.rating > 75 && p.rating < 83,
        ).length;
        const midPlayerCount = players.filter(
          (p) => p.rating > 75 && p.rating < 84,
        ).length;

        log("inventory:counts", {
          storageLen: storageNow.length,
          clubLen: players.length,
          midCountStorage: midCount,
          midCountClub: midPlayerCount,
        });

        let targetSet;

        if (midCount > 0) {
          targetSet = (sbcs?.sets || [])
            .filter((f) => !f.hidden && !f.isComplete())
            .find((f) => /TOTW/i.test(f.name));
          log("targetSet:maybe", {
            reason: "midCount > 0 => /TOTW/",
            found: !!targetSet,
            targetSetId: targetSet?.id,
            targetSetName: targetSet?.name,
          });
        }

        if (targetSet && storageNow.length >= 100) {
          services.Notification.queue(
            [`Running SBC: ${targetSet.name}`],
            UINotificationType.POSITIVE,
          );
          log("solveSBC:targetSet", { setId: targetSet.id });

          const solveRes = await safe("solveSBC(targetSet)", () =>
            solveSBC(targetSet.id, 0, true, 0, false, false, true),
          );

          if (!solveRes.ok) {
            log("fav:continue (solveSBC targetSet errored)");
          } else if (createSbcGrind) {
            await processPostSbcRewards("targetSet", targetSet.id);
          }

          log("fav:continue (after targetSet)");
          continue;
        }

        const favName = sbcs?.sets?.find((f) => f.id == fav)?.name;
        services.Notification.queue(
          [`Running SBC: ${favName}`],
          UINotificationType.POSITIVE,
        );

        log("solveSBC:fav", { fav, favName });

        if (!createSbcGrind) {
          log("fav:break (createSbcGrind turned false before solveSBC)");
          break;
        }

        const solveFavRes = await safe("solveSBC(fav)", () =>
          solveSBC(fav, 0, true, 0, false, false, true),
        );

        if (!createSbcGrind) {
          log("fav:break (createSbcGrind turned false after solveSBC)");
          break;
        }

        if (!solveFavRes.ok) {
          log("fav:continue (solveSBC fav errored)");
          continue;
        }

        if (createSbcGrind) {
          await processPostSbcRewards(`favourite:${fav}`, fav);
        }

        log("fav:end", { fav });
      }

      await safe("ratingCountUI() (end of cycle)", () => ratingCountUI());
      log("cycle:end");
    }

    log("exited (createSbcGrind is false)");
  } catch (err) {
    // IMPORTANT: don't recursively re-call futAutoGrind() here; it hides the real failure and can loop forever.
    console.warn(`[autoGrind:${runId}] fatal error`, err);
    showNotification(
      "Auto-grind crashed; check console logs",
      UINotificationType.NEGATIVE,
    );
    createSbcGrind = false;
  } finally {
    await releaseFutAutoGrindWakeLock();
  }
};
let apiUrl = "http://127.0.0.1:8000";
let sbcLogin = Array.isArray(window.sbcLogin) ? window.sbcLogin : [];
window.sbcLogin = sbcLogin;

let LOCKED_ITEMS_KEY = "excludePlayers";
