const FUTGG_PRICE_BATCH_SIZE_MAX = 50;
const FUTGG_PRICE_BATCH_SIZE_DEFAULT = 50;
const FUTGG_PRICE_REQUEST_DELAY_MS_DEFAULT = 1300;
const FUTGG_PRICE_ERROR_BACKOFF_MS_DEFAULT = 3000;
