const transferListOverride = () => {
  const patchActionHeaderForArray = () => {
    if (
      typeof UTSectionedItemListView === "undefined" ||
      !UTSectionedItemListView.prototype ||
      UTSectionedItemListView.prototype.__sbcMultiActionHeaderPatched
    ) {
      return;
    }

    const originalSetActionHeader =
      UTSectionedItemListView.prototype.setActionHeader;

    UTSectionedItemListView.prototype.__sbcMultiActionHeaderPatched = true;

    UTSectionedItemListView.prototype.setActionHeader = function (
      title,
      actionTextOrArray,
      callback,
    ) {
      const headerRoot = this._header?.getRootElement?.();
      if (headerRoot) {
        headerRoot
          .querySelectorAll(".sbc-extra-action-btn")
          .forEach((node) => node.remove());
      }

      if (!Array.isArray(actionTextOrArray)) {
        return originalSetActionHeader.call(
          this,
          title,
          actionTextOrArray,
          callback,
        );
      }

      const actions = actionTextOrArray.filter(
        (action) => action && typeof action.label === "string",
      );

      const primaryAction = actions[0];
      const primaryLabel = primaryAction?.label || "";
      const primaryCallback =
        typeof primaryAction?.onPress === "function"
          ? primaryAction.onPress
          : null;

      originalSetActionHeader.call(this, title, primaryLabel, primaryCallback);

      const primaryButtonRoot = this._header?._actionButton?.getRootElement?.();
      const buttonContainer = primaryButtonRoot?.parentElement || headerRoot;

      if (!buttonContainer) {
        return;
      }

      actions.slice(1).forEach((action, index) => {
        if (typeof action?.onPress !== "function") {
          return;
        }

        const extraButton = document.createElement("button");
        extraButton.type = "button";
        extraButton.classList.add(
          "btn-standard",
          "section-header-btn",
          "mini",
          "primary",
          "sbc-extra-action-btn",
        );
        extraButton.dataset.sbcActionIndex = String(index + 1);
        extraButton.textContent = action.label;
        extraButton.style.marginRight = "0.4rem";

        extraButton.addEventListener("click", (event) => {
          event.preventDefault();
          event.stopPropagation();

          try {
            action.onPress.call(this);
          } catch (err) {
            console.error("Transfer header extra action error", err);
          }
        });

        if (primaryButtonRoot) {
          buttonContainer.insertBefore(extraButton, primaryButtonRoot);
          return;
        }

        buttonContainer.appendChild(extraButton);
      });
    };
  };

  const processItemsByUnassignedRules = async (items, sectionLabel) => {
    const sourceItems = Array.isArray(items) ? items.filter(Boolean) : [];

    if (!sourceItems.length) {
      showNotification(
        `No ${sectionLabel} items to process`,
        UINotificationType.NEUTRAL,
      );
      return;
    }

    if (
      typeof getUnassignedRules !== "function" ||
      typeof groupUnassignedItemsByRules !== "function"
    ) {
      showNotification(
        "Unassigned rules engine is not available",
        UINotificationType.NEGATIVE,
      );
      return;
    }

    const allRules = getUnassignedRules() || [];
    const enabledRules = allRules.filter((rule) => rule?.enabled !== false);

    if (!enabledRules.length) {
      showNotification("No enabled rules found", UINotificationType.NEUTRAL);
      return;
    }

    const nonFreeItems = sourceItems.filter(
      (item) => !item?.isFreeCoins?.() && !item?.isFreePack?.(),
    );

    const grouping = groupUnassignedItemsByRules(nonFreeItems, enabledRules, {
      includeFreeItems: false,
      includeDoNothing: false,
    });

    const isTradable = (item) =>
      item?.tradable === true ||
      (typeof item?.isTradeable === "function" && item.isTradeable());

    const ensureLivePrices = async (entries) => {
      const toFetch = (entries || [])
        .map((entry) => entry?.item)
        .filter(Boolean)
        .filter(
          (item) =>
            !Number.isFinite(Number(getPrice(item))) || getPrice(item) <= 0,
        );

      if (!toFetch.length) return;

      if (typeof fetchLivePlayerPrice === "function") {
        for (const item of toFetch) {
          try {
            await fetchLivePlayerPrice(item);
          } catch (err) {
            console.warn("[transferList] livePrice failed", err);
          }
        }
        return;
      }

      if (typeof fetchPlayerPrices === "function") {
        await fetchPlayerPrices(toFetch);
      }
    };

    const actionBuckets = {
      sendToClub: (grouping.buckets.get("sendToClub") || []).filter((entry) =>
        entry?.item?.isMovable?.(),
      ),
      sendToTransferList: (
        grouping.buckets.get("sendToTransferList") || []
      ).filter((entry) => isTradable(entry?.item)),
      sendToStorage: [],
      quickSell: grouping.buckets.get("quickSell") || [],
      listOnTransferMarket: (
        grouping.buckets.get("listOnTransferMarket") || []
      ).filter((entry) => isTradable(entry?.item)),
    };

    const storagePlayers =
      typeof getStoragePlayers === "function" ? await getStoragePlayers() : [];
    const sendToStorageCandidates = (
      grouping.buckets.get("sendToStorage") || []
    ).filter((entry) => entry?.item?.isStorable?.());
    const storageCapacity = Math.max(0, 100 - (storagePlayers?.length ?? 0));
    actionBuckets.sendToStorage = sendToStorageCandidates.slice(
      0,
      storageCapacity,
    );

    const processedLog = [];
    const runTimestamp = new Date().toLocaleString();
    const addProcessedLog = (entries, action) => {
      entries.forEach((entry) => {
        if (!entry?.item) return;
        processedLog.push({
          item: entry.item,
          action,
          ruleNumber:
            typeof entry.ruleIndex === "number" && entry.ruleIndex >= 0
              ? entry.ruleIndex + 1
              : null,
          timestamp: runTimestamp,
          ruleColor: entry?.rule?.color || null,
        });
      });
    };

    const executeBucket = async (action, entries) => {
      const actionableEntries = entries || [];
      const bucketItems = actionableEntries
        .map((entry) => entry.item)
        .filter(Boolean);
      if (!bucketItems.length) return;

      if (action === "sendToClub") {
        services.Item.move(bucketItems, 7);
      } else if (action === "sendToTransferList") {
        services.Item.move(bucketItems, 5);
      } else if (action === "sendToStorage") {
        services.Item.move(bucketItems, 10);
      } else if (action === "quickSell") {
        services.Item.discard(bucketItems);
      } else if (action === "listOnTransferMarket") {
        await ensureLivePrices(actionableEntries);
        const eligible =
          typeof matchesUnassignedRule === "function"
            ? actionableEntries
                .filter((entry) =>
                  matchesUnassignedRule(entry.item, entry.rule),
                )
                .map((entry) => entry.item)
            : bucketItems;

        if (!eligible.length) return;

        await quickListItems(eligible, {
          suppressNotifications: true,
          minDelayMs: 2000,
          maxDelayMs: 3000,
        });
      }

      addProcessedLog(actionableEntries, action);
    };

    await executeBucket("sendToClub", actionBuckets.sendToClub);
    await executeBucket("sendToTransferList", actionBuckets.sendToTransferList);
    await executeBucket("sendToStorage", actionBuckets.sendToStorage);
    await executeBucket("quickSell", actionBuckets.quickSell);
    await executeBucket(
      "listOnTransferMarket",
      actionBuckets.listOnTransferMarket,
    );

    if (
      typeof appendUnassignedHistoryRows === "function" &&
      processedLog.length > 0
    ) {
      appendUnassignedHistoryRows(processedLog, runTimestamp);
    }

    if (!processedLog.length) {
      showNotification(
        `No ${sectionLabel} items matched enabled rules`,
        UINotificationType.NEUTRAL,
      );
      return;
    }

    showNotification(
      `Processed ${processedLog.length} ${sectionLabel} items by rules`,
      UINotificationType.POSITIVE,
    );
  };

  const patchController = (ControllerClass) => {
    if (
      !ControllerClass?.prototype ||
      ControllerClass.prototype.__sbcTransferListPatched
    ) {
      return;
    }

    const originalUpdateSectionHeaders =
      ControllerClass.prototype._updateSectionHeaders;

    if (!originalUpdateSectionHeaders) {
      return;
    }

    ControllerClass.prototype.__sbcTransferListPatched = true;

    ControllerClass.prototype._updateSectionHeaders =
      function _updateSectionHeaders() {
        originalUpdateSectionHeaders.call(this);

        try {
          const view = this.getView?.();
          if (!view || !this._viewmodel) {
            return;
          }

          const SECTION = UTTransferSectionListViewModel.SECTION;

          const isRefreshableItem = (item) => {
            const definitionId = Number(item?.definitionId);
            return Number.isFinite(definitionId) && definitionId > 0;
          };

          const dedupeByItemId = (items) => {
            const map = new Map();
            (items || []).forEach((item, index) => {
              const key =
                item?.id ||
                item?._auction?.tradeId ||
                item?._auction?.id ||
                `idx-${index}`;
              if (!key) return;
              if (!map.has(key)) {
                map.set(key, item);
              }
            });
            return Array.from(map.values());
          };

          const getRefreshCandidatesForSection = (sectionId) => {
            let sectionItems = [];

            if (
              sectionId === SECTION.UNSOLD &&
              typeof this._viewmodel.getUnsoldItems === "function"
            ) {
              sectionItems = this._viewmodel.getUnsoldItems() || [];
            } else {
              sectionItems = this._viewmodel.getSectionItems(sectionId) || [];
            }

            return dedupeByItemId(sectionItems).filter(isRefreshableItem);
          };

          const unsoldSection = view.getSection(SECTION.UNSOLD);
          const availableSection = view.getSection(SECTION.AVAILABLE);

          if (unsoldSection) {
            const relistEnabled =
              services.TransferMarket.isFeatureEnabledForUser() &&
              this._viewmodel.hasUnsoldItems();

            unsoldSection.setActionHeader(
              services.Localization.localize(
                "tradepile.dock.categories.expired.notsold",
              ),
              [
                {
                  label: services.Localization.localize(
                    "tradepile.button.relistall",
                  ),
                  onPress: relistEnabled ? this._relistAll.bind(this) : null,
                },
                {
                  label: "Quick List",
                  onPress: async () => {
                    const sectionItems =
                      this._viewmodel.getSectionItems(SECTION.UNSOLD) || [];
                    const tradableItems = sectionItems.filter(
                      (item) => item?.tradable === true,
                    );

                    if (!tradableItems.length) {
                      showNotification(
                        "No tradable unsold items",
                        UINotificationType.NEUTRAL,
                      );
                      return;
                    }

                    try {
                      await quickListItems(tradableItems, {
                        suppressNotifications: false,
                        minDelayMs: 2000,
                        maxDelayMs: 3000,
                      });
                      showNotification(
                        `Listed ${tradableItems.length} unsold items`,
                        UINotificationType.POSITIVE,
                      );
                    } catch (err) {
                      console.error("Quick list unsold error", err);
                      showNotification(
                        "Error listing unsold items",
                        UINotificationType.NEGATIVE,
                      );
                    }
                  },
                },
                {
                  label: "Process by Rules",
                  onPress: async () => {
                    const sectionItems =
                      this._viewmodel.getSectionItems(SECTION.UNSOLD) || [];
                    await processItemsByUnassignedRules(sectionItems, "unsold");
                  },
                },
                {
                  label: "Refresh Price",
                  onPress: async () => {
                    const playersToRefresh = getRefreshCandidatesForSection(
                      SECTION.UNSOLD,
                    );

                    if (!playersToRefresh.length) {
                      showNotification(
                        "No unsold items to refresh",
                        UINotificationType.NEUTRAL,
                      );
                      return;
                    }

                    try {
                      if (typeof refreshItemsLivePrices !== "function") {
                        showNotification(
                          "Refresh prices UI is not available",
                          UINotificationType.NEGATIVE,
                        );
                        return;
                      }
                      await refreshItemsLivePrices(playersToRefresh);
                    } catch (err) {
                      console.error("Refresh price unsold error", err);
                      showNotification(
                        "Error refreshing prices",
                        UINotificationType.NEGATIVE,
                      );
                    }
                  },
                },
              ],
            );

            unsoldSection.toggleHeaderButton(relistEnabled);
          }

          if (availableSection) {
            const transferPileFull = repositories.Item.isPileFull(
              ItemPile.TRANSFER,
            );

            availableSection.setActionHeader(
              services.Localization.localize(
                "tradepile.dock.categories.available",
              ),
              [
                {
                  label: services.Localization.localize(
                    "infopanel.label.addplayer",
                  ),
                  onPress: () => {
                    if (isPhone()) {
                      const navController = this.getNavigationController?.();
                      if (navController) {
                        const transferNavController =
                          new UTTransferListNavigationController().init();
                        transferNavController.setNavigationStyle(
                          UTNavigationBarView.Style.SECONDARY,
                        );
                        navController.pushViewController(
                          transferNavController,
                          true,
                        );
                      }
                      return;
                    }

                    this.onSearchClub?.notify?.();
                  },
                },
                {
                  label: "Quick List",
                  onPress: async () => {
                    const sectionItems =
                      this._viewmodel.getSectionItems(SECTION.AVAILABLE) || [];
                    const tradableItems = sectionItems.filter(
                      (item) => item?.tradable === true,
                    );

                    if (!tradableItems.length) {
                      showNotification(
                        "No tradable available items",
                        UINotificationType.NEUTRAL,
                      );
                      return;
                    }

                    try {
                      await quickListItems(tradableItems, {
                        suppressNotifications: false,
                        minDelayMs: 2000,
                        maxDelayMs: 3000,
                      });
                      showNotification(
                        `Listed ${tradableItems.length} available items`,
                        UINotificationType.POSITIVE,
                      );
                    } catch (err) {
                      console.error("Quick list available error", err);
                      showNotification(
                        "Error listing available items",
                        UINotificationType.NEGATIVE,
                      );
                    }
                  },
                },
                {
                  label: "Process by Rules",
                  onPress: async () => {
                    const sectionItems =
                      this._viewmodel.getSectionItems(SECTION.AVAILABLE) || [];
                    await processItemsByUnassignedRules(
                      sectionItems,
                      "available",
                    );
                  },
                },
                {
                  label: "Refresh Price",
                  onPress: async () => {
                    const playersToRefresh = getRefreshCandidatesForSection(
                      SECTION.AVAILABLE,
                    );

                    if (!playersToRefresh.length) {
                      showNotification(
                        "No available items to refresh",
                        UINotificationType.NEUTRAL,
                      );
                      return;
                    }

                    try {
                      if (typeof refreshItemsLivePrices !== "function") {
                        showNotification(
                          "Refresh prices UI is not available",
                          UINotificationType.NEGATIVE,
                        );
                        return;
                      }
                      await refreshItemsLivePrices(playersToRefresh);
                    } catch (err) {
                      console.error("Refresh price available error", err);
                      showNotification(
                        "Error refreshing prices",
                        UINotificationType.NEGATIVE,
                      );
                    }
                  },
                },
              ],
            );

            availableSection.toggleHeaderButtonEnabled(!transferPileFull);
          }
        } catch (err) {
          console.warn("Transfer list multi-action override error:", err);
        }
      };
  };

  patchActionHeaderForArray();

  if (typeof UTTransferListViewController !== "undefined") {
    patchController(UTTransferListViewController);
  }

  if (typeof UTTransferListSplitViewController !== "undefined") {
    patchController(UTTransferListSplitViewController);
  }
};

if (
  typeof UTTransferListViewController !== "undefined" ||
  typeof UTTransferListSplitViewController !== "undefined"
) {
  transferListOverride();
}
const playerSlotOverride = () => {
  const pitchProto = globalThis.UTSquadPitchView?.prototype;
  if (!pitchProto || pitchProto.__autoSbcSlotPricePatched) {
    return;
  }

  const playerSlot = pitchProto.setSlots;

  pitchProto.setSlots = async function (...args) {
    const result = playerSlot.call(this, ...args);
    // Cache the slot entities on the pitch view for recalc in updateSlot
    this.__autoSbcSlotEntities = args[0];
    const squadSlots = buildSquadSlotsFromEntities(args[0], this.getSlotViews());
    appendSlotPrice(squadSlots);
    return result;
  };

  const baseUpdateSlot = pitchProto.updateSlot;

  pitchProto.updateSlot = function (...args) {
    const result = baseUpdateSlot.apply(this, args);
    // args[0] is the updated UTSquadSlotEntity — update cached entry
    const slotData = args[0];
    if (this.__autoSbcSlotEntities && slotData) {
      const idx = this.__autoSbcSlotEntities.findIndex(
        (e) => e.index === slotData.index,
      );
      if (idx >= 0) {
        this.__autoSbcSlotEntities[idx] = slotData;
      }
    }
    const squadSlots = buildSquadSlotsFromEntities(
      this.__autoSbcSlotEntities,
      this.getSlotViews(),
    );
    appendSlotPrice(squadSlots);
    return result;
  };

  pitchProto.__autoSbcSlotPricePatched = true;
};

const buildSquadSlotsFromEntities = (slotEntities, slotViews) => {
  const result = [];
  if (!slotEntities || !slotViews) return result;
  for (const entity of slotEntities) {
    if (!entity?._item || entity._item.definitionId <= 0) continue;
    const sv = slotViews.find((s) => s.getIndex() === entity.index);
    if (sv) {
      result.push({ item: entity._item, rootElement: sv.getRootElement() });
    }
  }
  return result;
};

const appendSlotPrice = async (squadSlots) => {
  if (!squadSlots.length) {
    appendSquadTotal(0);
    return;
  }

  const players = [];
  for (const { item } of squadSlots) {
    players.push(item);
  }

  await fetchPlayerPrices(players);
  let total = 0;
  const duplicateIds = await fetchDuplicateIds();
  getPriceItems();
  for (const { rootElement, item } of squadSlots) {
    if (duplicateIds.includes(item.id)) {
      rootElement.style.opacity = "0.4";
    }

    appendPriceToSlot(rootElement, item);
    total += getPrice(item);
  }

  appendSquadTotal(total);
};

const appendSquadTotal = (total) => {
  window.__autoSbcSquadPriceTotal = Number.isFinite(total) ? total : 0;
  if (typeof refreshSbcSquadPriceBanners === "function") {
    refreshSbcSquadPriceBanners();
  }
};

const appendPriceToSlot = async (rootElement, item) => {
  let priceElement = await getPriceDiv(item);
  if (priceElement) {
    rootElement.prepend(priceElement);
  }
};

const getUserPlatform = () => {
  if (services.User.getUser().getSelectedPersona().isPC) {
    return "pc";
  }
  return "ps";
};
const createPackList = async () => {
  let packs = await getPacks();
  let i = services.Localization;
  const visiblePackCount = packs.packs.filter(
    (f) => f.isMyPack || f?.prices?._collection?.COINS?.amount < 101,
  ).length;

  let packContent = `<span>Packs<br>${visiblePackCount}</span>`;
  let packCounts = packs.packs
    .filter((f) => f.isMyPack || f?.prices?._collection?.COINS?.amount < 101)
    .reduce((acc, pack) => {
      let key = `${pack.packName} ${
        pack.tradeable ? "(Tradable)" : "(Untradable)"
      }`;

      acc[key] = acc[key] || {};
      acc[key].count = (acc[key]?.count || 0) + 1;
      acc[key].packName =
        i.localize(pack.packName) +
        (pack?.prices?._collection?.COINS?.amount
          ? ` (${pack.prices._collection.COINS.amount} coins)`
          : "");
      acc[key].class = pack.tradable ? "tradable" : "untradable";
      acc[key].description = i.localize(pack.packDesc);
      acc[key].pack = pack;

      return acc;
    }, {});

  if (Object.keys(packCounts).length > 1) {
    packCounts["Open All Packs"] = {
      count: 0,
      packName: "Open All Packs",
      class: "OpenAll",
      description: "Open all available packs",
      pack: Object.values(packCounts)[0]?.pack || null,
    };
  }
  let packHoverButtons = Object.keys(packCounts).map((packName) => {
    let pack = packCounts[packName];

    let navLabelSpan = document.createElement("span");
    navLabelSpan.title = pack.description;
    navLabelSpan.classList.add(pack.class);
    navLabelSpan.style.direction = "ltr";
    let packCountLabel = document.createElement("div");
    packCountLabel.classList.add("ut-tab-bar-item-notif");
    packCountLabel.style.left = "5px";
    packCountLabel.innerHTML = pack.count;
    navLabelSpan.innerHTML = pack.packName;
    if (pack.count > 1) {
      navLabelSpan.prepend(packCountLabel);
    }

    let btn = createNavButton(
      "openPackItem",
      navLabelSpan.outerHTML,
      async () => {},
      async () => {
        let packToOpen = pack.pack;
        if (pack.pack.isMyPack) {
          await openPack(packToOpen, pack.count, packName === "Open All Packs");
        } else {
          packToOpen
            .purchase(GameCurrency.COINS)
            .observe(new UTStoreViewController(), async () => {
              await openPack(packToOpen);
            });
        }
      },
      { width: "20vw", marginTop: "0px" },
    );

    return btn;
  });

  let packDiv = document.createElement("div");
  packHoverButtons.forEach((button) => {
    packDiv.appendChild(button);
  });
  let packNavBtn = createNavButton(
    "navPacks",
    packContent,
    async () => {
      if (Object.keys(packCounts).length > 0) {
        return createHoverNav(
          "myPacks",
          "My Packs",
          "click to open",
          [packDiv],
          { width: "20vw" },
        );
      }
      return null;
    },
    async () => {
      packToOpen = Object.values(packCounts)[0]?.pack || null;
      if (!packToOpen) {
        await openPack(packToOpen, 0, true);
      }
    },
    { background: "none" },
  );

  return packNavBtn;
};

const sbcToolbarImageUrlCache = new Map();
const sbcToolbarImageInFlight = new Map();

const getCachedSbcToolbarImageSrc = async (src) => {
  if (!src || typeof src !== "string") {
    return src;
  }

  if (sbcToolbarImageUrlCache.has(src)) {
    return sbcToolbarImageUrlCache.get(src);
  }

  if (sbcToolbarImageInFlight.has(src)) {
    return await sbcToolbarImageInFlight.get(src);
  }

  const request = fetch(src, { credentials: "include" })
    .then((response) => {
      if (!response?.ok) {
        throw new Error(`Image fetch failed (${response?.status || "unknown"})`);
      }
      return response.blob();
    })
    .then((blob) => {
      const objectUrl = URL.createObjectURL(blob);
      sbcToolbarImageUrlCache.set(src, objectUrl);
      return objectUrl;
    })
    .catch((error) => {
      console.warn("[SBC Toolbar] image cache fetch failed", { src, error });
      sbcToolbarImageUrlCache.set(src, src);
      return src;
    })
    .finally(() => {
      sbcToolbarImageInFlight.delete(src);
    });

  sbcToolbarImageInFlight.set(src, request);
  return await request;
};

const createCategoryPicker = async () => {
  let sets = await sbcSets();
  if (sets === undefined) {
    console.log("createCategoryPicker: sets are undefined");
    return null;
  }
  const incompleteSetIds = (sets.sets || [])
    .filter((s) => !s.isComplete())
    .map((s) => s.id);
  const filteredCategories = (sets.categories || []).filter(
    (cat) =>
      Array.isArray(cat.setIds) &&
      cat.setIds.some((id) => incompleteSetIds.includes(id)),
  );
  let categories = filteredCategories.length
    ? filteredCategories.map((c) => c.name)
    : (sets.categories || []).map((c) => c.name);

  if (!categories.includes("Daily")) {
    let dailySbcs = sets.sets
      .filter((set) => set.name.toLowerCase().includes("daily"))
      .filter((s) => !s.isComplete());

    if (dailySbcs.length > 0) {
      sets.categories.push({
        name: "Daily",
        setIds: dailySbcs.map((sbc) => sbc.id),
      });
      categories.push("Daily");
    }
  }

  if (!categories.includes("Login")) {
    // Use same settings-driven logic as init/fut-home for login SBC selection.
    const loginSetIds = getOrderedLoginSbcSetIds(sets);
    let loginSbcs = sets.sets.filter((set) =>
      loginSetIds.includes(String(set.id)),
    );

    if (loginSbcs.length > 0) {
      sets.categories.push({
        name: "Login",
        setIds: loginSbcs.map((sbc) => sbc.id),
      });
      categories.push("Login");
    }
  }

  let categoryButtons = [];
  categories.forEach((category) => {
    let navLabelSpan = document.createElement("span");
    navLabelSpan.innerHTML = category;
    navLabelSpan.style.display = "inline-block";
    navLabelSpan.style.verticalAlign = "middle";
    navLabelSpan.style.width = "50px";
    let navBtn = createNavButton(
      category,
      navLabelSpan.outerHTML,
      () => {},
      async () => {
        saveSettings("global", "global", "sbcType", category);
        services.Notification.queue([
          "Updating SBC toolbar to " + category,
          UINotificationType.POSITIVE,
        ]);
        createSBCTab();
      },
      { width: "20vw", marginTop: "0px" },
    );
    categoryButtons.push(navBtn);
  });

  let categoryNavBtn = createNavButton(
    "navCategory",
    `SBC 1-click <br>${getSettings(0, 0, "sbcType")}`,
    async () => {
      return createHoverNav(
        "categoryPicker",
        "SBC Categories",
        "click to select",
        categoryButtons,
        { width: "20vw" },
      );
    },
    () => {},
    { background: "none" },
  );
  return categoryNavBtn;
};

const areStringArraysEqual = (left, right) => {
  if (!Array.isArray(left) || !Array.isArray(right)) {
    return false;
  }
  if (left.length !== right.length) {
    return false;
  }
  for (let i = 0; i < left.length; i += 1) {
    if (String(left[i]) !== String(right[i])) {
      return false;
    }
  }
  return true;
};

const getResolvedLoginSbcSetIdsFromSettings = (setsData) => {
  const findLoginFn =
    window?.autoSbcConsoleApi?.findSBCLogin ||
    (typeof findSBCLogin !== "undefined" ? findSBCLogin : undefined);

  const allSets = Array.isArray(setsData?.sets) ? setsData.sets : [];

  if (typeof findLoginFn !== "function" || !allSets.length) {
    return [];
  }

  const solverSettings = getSolverSettings();
  const sbcSettingsLogin = findLoginFn(solverSettings, "sbcOnLogin") || [];

  const setById = new Map(allSets.map((set) => [String(set.id), set]));
  const setByName = new Map(
    allSets.map((set) => [String(set.name || "").toLowerCase(), set]),
  );

  const loginSetIds = sbcSettingsLogin
    .map((entry) => entry?.parents?.[1])
    .map((rawRef) => {
      if (rawRef === undefined || rawRef === null || rawRef === "") {
        return null;
      }

      const refText = String(rawRef).trim();
      if (!refText) {
        return null;
      }

      if (setById.has(refText)) {
        return refText;
      }

      const byName = setByName.get(refText.toLowerCase());
      if (byName?.id !== undefined && byName?.id !== null) {
        return String(byName.id);
      }

      return null;
    })
    .filter((setId) => !!setId);

  return [...new Set(loginSetIds)];
};

const getOrderedLoginSbcSetIds = (setsData) => {
  const allSets = Array.isArray(setsData?.sets) ? setsData.sets : [];
  const setNameById = new Map(
    allSets.map((set) => [String(set?.id), String(set?.name || "").trim()]),
  );
  const setByName = new Map(
    allSets
      .map((set) => [String(set?.name || "").trim().toLowerCase(), set])
      .filter(([name]) => !!name),
  );
  const baseIds = getResolvedLoginSbcSetIdsFromSettings(setsData).filter((id) =>
    setNameById.has(String(id)),
  );
  const baseNames = baseIds
    .map((id) => setNameById.get(String(id)))
    .filter(Boolean);
  const savedOrder = getSettings(0, 0, "loginSbcOrder");
  const savedNames = Array.isArray(savedOrder)
    ? savedOrder
        .map((entry) => {
          const rawValue = String(entry || "").trim();
          if (!rawValue) {
            return null;
          }

          if (setNameById.has(rawValue)) {
            return setNameById.get(rawValue);
          }

          return setByName.get(rawValue.toLowerCase())?.name || null;
        })
        .filter(Boolean)
    : [];

  // If runtime settings are briefly unavailable, keep existing persisted order
  // instead of auto-healing to an empty array.
  if (!baseNames.length) {
    return savedNames
      .map((name) => setByName.get(String(name).toLowerCase())?.id)
      .filter((id) => id !== undefined && id !== null)
      .map((id) => String(id));
  }

  const seen = new Set();
  const ordered = [];

  savedNames.forEach((name) => {
    const nameKey = String(name).toLowerCase();
    if (baseNames.some((baseName) => String(baseName).toLowerCase() === nameKey) && !seen.has(nameKey)) {
      seen.add(nameKey);
      ordered.push(name);
    }
  });

  baseNames.forEach((name) => {
    const nameKey = String(name).toLowerCase();
    if (!seen.has(nameKey)) {
      seen.add(nameKey);
      ordered.push(name);
    }
  });

  if (!areStringArraysEqual(savedNames, ordered)) {
    saveSettings("global", "global", "loginSbcOrder", ordered);
  }

  return ordered
    .map((name) => setByName.get(String(name).toLowerCase())?.id)
    .filter((id) => id !== undefined && id !== null)
    .map((id) => String(id));
};

const persistLoginToolbarOrder = (container) => {
  if (!container) {
    return;
  }

  const orderedNames = Array.from(container.children)
    .map((child) => child?.dataset?.loginSetName)
    .filter((name) => !!name)
    .map((name) => String(name).trim());

  saveSettings("global", "global", "loginSbcOrder", orderedNames);
};

const enableLoginToolbarDragAndDrop = (container) => {
  if (!container || container.dataset.loginDnDEnabled === "true") {
    return;
  }

  const draggableItems = Array.from(container.children).filter(
    (child) => !!child?.dataset?.loginSetId,
  );

  if (draggableItems.length <= 1) {
    return;
  }

  container.dataset.loginDnDEnabled = "true";
  let draggedItem = null;

  draggableItems.forEach((item) => {
    item.draggable = true;
    item.style.cursor = "grab";

    item.addEventListener("dragstart", (event) => {
      draggedItem = item;
      item.style.opacity = "0.6";
      if (event?.dataTransfer) {
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", item.dataset.loginSetId || "");
      }
    });

    item.addEventListener("dragend", () => {
      item.style.opacity = "";
    });
  });

  container.addEventListener("dragover", (event) => {
    if (!draggedItem) {
      return;
    }

    const targetItem = event.target?.closest(".ut-tab-bar-item");
    if (!targetItem || targetItem === draggedItem || targetItem.parentNode !== container) {
      return;
    }

    event.preventDefault();
    const rect = targetItem.getBoundingClientRect();
    const shouldInsertBefore = (event.clientY - rect.top) < rect.height / 2;

    if (shouldInsertBefore) {
      container.insertBefore(draggedItem, targetItem);
    } else {
      container.insertBefore(draggedItem, targetItem.nextSibling);
    }
  });

  container.addEventListener("drop", (event) => {
    if (!draggedItem) {
      return;
    }

    event.preventDefault();
    persistLoginToolbarOrder(container);
    draggedItem = null;
  });
};

const SBC_CHALLENGE_CACHE_TTL_MS = 60 * 1000;
const sbcChallengesCache = new Map();
const sbcChallengesInFlight = new Map();

const getCachedChallengesForSet = async (set) => {
  const setId = Number(set?.id);
  if (!Number.isFinite(setId) || setId <= 0) {
    return await getChallenges(set);
  }

  const now = Date.now();
  const cached = sbcChallengesCache.get(setId);
  if (
    cached &&
    now - Number(cached.timestamp || 0) < SBC_CHALLENGE_CACHE_TTL_MS &&
    cached.data
  ) {
    return cached.data;
  }

  const inFlight = sbcChallengesInFlight.get(setId);
  if (inFlight) {
    return await inFlight;
  }

  const requestPromise = Promise.resolve()
    .then(() => getChallenges(set))
    .then((result) => {
      if (result && Array.isArray(result.challenges)) {
        sbcChallengesCache.set(setId, {
          timestamp: Date.now(),
          data: result,
        });
      }
      return result;
    })
    .finally(() => {
      sbcChallengesInFlight.delete(setId);
    });

  sbcChallengesInFlight.set(setId, requestPromise);
  return await requestPromise;
};

const createSBCButtons = async () => {
  let sets = await sbcSets();
  if (sets === undefined) {
    console.log("createSBCButtons: sets are undefined");
    return null;
  }

  let sbcSetIds;
  const currentSbcType = getSettings(0, 0, "sbcType");
  const isLoginCategory = currentSbcType === "Login";

  if (currentSbcType === "Daily") {
    sbcSetIds = sets.sets
      .filter((set) => set.name.toLowerCase().includes("daily"))
      .map((set) => set.id);
  } else if (isLoginCategory) {
    sbcSetIds = getOrderedLoginSbcSetIds(sets);
  } else {
    sbcSetIds =
      sets.categories.filter((f) => f.name == currentSbcType)[0]?.setIds || [];
  }

  sbcSetIds = (sbcSetIds || []).map((id) => String(id));

  // For Login category include all SBCs (complete + incomplete); others exclude complete
  let allSbcSets = sets.sets.filter(
    (f) =>
      sbcSetIds.includes(String(f.id)) &&
      (isLoginCategory || !f.isComplete()),
  );

  if (isLoginCategory) {
    const orderedIndexBySetId = new Map(
      sbcSetIds.map((id, index) => [String(id), index]),
    );
    allSbcSets = allSbcSets.sort((a, b) => {
      const aIndex = orderedIndexBySetId.get(String(a.id));
      const bIndex = orderedIndexBySetId.get(String(b.id));
      return Number(aIndex) - Number(bIndex);
    });
  } else {
    allSbcSets = allSbcSets.reverse();
  }

  if (currentSbcType === "Favourites") {
    allSbcSets = allSbcSets.sort((a, b) => b.timesCompleted - a.timesCompleted);
  }

  let sbcTiles = [];
  allSbcSets.forEach((set) => {
    const isCompleted = set.isComplete();
    var t = new UTSBCSetTileView();
    (t.init(), (t.title = set.name), t.setData(set), t.render());
    let pb = t._progressBar;
    let sbcDiv = document.createElement("div");
    var img = document.createElement("img");
    const originalSrc = t?._setImage?.src;
    if (originalSrc) {
      img.setAttribute("src", originalSrc);
      Promise.resolve(getCachedSbcToolbarImageSrc(originalSrc)).then(
        (cachedSrc) => {
          if (cachedSrc && img) {
            img.setAttribute("src", cachedSrc);
          }
        },
      );
    }
    img.width = img.height = "64";
    if (isCompleted) {
      img.style.filter = "grayscale(100%)";
      img.style.opacity = "0.5";
    }
    sbcDiv.appendChild(img);
    if (!t.data.isSingleChallenge) {
      sbcDiv.appendChild(pb.getRootElement());
    }
    var label = document.createElement("span");
    label.innerHTML = set.name;
    if (isCompleted) {
      label.style.color = "#888";
    }
    sbcDiv.appendChild(label);

    const sbcTileButton = createNavButton(
        `navSBC${set.id}`,
        sbcDiv.outerHTML,
        async () => {
          let hoverSet = await createSBCHover(set, isLoginCategory);
          let hoverNav = createHoverNav(set.id, "", "click to start", [
            hoverSet,
          ]);
          return hoverNav;
        },
        () => {
          if (isCompleted) return;
          createSbc = true;
          createSBCTab();
          services.Notification.queue([
            set.name + " SBC Started",
            UINotificationType.POSITIVE,
          ]);
          solveSBC(
            set.id,
            0,
            true,
            null,
            true,
            true,
            isLoginCategory ? true : null,
          );
        },
        {
          background: "none",
          ...(isCompleted ? { opacity: "0.5", cursor: "default" } : {}),
        },
      );

    if (isLoginCategory) {
      sbcTileButton.dataset.loginSetId = String(set.id);
      sbcTileButton.dataset.loginSetName = String(set.name || "").trim();
    }

    sbcTiles.push(sbcTileButton);
  });
  return sbcTiles;
};

const createSBCHover = async (set, forceRunInBackground = false) => {
  const CHALLENGE_HOVER_OPEN_DELAY_MS = 260;
  const CHALLENGE_HOVER_CLOSE_DELAY_MS = 180;
  let layoutHubDiv = document.createElement("div");
  layoutHubDiv.style.padding = "0";
  layoutHubDiv.style.width = "50vw";
  layoutHubDiv.style.maxWidth = "500px";
  layoutHubDiv.style.direction = "ltr";
  layoutHubDiv.style.overflowY = "none";
  var s = new UTSBCSetTileView();
  (s.init(), (s.title = set.name), s.setData(set), s.render());
  const hoverImageSrc = s?._setImage?.src;
  if (hoverImageSrc && s?._setImage) {
    Promise.resolve(getCachedSbcToolbarImageSrc(hoverImageSrc)).then(
      (cachedSrc) => {
        if (cachedSrc && s?._setImage) {
          s._setImage.src = cachedSrc;
        }
      },
    );
  }
  layoutHubDiv.appendChild(s.getRootElement());
  layoutHubDiv.querySelectorAll("div").forEach((div) => {
    div.classList.remove("col-1-2-md");
  });
  let progressBlock = layoutHubDiv.querySelector(
    ".ut-sbc-set-tile-view--progress-block",
  );
  if (progressBlock) {
    progressBlock.insertBefore(
      s._progressBar.getRootElement(),
      progressBlock.firstChild,
    );
  }

  let c;
  try {
    c = await getCachedChallengesForSet(set);
  } catch (err) {
    console.warn("[SBC Hover] Failed to fetch challenges", err);
    c = null;
  }

  const safeChallenges = Array.isArray(c?.challenges) ? c.challenges : [];
  if (!safeChallenges.length) {
    const emptyState = document.createElement("div");
    emptyState.style.padding = "10px";
    emptyState.style.color = "#f59e0b";
    emptyState.textContent = "Challenges unavailable right now (rate limited).";
    layoutHubDiv.appendChild(emptyState);
    return layoutHubDiv;
  }

  let row = safeChallenges
    .sort(function (e, t) {
      return e.priority - t.priority;
    })
    .map(function (e) {
      loadChallenge(e);
      i = new UTSBCChallengeTableRowView();
      (i.init(), i.setTitle(e.name), i.render(e));
      let rowRoot = i.getRootElement();
      rowRoot.querySelectorAll("div").forEach((div) => {
        div.classList.remove("has-tap-callback");
        if (div.classList.contains("ut-progress-bar")) {
          div.remove();
        }

        rowRoot.querySelectorAll("img").forEach((img) => {
          img.style.width = "15%";
        });
      });
      let openTimeout = null;
      let hideTimeout = null;
      let challengeDiv = null;

      const removeChallengeNav = () => {
        if (challengeDiv && challengeDiv.parentNode) {
          challengeDiv.remove();
        }
        challengeDiv = null;
      };

      const showChallengeNav = async () => {
        if (challengeDiv && challengeDiv.parentNode) {
          return;
        }

        let existingChallengeNav = document.getElementById("challengeNav");
        if (existingChallengeNav) {
          existingChallengeNav.remove();
        }

        let s = new UTSBCChallengeRequirementsView();
        s.renderChallengeRequirements(e, true);
        challengeDiv = document.createElement("div");
        challengeDiv.id = "challengeNav";
        challengeDiv.style.position = "absolute";

        challengeDiv.style.top = "355px";
        challengeDiv.style.right = "calc(100% + 5px)";
        challengeDiv.style.padding = "5px";
        challengeDiv.style.width = "25vw";
        challengeDiv.style.borderRadius = "20px";
        challengeDiv.style.background = "#1e1f1f";
        challengeDiv.appendChild(s.getRootElement());

        let settingsContainer = document.createElement("div");
        settingsContainer.style.marginTop = "10px";
        settingsContainer.style.padding = "5px";
        settingsContainer.style.maxHeight = "300px";
        settingsContainer.style.overflowY = "auto";

        let settingsTitle = document.createElement("div");
        settingsTitle.style.fontWeight = "bold";
        settingsTitle.style.marginBottom = "5px";
        settingsTitle.style.cursor = "pointer";
        settingsTitle.style.userSelect = "none";
        settingsTitle.style.display = "flex";
        settingsTitle.style.justifyContent = "space-between";
        settingsTitle.style.alignItems = "center";

        let sbcParamsTile = document.createElement("div");
        sbcParamsTile.style.display = "none";
        sbcParamsTile.style.fontSize = "0.85em";

        let toggleArrow = document.createElement("span");
        toggleArrow.textContent = "▶";
        toggleArrow.style.transition = "transform 0.2s";
        settingsTitle.appendChild(
          document.createTextNode("Challenge Settings "),
        );
        settingsTitle.appendChild(toggleArrow);

        settingsTitle.addEventListener("click", () => {
          if (sbcParamsTile.style.display === "none") {
            sbcParamsTile.style.display = "block";
            toggleArrow.style.transform = "rotate(90deg)";
          } else {
            sbcParamsTile.style.display = "none";
            toggleArrow.style.transform = "rotate(0deg)";
          }
        });

        const sbcId = e.setId;
        const challengeId = e.id;
        const populateSbcParamsTileFn =
          window?.autoSbcConsoleApi?.populateSbcParamsTile ||
          (typeof populateSbcParamsTile !== "undefined"
            ? populateSbcParamsTile
            : undefined);

        if (typeof populateSbcParamsTileFn === "function") {
          await populateSbcParamsTileFn(sbcParamsTile, sbcId, challengeId);
        } else {
          console.warn("[SBC Hover] populateSbcParamsTile is unavailable");
        }

        settingsContainer.appendChild(settingsTitle);
        settingsContainer.appendChild(sbcParamsTile);
        challengeDiv.appendChild(settingsContainer);

        if (e.awards && e.awards.length > 0) {
          let rewardsContainer = document.createElement("div");
          rewardsContainer.style.marginTop = "10px";
          rewardsContainer.style.padding = "5px";

          let rewardsTitle = document.createElement("span");
          rewardsTitle.textContent = services.Localization.localize(
            "sbc.rewards.challenge",
          );
          rewardsTitle.style.display = "block";
          rewardsTitle.style.marginBottom = "5px";
          rewardsTitle.style.fontWeight = "bold";
          rewardsContainer.appendChild(rewardsTitle);

          let rewardList = new UTSBCGroupRewardListView();
          rewardList.init();
          rewardList.setRewards(e.awards);
          rewardsContainer.appendChild(rewardList.getRootElement());
          challengeDiv.appendChild(rewardsContainer);
        }

        let goToChallengeBtn = document.createElement("button");
        goToChallengeBtn.textContent = "Go to Challenge";
        goToChallengeBtn.style.width = "100%";
        goToChallengeBtn.style.marginTop = "10px";
        goToChallengeBtn.style.padding = "8px";
        goToChallengeBtn.style.backgroundColor = "#1e90ff";
        goToChallengeBtn.style.color = "white";
        goToChallengeBtn.style.border = "none";
        goToChallengeBtn.style.borderRadius = "5px";
        goToChallengeBtn.style.cursor = "pointer";
        goToChallengeBtn.addEventListener("click", async () => {
          let hoverNav = document.getElementById("hoverNav");
          if (hoverNav) {
            hoverNav.remove();
          }
          let challengeNav = document.getElementById("challengeNav");
          if (challengeNav) {
            challengeNav.remove();
          }

          try {
            const allSbcData = await sbcSets();
            const sbcSet = allSbcData.sets.filter(
              (set) => set.id == e.setId,
            )[0];

            if (!sbcSet) {
              console.warn("[SBC Hover] SBC set not found");
              showNotification(
                "SBC set not found",
                UINotificationType.NEGATIVE,
              );
              return;
            }

            await loadChallenge(e);

            const reloadSbcScreenFn =
              window?.autoSbcConsoleApi?.reloadSbcScreen ||
              (typeof reloadSbcScreen !== "undefined"
                ? reloadSbcScreen
                : undefined);

            if (typeof reloadSbcScreenFn === "function") {
              await reloadSbcScreenFn(sbcSet, e.id);
            } else {
              console.warn("[SBC Hover] reloadSbcScreen is unavailable");
              showNotification(
                "Navigation unavailable",
                UINotificationType.NEGATIVE,
              );
            }
          } catch (err) {
            console.warn("[SBC Hover] Failed to open challenge", err);
            showNotification(
              "Failed to open challenge",
              UINotificationType.NEGATIVE,
            );
          }
        });
        challengeDiv.appendChild(goToChallengeBtn);

        layoutHubDiv.appendChild(challengeDiv);

        challengeDiv.addEventListener("mouseenter", () => {
          if (hideTimeout) clearTimeout(hideTimeout);
        });

        challengeDiv.addEventListener("mouseleave", () => {
          removeChallengeNav();
        });
      };

      rowRoot.addEventListener("mouseenter", () => {
        if (hideTimeout) {
          clearTimeout(hideTimeout);
          hideTimeout = null;
        }
        if (openTimeout) {
          clearTimeout(openTimeout);
        }
        openTimeout = setTimeout(() => {
          openTimeout = null;
          showChallengeNav();
        }, CHALLENGE_HOVER_OPEN_DELAY_MS);
      });

      rowRoot.addEventListener("mouseleave", () => {
        if (openTimeout) {
          clearTimeout(openTimeout);
          openTimeout = null;
        }
        hideTimeout = setTimeout(() => {
          removeChallengeNav();
        }, CHALLENGE_HOVER_CLOSE_DELAY_MS);
      });
      rowRoot.addEventListener("click", () => {
        let hoverNav = document.getElementById("hoverNav");

        if (hoverNav) {
          hoverNav.remove();
        }
        createSbc = true;
        createSBCTab();
        services.Notification.queue([
          set.name + " SBC Started",
          UINotificationType.POSITIVE,
        ]);

        solveSBC(
          e.setId,
          e.id,
          true,
          null,
          false,
          false,
          forceRunInBackground ? true : null,
        );
      });
      return rowRoot;
    });

  let rowDiv = document.createElement("div");
  rowDiv.id = "challengeRow";
  rowDiv.style.padding = "5px";
  rowDiv.style.borderRadius = "20px";
  rowDiv.style.background = "#1e1f1f";
  rowDiv.style.overflowY = "auto";
  row.forEach((r) => {
    rowDiv.appendChild(r);
  });
  layoutHubDiv.appendChild(rowDiv);

  return layoutHubDiv;
};

let createSBCTab = async () => {
  const existingScrollContainer = document.querySelector(
    "#sbcToolbar #sbcToolbarListScroll",
  );
  if (existingScrollContainer) {
    window.__sbcToolbarListScrollTop = Number(existingScrollContainer.scrollTop) || 0;
  }

  if (!getSettings(0, 0, "showSbcTab")) {
    document.querySelectorAll(".sbc-auto").forEach((el) => el.remove());
    return;
  }

  if (
    getSettings(0, 0, "autoOpenSub100CoinPacks") &&
    !window.__autoOpenSub100CoinPacksRunning
  ) {
    window.__autoOpenSub100CoinPacksRunning = true;
    try {
      const packsResponse = await getPacks();
      const cheapPacks = (packsResponse?.packs || []).filter((pack) => {
        const coinAmount = Number(pack?.prices?._collection?.COINS?.amount);
        return Number.isFinite(coinAmount) && coinAmount <= 100;
      });

      for (const cheapPack of cheapPacks) {
        await new Promise((resolve) => {
          cheapPack
            .purchase(GameCurrency.COINS)
            .observe(new UTStoreViewController(), async (_obs, event) => {
              try {
                if (event?.success) {
                  await openPack(cheapPack);
                }
              } catch (err) {
                console.warn("autoOpenSub100CoinPacks: openPack failed", err);
              }
              resolve();
            });
        });
      }
    } catch (err) {
      console.warn("autoOpenSub100CoinPacks failed", err);
    } finally {
      window.__autoOpenSub100CoinPacksRunning = false;
    }
  }

  if (!document.getElementById("auto-grind-spinner-style")) {
    const styleTag = document.createElement("style");
    styleTag.id = "auto-grind-spinner-style";
    styleTag.textContent = `
        .button-spinner {
          display: inline-block;
          width: 1em;
          height: 1em;
          border: 2px solid #fff;
          border-top-color: transparent;
          border-radius: 50%;
          margin-left: 5px;
          vertical-align: middle;
          animation: spin 1s linear infinite;
        }
        @keyframes spin {
          to { transform: rotate(360deg); }
        }
      `;
    document.head.appendChild(styleTag);
  }

  services.SBC.repository.reset();
  const nav = document.createElement("nav");
  nav.id = "sbcToolbar";
  nav.classList.add("ut-tab-bar", "sbc-auto");
  const sbcData = await sbcSets();
  const favCategory = sbcData.categories.find((c) => c.isFavourite);
  const favSets = sbcData.sets.filter((s) =>
    favCategory?.setIds.includes(s.id),
  );
  const totalFavCompleted = favSets.reduce(
    (sum, s) => sum + (s.timesCompleted || 0),
    0,
  );
  const PACK_PURCHASE_COUNTS_KEY = "packPurchaseCountsById";
  const AUTO_BUY_PACK_ID_KEY = "autosbc_autoBuyPackId";
  const DEFAULT_AUTO_BUY_PACK_ID = 101; // Bronze Pack
  const autoBuyCurrency =
    getSettings(0, 0, "autoBuyCurrency") === "POINTS" ? "POINTS" : "COINS";
  const autoBuyGameCurrency =
    autoBuyCurrency === "POINTS" ? GameCurrency.POINTS : GameCurrency.COINS;

  const readPackPurchaseCount = (packId) => {
    try {
      const raw = localStorage.getItem(PACK_PURCHASE_COUNTS_KEY);
      const parsed = raw ? JSON.parse(raw) : {};
      const count =
        parsed && typeof parsed === "object"
          ? Number(parsed[String(packId)])
          : 0;
      return Number.isFinite(count) ? count : 0;
    } catch {
      return 0;
    }
  };

  const readAutoBuyPackId = () => {
    try {
      const raw = Number(localStorage.getItem(AUTO_BUY_PACK_ID_KEY));
      return Number.isFinite(raw) && raw > 0 ? raw : null;
    } catch {
      return null;
    }
  };

  const saveAutoBuyPackId = (packId) => {
    try {
      localStorage.setItem(AUTO_BUY_PACK_ID_KEY, String(packId));
    } catch {}
  };

  // Coin-purchasable store packs a user can pick from for the Auto Buy loop.
  // Only displayGroup bronze/silver/gold/special actually appear on the
  // storefront's Packs/Promo/Classic/Previewed tabs; "eventtoken" entries
  // (Nx NN+ Gold Players Pack, Kits/Player Picks) are reward-catalog items
  // not shown or purchasable in the store, and "vanityBundles" are cosmetic
  // Icon bundles — both confirmed absent from the live store UI. "Preview"
  // variants are duplicate bronze/silver/gold entries for the odds-preview
  // screen, not separately purchasable packs. All confirmed against the live
  // services.Store.getPacks(PurchasePackType.ALL, ...) response and the
  // actual store tab contents.
  const AUTO_BUY_DISPLAY_GROUPS = new Set(["bronze", "silver", "gold", "special"]);
  const getAutoBuyPackCatalog = async () => {
    let allPacks;
    try {
      allPacks = await getPacks(true);
    } catch {
      allPacks = null;
    }

    const seen = new Set();
    const catalog = [];
    for (const pack of allPacks?.packs || []) {
      const price = Number(
        pack?.prices?._collection?.[autoBuyCurrency]?.amount,
      );
      if (pack.isMyPack || !(price > 0)) continue;
      if (pack.packType !== "CARDPACK") continue;
      if (!AUTO_BUY_DISPLAY_GROUPS.has(pack.displayGroup)) continue;

      const name = services.Localization.localize(pack.packName);
      if (!name || /preview/i.test(name)) continue;

      const key = String(pack.id);
      if (seen.has(key)) continue;
      seen.add(key);

      catalog.push({
        id: pack.id,
        name,
        price,
      });
    }

    catalog.sort((a, b) => a.price - b.price);
    return catalog;
  };

  const autoBuyPackCatalog = await getAutoBuyPackCatalog();

  const resolveDefaultAutoBuyPackId = () => {
    const saved = readAutoBuyPackId();
    if (saved && autoBuyPackCatalog.some((p) => p.id === saved)) {
      return saved;
    }
    const bronze = autoBuyPackCatalog.find((p) =>
      /bronze/i.test(p.name || ""),
    );
    if (bronze) return bronze.id;
    return autoBuyPackCatalog[0]?.id ?? DEFAULT_AUTO_BUY_PACK_ID;
  };

  window.__autoBuyPackId = resolveDefaultAutoBuyPackId();
  window.__autoBuyRunning = false;
  window.__autoBuyCountTimer = null;

  const autoBuyPackName = (packId) =>
    autoBuyPackCatalog.find((p) => p.id === packId)?.name || "Bronze Packs";
  const autoBuyCurrencyClass =
    autoBuyCurrency === "POINTS" ? "currency-points" : "currency-coins";
  const autoBuyCurrencyLabel = autoBuyCurrency === "POINTS" ? "Points" : "Coins";

  const updateAutoBuyLabel = () => {
    const nameEl = document.getElementById("btnAutoBuy-packName");
    const countEl = document.getElementById("btnAutoBuy-count");
    if (nameEl) nameEl.textContent = autoBuyPackName(window.__autoBuyPackId);
    if (countEl)
      countEl.textContent = String(
        readPackPurchaseCount(window.__autoBuyPackId),
      );
  };

  const autoBuyPackButtons = autoBuyPackCatalog.map((entry) => {
    const label = `${entry.name} (${entry.price.toLocaleString()} ${autoBuyCurrencyLabel.toLowerCase()})`;
    return createNavButton(
      `autoBuyPackOption-${entry.id}`,
      `<span>${label}</span>`,
      null,
      () => {
        window.__autoBuyPackId = entry.id;
        saveAutoBuyPackId(entry.id);
        updateAutoBuyLabel();
      },
      { width: "20vw", marginTop: "0px", background: "none", color: "#fff" },
    );
  });

  const autoBuyBtn = createNavButton(
    "btnAutoBuy",
    `
        <div style="text-align:center;line-height:1.2">
          <span>Auto Buy</span>
          <span id="btnAutoBuy-currency" class="autosbc-auto-buy-currency-icon ${autoBuyCurrencyClass}" title="${autoBuyCurrencyLabel}" aria-label="${autoBuyCurrencyLabel}"></span>
          <span id="btnAutoBuy-packName" style="font-size:0.75em;display:block;opacity:0.85">
            ${autoBuyPackName(window.__autoBuyPackId)}
          </span>
          <span id="btnAutoBuy-count" style="font-size:0.8em;color:#07f468">
            ${readPackPurchaseCount(window.__autoBuyPackId)}
          </span>
          <span id="btnAutoBuy-spinner" class="button-spinner" style="display:none"></span>
        </div>
      `,
    autoBuyPackButtons.length
      ? async () =>
          createHoverNav(
            "autoBuyPacks",
            "Choose Pack to Auto Buy",
            "click to select",
            autoBuyPackButtons,
            { width: "20vw" },
          )
      : null,
    async () => {
      const spinner = document.getElementById("btnAutoBuy-spinner");

      if (window.__autoBuyRunning) {
        window.__autoBuyRunning = false;
        if (spinner) spinner.style.display = "none";
        if (window.__autoBuyCountTimer) {
          clearInterval(window.__autoBuyCountTimer);
          window.__autoBuyCountTimer = null;
        }
        updateAutoBuyLabel();
        return;
      }

      window.__autoBuyRunning = true;
      if (spinner) spinner.style.display = "inline-block";
      updateAutoBuyLabel();
      window.__autoBuyCountTimer = setInterval(updateAutoBuyLabel, 1000);

      const randDelay = () => 1200 + Math.floor(Math.random() * 1000);

      try {
        while (window.__autoBuyRunning) {
          const packId = window.__autoBuyPackId;

          try {
            await processUnassigned();
          } catch {}

          try {
            await clearSoldItems();
            relistItems();
          } catch {}

          let transferItems = [];
          try {
            transferItems = await getTransferItems();
          } catch {}

          if (Array.isArray(transferItems) && transferItems.length >= 100) {
            showNotification(
              `Stopping Auto Buy: transfer list is full (${transferItems.length}/100)`,
              UINotificationType.NEUTRAL,
            );
            break;
          }

          const balance = await getCurrencyBalance(autoBuyGameCurrency).catch(
            () => null,
          );
          if (typeof balance === "number" && balance <= 0) {
            showNotification(
              `Stopping Auto Buy: low ${autoBuyCurrency.toLowerCase()} balance`,
              UINotificationType.NEUTRAL,
            );
            break;
          }
          await processUnassigned();
          await purchasePackById(packId, autoBuyGameCurrency);
          updateAutoBuyLabel();

          try {
            await goToUnassignedView();
          } catch {}

          await sleep(randDelay());
        }
      } catch (err) {
        console.warn("Auto Buy loop error", err);
        showNotification(
          "Auto Buy encountered an error; stopping.",
          UINotificationType.NEGATIVE,
        );
      } finally {
        window.__autoBuyRunning = false;
        if (spinner) spinner.style.display = "none";
        if (window.__autoBuyCountTimer) {
          clearInterval(window.__autoBuyCountTimer);
          window.__autoBuyCountTimer = null;
        }
        updateAutoBuyLabel();
      }
    },
    { background: "none", color: "#fff" },
  );

  if (getSettings(0, 0, "showAutoBuyButton") !== false) {
    nav.appendChild(autoBuyBtn);
  }

  const autoGrindBtn = createNavButton(
    "btnAutoGrind",
    /* html */ `
        <div style="text-align:center;line-height:1.2">
          <span>Auto Grind</span>
          <span style="font-size:0.8em;color:#07f468">
            ✪ ${totalFavCompleted}
          </span>
          <span id="btnAutoGrind-spinner"
                class="button-spinner"
                style="display:none"></span>
        </div>
      `,
    null,
    async () => {
      const spinner = document.getElementById("btnAutoGrind-spinner");
      if (createSbcGrind) {
        createSbcGrind = false;
        spinner.style.display = "none";
        return;
      }
      createSbcGrind = true;
      spinner.style.display = "inline-block";
      try {
        await futAutoGrind();
      } finally {
        spinner.style.display = "none";
        autoGrindBtn.disabled = false;
        // Remove any persisted stop overlay button now that grind has ended
        document
          .querySelectorAll("#sbc-stop-overlay")
          .forEach((el) => el.remove());
      }
    },
    { background: "none", color: "#fff" },
  );

  nav.appendChild(autoGrindBtn);

  let packList = await createPackList();
  nav.appendChild(packList);

  let categoryPicker = await createCategoryPicker();
  nav.appendChild(categoryPicker);

  let sbcDiv = document.createElement("div");
  sbcDiv.id = "sbcToolbarListScroll";
  sbcDiv.style.overflowY = "auto";
  sbcDiv.style.height = "auto";
  let sbcTiles = await createSBCButtons();
  sbcTiles.forEach((tile) => sbcDiv.appendChild(tile));

  if (getSettings(0, 0, "sbcType") === "Login") {
    enableLoginToolbarDragAndDrop(sbcDiv);
  }

  const savedScrollTop = Number(window.__sbcToolbarListScrollTop || 0);
  if (savedScrollTop > 0) {
    sbcDiv.scrollTop = savedScrollTop;
  }

  nav.appendChild(sbcDiv);

  document.querySelectorAll(".sbc-auto").forEach((el) => el.remove());
  document.querySelectorAll(".ut-tab-bar-view").forEach((el) => {
    el.insertBefore(nav, el.firstChild);
  });

  if (savedScrollTop > 0) {
    requestAnimationFrame(() => {
      const currentScrollContainer = document.querySelector(
        "#sbcToolbar #sbcToolbarListScroll",
      );
      if (currentScrollContainer) {
        currentScrollContainer.scrollTop = savedScrollTop;
      }
    });
  }
};
const sbcFavoriteTagOverride = () => {
  const favTag = UTSBCFavoriteButtonControl.prototype.watchSBCSet;

  UTSBCFavoriteButtonControl.prototype.watchSBCSet = function () {
    const result = favTag.call(this);
    createSBCTab();
    return result;
  };
};
// SBC Settings - Data Layer
// Handles reading/writing solver settings via backend HTTP API (with localStorage fallback).
// Settings are keyed by SBC name and challenge name (not IDs, which expire/change over time).

let SOLVER_SETTINGS_KEY = "sbcSolverSettings";
let cachedSolverSettings;
let _settingsReady = false;
const SETTINGS_API_URL = "http://127.0.0.1:8000/api/settings";

const getDefaultPackAnimationFilterRule = () => ({
  filters: ["rating"],
  ratingRange: [86, 99],
  priceRange: [200, 15000000],
  includeLeagues: [],
  excludeLeagues: [],
  includeTeams: [],
  excludeTeams: [],
  includeNations: [],
  excludeNations: [],
  includeRarity: [],
  excludeRarity: [],
});

const normalizePackAnimationFilterRule = (value) => {
  const defaults = getDefaultPackAnimationFilterRule();

  if (value && typeof value === "object" && !Array.isArray(value)) {
    return {
      ...defaults,
      ...value,
      filters: Array.isArray(value.filters) ? value.filters : defaults.filters,
      ratingRange:
        Array.isArray(value.ratingRange) && value.ratingRange.length === 2
          ? value.ratingRange
          : defaults.ratingRange,
      priceRange:
        Array.isArray(value.priceRange) && value.priceRange.length === 2
          ? value.priceRange
          : defaults.priceRange,
      includeLeagues: Array.isArray(value.includeLeagues)
        ? value.includeLeagues
        : defaults.includeLeagues,
      excludeLeagues: Array.isArray(value.excludeLeagues)
        ? value.excludeLeagues
        : defaults.excludeLeagues,
      includeTeams: Array.isArray(value.includeTeams)
        ? value.includeTeams
        : defaults.includeTeams,
      excludeTeams: Array.isArray(value.excludeTeams)
        ? value.excludeTeams
        : defaults.excludeTeams,
      includeNations: Array.isArray(value.includeNations)
        ? value.includeNations
        : defaults.includeNations,
      excludeNations: Array.isArray(value.excludeNations)
        ? value.excludeNations
        : defaults.excludeNations,
      includeRarity: Array.isArray(value.includeRarity)
        ? value.includeRarity
        : defaults.includeRarity,
      excludeRarity: Array.isArray(value.excludeRarity)
        ? value.excludeRarity
        : defaults.excludeRarity,
    };
  }

  return defaults;
};

// Name-based caching for current SBC/challenge context
let _currentSbcName = null;
let _currentChallengeName = null;

// --- Backend API helpers ---------------------------------------------------

const _readSettingsFromBackend = async () => {
  try {
    const response = await fetch(SETTINGS_API_URL);
    if (!response.ok) {
      console.warn("[SBC] Backend returned non-OK status:", response.status);
      return null;
    }
    return await response.json();
  } catch (err) {
    console.error("[SBC] Failed to read settings from backend:", err);
    return null;
  }
};

const _writeSettingsToBackend = async (settings) => {
  try {
    const response = await fetch(SETTINGS_API_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(settings),
    });
    if (!response.ok) {
      console.error("[SBC] Backend returned non-OK status on write:", response.status);
      return false;
    }
    return true;
  } catch (err) {
    console.error("[SBC] Failed to write settings to backend:", err);
    return false;
  }
};

// Bootstrap: load from backend, migrate from localStorage if needed
(async () => {
  try {
    let data = await _readSettingsFromBackend();
    if (!data || Object.keys(data).length === 0) {
      // No settings on backend – migrate from localStorage if available
      const raw = localStorage.getItem(SOLVER_SETTINGS_KEY);
      if (raw) {
        try {
          data = JSON.parse(raw);
          await _writeSettingsToBackend(data);
          console.log("[SBC] Migrated solver settings from localStorage to backend");
        } catch (parseErr) {
          console.error("[SBC] Failed to parse localStorage settings:", parseErr);
          data = null;
        }
      }
    }
    if (data) {
      cachedSolverSettings = data;
      // Also keep localStorage in sync as a fallback
      localStorage.setItem(SOLVER_SETTINGS_KEY, JSON.stringify(data));
    }
  } catch (err) {
    console.error("[SBC] Settings bootstrap error:", err);
  } finally {
    // Run migrations after load
    initDefaultSettings();
    _settingsReady = true;
  }
})();

// --- Public API (synchronous cache + async backend persist) ------------------

let setSolverSettings = function (key, Settings) {
  let SolverSettings = getSolverSettings();
  SolverSettings[key] = Settings;
  cachedSolverSettings = SolverSettings;
  // Also keep localStorage in sync
  localStorage.setItem(SOLVER_SETTINGS_KEY, JSON.stringify(cachedSolverSettings));
  // Persist to backend asynchronously (fire and forget with error logging)
  _writeSettingsToBackend(cachedSolverSettings).catch((err) => {
    console.error("[SBC] Failed to persist settings to backend:", err);
  });
};

let getSolverSettings = function () {
  if (cachedSolverSettings) {
    return cachedSolverSettings;
  }
  cachedSolverSettings = {};
  // Fallback: read from localStorage if cache is empty
  let SolverSettings = localStorage.getItem(SOLVER_SETTINGS_KEY);
  if (SolverSettings) {
    try {
      cachedSolverSettings = JSON.parse(SolverSettings);
    } catch {
      cachedSolverSettings = {};
    }
  }
  return cachedSolverSettings;
};

// Set current context for name-based lookups
const setCurrentSbcContext = (sbcName, challengeName) => {
  _currentSbcName = sbcName;
  _currentChallengeName = challengeName;
};

// Normalize to name-based keys, with fallback to global
const _normalizeKey = (sbc, challenge) => {
  // Global settings (0, 0) - use "global" prefix
  if (sbc === 0 || sbc === "0" || sbc === null || sbc === undefined) {
    return { sbcKey: "global", challengeKey: "global" };
  }
  
  // Use provided name if it's a string (not numeric)
  // If numeric, use current context name or don't save (to avoid ID pollution)
  let sbcKey = sbc;
  let challengeKey = challenge;
  
  // If sbcKey looks numeric, try to use current context
  if (typeof sbcKey === "number" || (typeof sbcKey === "string" && /^\d+$/.test(sbcKey))) {
    sbcKey = _currentSbcName || null;
  }
  
  // If challengeKey looks numeric, try to use current context
  if (typeof challengeKey === "number" || (typeof challengeKey === "string" && /^\d+$/.test(challengeKey))) {
    challengeKey = _currentChallengeName || "global";
  }
  
  // If no sbcKey, fallback to global (but log warning)
  if (!sbcKey) {
    console.warn("[SBC] saveSettings called with numeric ID but no SBC name context set. Using global.");
    sbcKey = "global";
  }
  
  return { sbcKey, challengeKey };
};

const saveSettings = (sbc, challenge, id, value) => {
  let settings = getSolverSettings();
  settings["sbcSettings"] ??= {};
  let sbcSettings = settings["sbcSettings"];
  
  const { sbcKey, challengeKey } = _normalizeKey(sbc, challenge);
  const numericSbcValue =
    typeof sbc === "number"
      ? sbc
      : typeof sbc === "string" && sbc.trim() !== ""
        ? Number(sbc)
        : NaN;
  const isNumericSbcInput =
    typeof sbc === "number" ||
    (typeof sbc === "string" && /^\d+$/.test(sbc.trim()));
  const isExplicitGlobalInput =
    sbc === "global" ||
    challenge === "global" ||
    sbc == null ||
    (Number.isFinite(numericSbcValue) && numericSbcValue === 0);
  
  // Don't save if we had to default to global due to missing context
  // (this prevents polluting settings with orphaned numeric ID entries)
  if (sbcKey === "global" && isNumericSbcInput && !isExplicitGlobalInput) {
    console.warn(`[SBC] Skipping save to numeric ID ${sbc}/${challenge} - waiting for SBC name context`);
    return;
  }
  
  sbcSettings[sbcKey] ??= {};
  sbcSettings[sbcKey][challengeKey] ??= {};
  sbcSettings[sbcKey][challengeKey][id] = value;
  setSolverSettings("sbcSettings", sbcSettings);
};

const getSettings = (sbc, challenge, id) => {
  let settings = getSolverSettings();
  const { sbcKey, challengeKey } = _normalizeKey(sbc, challenge);
  
  // Try: exact match (by name/global) -> SBC-level settings -> global
  // Skip any numeric ID-based keys (sbc_\d+ or challenge_\d+)
  let returnValue =
    settings["sbcSettings"]?.[sbcKey]?.[challengeKey]?.[id] ??
    settings["sbcSettings"]?.[sbcKey]?.["global"]?.[id] ??
    settings["sbcSettings"]?.["global"]?.["global"]?.[id] ??
    defaultSBCSolverSettings[id];

  return returnValue;
};

const defaultSBCSolverSettings = {
  apiUrl: "http://127.0.0.1:8000",
  excludeTeams: [],
  excludeRarity: [],
  excludeNations: [],
  excludeLeagues: [],
  excludePlayers: [],
  excludeSbc: false,
  excludeTradable: false,
  excludeSpecial: false,
  excludeObjective: false,
  excludeEvolutions: true,
  excludeExtinct: false,
  excludeFromSquadIds: [],
  onlyStorage: false,
  useConcepts: false,
  collectConcepts: false,
  animateWalkoutItems: getDefaultPackAnimationFilterRule(),
  playSounds: true,
  showAutoBuyButton: true,
  autoBuyCurrency: "COINS",
  autoSubmit: 0,
  maxSolveTime: 60,
  priceCacheMinutes: 1440,
  ratingRange: [0, 99],
  repeatCount: 0,
  showPrices: true,
  showRecentPackedSpecials: true,
  showSbcSubmitTracker: true,
  showSbcTab: true,
  showQuickSolutionButtonOnSbcScreen: true,
  showQuickBuyButtonOnSbcScreen: true,
  useDupes: true,
  runInBackground: false,
  autoOpenPacks: false,
  autoOpenSub100CoinPacks: false,
  autoGrindOpenAllPacks: true,
  autoGrindSubmitMode: 4,
  autoApplyQuickSolutionOnOpen: false,
  lockMinOnePlayerRequirements: true,
  saveTotw: false,
  sbcType: "Favourites",
  showLogOverlay: false,
  duplicateDiscount: 50,
  untradeableDiscount: 80,
  conceptPremium: 10,
  evoPremium: 2,
  ratingUI: false,
  replaceStoragePlayers: false,
  loginSbcOrder: [],
  conceptResetHour: 7,
  maxPlayerPrice: 0,
};

const migrateMaxRatingSettings = () => {
  const settings = getSolverSettings();
  const sbcSettings = settings?.sbcSettings;

  if (!sbcSettings) {
    return;
  }

  let needsSave = false;
  const newSettings = {};

  // Migrate from old ID-based keys to name-based keys
  Object.entries(sbcSettings).forEach(([sbcKey, challenges]) => {
    if (!challenges || typeof challenges !== "object") {
      // Copy non-object entries as-is (like "global", "sbcSettings" parent)
      newSettings[sbcKey] = challenges;
      return;
    }

    // Check if this looks like an old ID key (numeric prefix like sbc_1035)
    const isOldIdFormat = /^sbc_\d+$|^challenge_\d+$/.test(sbcKey);
    
    if (isOldIdFormat) {
      console.log(`[SBC] Removing orphaned ID-based settings key: ${sbcKey}`);
      needsSave = true;
      // Skip this key entirely - don't copy it to newSettings
      return;
    }

    // Keep non-numeric keys
    if (!newSettings[sbcKey]) {
      newSettings[sbcKey] = {};
    }

    Object.entries(challenges).forEach(([challengeKey, config]) => {
      if (!config || typeof config !== "object") {
        return;
      }

      // Handle maxRating migration (legacy field)
      if ("maxRating" in config) {
        const maxRating = Number(config.maxRating);
        if (Number.isFinite(maxRating)) {
          const currentRange = Array.isArray(config.ratingRange)
            ? [...config.ratingRange]
            : [0, 99];

          currentRange[1] = maxRating;
          config.ratingRange = currentRange;
          needsSave = true;
        }

        delete config.maxRating;
        needsSave = true;
      }

      // Only keep challenge keys that aren't numeric
      if (!/^challenge_\d+$/.test(challengeKey)) {
        if (!newSettings[sbcKey][challengeKey]) {
          newSettings[sbcKey][challengeKey] = {};
        }
        Object.assign(newSettings[sbcKey][challengeKey], config);
      } else {
        needsSave = true; // Mark as changed if we're dropping numeric challenge keys
      }
    });
  });

  if (needsSave) {
    console.log("[SBC] Cleaned up orphaned ID-based settings keys");
    cachedSolverSettings.sbcSettings = newSettings;
    setSolverSettings("sbcSettings", newSettings);
  }
};

const migrateLoginSbcOrderFromSbcOnLogin = () => {
  const settings = getSolverSettings();
  const sbcSettings = settings?.sbcSettings;

  if (!sbcSettings || typeof sbcSettings !== "object") {
    return;
  }

  const globalSettings = sbcSettings?.global?.global || {};
  const existingOrder = Array.isArray(globalSettings.loginSbcOrder)
    ? globalSettings.loginSbcOrder.map((entry) => String(entry).trim()).filter(Boolean)
    : [];

  const existingOrderSet = new Set(existingOrder.map((entry) => entry.toLowerCase()));
  const loginEnabledSbcNames = [];

  Object.entries(sbcSettings).forEach(([sbcName, challengeMap]) => {
    if (sbcName === "global" || !challengeMap || typeof challengeMap !== "object") {
      return;
    }

    const hasLoginEnabled = Object.values(challengeMap).some(
      (config) => config && typeof config === "object" && config.sbcOnLogin === true,
    );

    if (hasLoginEnabled) {
      loginEnabledSbcNames.push(sbcName);
    }
  });

  const missingNames = loginEnabledSbcNames.filter(
    (name) => !existingOrderSet.has(String(name).toLowerCase()),
  );

  if (missingNames.length === 0) {
    return;
  }

  const nextOrder = [...existingOrder, ...missingNames];
  sbcSettings.global ??= {};
  sbcSettings.global.global ??= {};
  sbcSettings.global.global.loginSbcOrder = nextOrder;
  cachedSolverSettings.sbcSettings = sbcSettings;
  setSolverSettings("sbcSettings", sbcSettings);
  console.log("[SBC] Added missing login SBCs to loginSbcOrder", missingNames);
};

let initDefaultSettings = () => {
  migrateMaxRatingSettings();
  migrateLoginSbcOrderFromSbcOnLogin();
};
// SBC Settings - UI Control Builders
// Reusable UI primitives for building the settings panel.

const createPanel = (long = false) => {
  var panel = document.createElement("div");
  if (long) {
    panel.classList.add("sbc-settings-longField");
  } else {
    panel.classList.add("sbc-settings-field");
  }

  return panel;
};

const createTooltip = (tooltip, labelSpan, labelContainer) => {
  const tooltipIcon = document.createElement("span");
  const labelWrapper = document.createElement("div");
  labelWrapper.style.position = "relative";
  labelWrapper.style.display = "inline-block";
  labelWrapper.style.paddingRight = "25px";
  labelWrapper.appendChild(labelSpan);

  // Add a data attribute for the tooltip text
  labelWrapper.dataset.tooltip = tooltip;
  labelWrapper.classList.add("tooltip-container");

  // Replace the labelContainer with our wrapper
  labelContainer.appendChild(labelWrapper);
  labelContainer.appendChild(tooltipIcon);
};

const createDoubleRangeControl = (
  parentDiv,
  label,
  id,
  absoluteMin = 0,
  absoluteMax = 99,
  value = [0, 99],
  target = () => {},
  tooltip = "",
  step = UTDoubleRangeControl.DEFAULT_STEP,
  valueLabel = ["Min Ovr", " Max Ovr"],
) => {
  const panelRow = document.createElement("div");
  panelRow.classList.add("panelActionRow");
  const infoLabel = document.createElement("div");
  infoLabel.classList.add("buttonInfoLabel");
  const rangeLabel = document.createElement("span");
  rangeLabel.classList.add("spinnerLabel");
  rangeLabel.innerHTML = label;
  infoLabel.appendChild(rangeLabel);

  if (tooltip) {
    createTooltip(tooltip, rangeLabel, infoLabel);
  }

  panelRow.appendChild(infoLabel);

  const rangeControl = new UTDoubleRangeControl();
  rangeControl._generate();
  (rangeControl.init(),
    rangeControl.setStep(step),
    (rangeControl.latestSetMin = value[0]),
    (rangeControl.latestSetMax = value[1]),
    rangeControl.setAbsoluteMin(absoluteMin),
    rangeControl.setAbsoluteMax(absoluteMax),
    rangeControl._setValue(value[0], rangeControl.__rangeSliderMinInput),
    rangeControl._setValue(value[1], rangeControl.__rangeSliderMaxInput),
    rangeControl.setMinTitle(valueLabel[0]),
    rangeControl.setMaxTitle(valueLabel[1]),
    rangeControl._refresh());
  rangeControl.addTarget(rangeControl, target, EventType.INPUT);

  const panel = createPanel(true);
  panel.setAttribute("id", id);
  panel.appendChild(panelRow);
  panel.appendChild(rangeControl.getRootElement());
  parentDiv.appendChild(panel);

  return panel;
};

const createNumberSpinner = (
  parentDiv,
  label,
  id,
  min = 0,
  max = 100,
  value = 1,
  target = () => {},
  tooltip = "",
) => {
  var i = document.createElement("div");
  i.classList.add("panelActionRow");
  var o = document.createElement("div");
  o.classList.add("buttonInfoLabel");
  var spinnerLabel = document.createElement("span");
  spinnerLabel.classList.add("spinnerLabel");
  spinnerLabel.innerHTML = label;
  o.appendChild(spinnerLabel);

  // Add tooltip icon if tooltip text is provided
  if (tooltip) {
    createTooltip(tooltip, spinnerLabel, o);
  }

  i.appendChild(o);
  let spinner = new UTNumberInputSpinnerControl();
  let panel = createPanel();

  spinner.init();
  spinner.setLimits(min, max);
  spinner.setValue(value);
  spinner.addTarget(spinner, target, EventType.CHANGE);
  panel.appendChild(i);
  panel.appendChild(spinner.getRootElement());

  parentDiv.appendChild(panel);
  return panel;
};

const createTextInput = (
  parentDiv,
  label,
  id,
  value = "",
  onChange = () => {},
  tooltip = "",
  placeholder = "",
) => {
  const row = document.createElement("div");
  row.classList.add("panelActionRow");

  const infoLabel = document.createElement("div");
  infoLabel.classList.add("buttonInfoLabel");

  const textLabel = document.createElement("span");
  textLabel.classList.add("spinnerLabel");
  textLabel.innerHTML = label;
  infoLabel.appendChild(textLabel);

  if (tooltip) {
    createTooltip(tooltip, textLabel, infoLabel);
  }

  row.appendChild(infoLabel);

  const panel = createPanel();
  panel.setAttribute("id", id);
  panel.appendChild(row);

  const input = document.createElement("input");
  input.type = "text";
  input.value = value == null ? "" : String(value);
  input.placeholder = placeholder || "";
  input.style.width = "100%";
  input.style.padding = "8px";
  input.style.boxSizing = "border-box";

  input.addEventListener("change", () => onChange(input.value));
  input.addEventListener("blur", () => onChange(input.value));

  panel.appendChild(input);
  parentDiv.appendChild(panel);
  return panel;
};

const createChoice = (
  parentDiv,
  label,
  id,
  options,
  sbc,
  challenge,
  tooltip = "",
) => {
  if (document.contains(document.getElementById(id))) {
    document.getElementById(id).remove();
  }
  const i = document.createElement("div");
  i.classList.add("panelActionRow");
  const o = document.createElement("div");
  o.classList.add("buttonInfoLabel");
  const choicesLabel = document.createElement("span");
  choicesLabel.classList.add("choicesLabel");
  choicesLabel.innerHTML = label;
  o.appendChild(choicesLabel);

  if (tooltip) {
    createTooltip(tooltip, choicesLabel, o);
  }

  i.appendChild(o);

  let panel = createPanel();
  panel.appendChild(i);
  panel.setAttribute("id", id);
  let select = document.createElement("select");
  select.multiple = "multiple";
  select.setAttribute("id", "choice" + id);

  panel.appendChild(select);
  parentDiv.appendChild(panel);
  let currentSettings = getSettings(sbc, challenge, id) || [];

  const choices = new Choices(select, {
    choices: options,
    closeDropdownOnSelect: true,
    removeItemButton: true,
    shouldSort: false,
    allowHTML: true,
    callbackOnCreateTemplates: function (template) {
      return {
        item: (classNames, data) => {
          const customProps = data.customProperties
            ? data.customProperties
            : {};
          return template(`
              <div class="choices__item choices__item--selectable ${
                data.highlighted ? "choices__item--highlighted" : ""
              }" data-item data-deletable data-id="${data.id}" data-value="${
                data.value
              }" data-custom-properties='${data.customProperties}' ${
                data.active ? 'aria-selected="true"' : ""
              }>
                ${customProps.icon || ""} ${data.label}
                <button type="button" class="choices__button" aria-label="Remove item: ${
                  data.value
                }" data-button>Remove item</button>
             </div>
            `);
        },
        choice: (classNames, data) => {
          const customProps = data.customProperties
            ? data.customProperties
            : {};
          return template(`
              <div class=" choices__item choices__item--choice ${
                data.disabled
                  ? "choices__item--disabled"
                  : "choices__item--selectable"
              }" data-select-text="${
                this.config.itemSelectText
              }" data-choice data-id="${data.id}" data-value="${data.value}" ${
                data.disabled
                  ? 'data-choice-disabled aria-disabled="true"'
                  : "data-choice-selectable"
              }>
                ${customProps.icon || ""} ${data.label}
               </div>
            `);
        },
      };
    },
  });

  choices.setChoiceByValue(currentSettings);
  select.addEventListener(
    "change",
    function (event) {
      saveSettings(sbc, challenge, id, choices.getValue(true));
    },
    false,
  );
};

const createChoiceLocal = (
  parentDiv,
  label,
  id,
  options,
  currentValues,
  onChange,
  tooltip = "",
  config = {},
) => {
  if (document.contains(document.getElementById(id))) {
    document.getElementById(id).remove();
  }
  const i = document.createElement("div");
  i.classList.add("panelActionRow");
  const o = document.createElement("div");
  o.classList.add("buttonInfoLabel");
  const choicesLabel = document.createElement("span");
  choicesLabel.classList.add("choicesLabel");
  choicesLabel.innerHTML = label;
  o.appendChild(choicesLabel);

  if (tooltip) {
    createTooltip(tooltip, choicesLabel, o);
  }

  i.appendChild(o);

  let container = document.createElement("div");
  container.appendChild(i);
  container.setAttribute("id", id);
  let select = document.createElement("select");
  select.multiple = "multiple";
  select.setAttribute("id", `choice${id}`);

  container.appendChild(select);
  parentDiv.appendChild(container);

  const normalizedValues = Array.isArray(currentValues)
    ? currentValues
        .map((value) => String(value || "").trim())
        .filter(Boolean)
    : [];

  const normalizedOptions = Array.isArray(options)
    ? options
        .map((option) => ({
          ...option,
          value: String(option?.value ?? "").trim(),
          label: String(option?.label ?? option?.value ?? "").trim(),
        }))
        .filter((option) => option.value)
    : [];

  const mergedOptions = [...normalizedOptions];
  if (config.allowCustomValues) {
    const existingOptionValues = new Set(
      normalizedOptions.map((option) => option.value),
    );
    normalizedValues.forEach((value) => {
      if (existingOptionValues.has(value)) {
        return;
      }
      existingOptionValues.add(value);
      mergedOptions.push({ value, label: value });
    });
  }

  const choices = new Choices(select, {
    choices: mergedOptions,
    closeDropdownOnSelect: true,
    removeItemButton: true,
    duplicateItemsAllowed: Boolean(config.allowCustomValues) ? false : true,
    addItems: Boolean(config.allowCustomValues),
    addChoices: Boolean(config.allowCustomValues),
    editItems: Boolean(config.allowCustomValues),
    paste: Boolean(config.allowCustomValues),
    delimiter: ",",
    shouldSort: false,
    allowHTML: true,
    callbackOnCreateTemplates: function (template) {
      return {
        item: (classNames, data) => {
          const customProps = data.customProperties
            ? data.customProperties
            : {};
          return template(`
              <div class="choices__item choices__item--selectable ${
                data.highlighted ? "choices__item--highlighted" : ""
              }" data-item data-deletable data-id="${data.id}" data-value="${
                data.value
              }" data-custom-properties='${data.customProperties}' ${
                data.active ? 'aria-selected="true"' : ""
              }>
                ${customProps.icon || ""} ${data.label}
                <button type="button" class="choices__button" aria-label="Remove item: ${
                  data.value
                }" data-button>Remove item</button>
             </div>
            `);
        },
        choice: (classNames, data) => {
          const customProps = data.customProperties
            ? data.customProperties
            : {};
          return template(`
              <div class=" choices__item choices__item--choice ${
                data.disabled
                  ? "choices__item--disabled"
                  : "choices__item--selectable"
              }" data-select-text="${
                this.config.itemSelectText
              }" data-choice data-id="${data.id}" data-value="${data.value}" ${
                data.disabled
                  ? 'data-choice-disabled aria-disabled="true"'
                  : "data-choice-selectable"
              }>
                ${customProps.icon || ""} ${data.label}
               </div>
            `);
        },
      };
    },
  });

  if (normalizedValues.length) {
    choices.setChoiceByValue(normalizedValues);
  }

  select.addEventListener(
    "change",
    function () {
      onChange(choices.getValue(true));
    },
    false,
  );
};

const createDropDown = (
  parentDiv,
  label,
  id,
  options,
  value,
  target,
  tooltip = "",
  fullWidth = false,
  triggerOnInit = true,
) => {
  if (document.contains(document.getElementById(id))) {
    document.getElementById(id).remove();
  }

  const i = document.createElement("div");
  i.classList.add("panelActionRow");

  const o = document.createElement("div");
  o.classList.add("buttonInfoLabel");

  // Add label
  const spinnerLabel = document.createElement("span");
  spinnerLabel.classList.add("spinnerLabel");
  spinnerLabel.innerHTML = label;
  o.appendChild(spinnerLabel);

  // Add tooltip icon if tooltip text is provided
  if (tooltip) {
    createTooltip(tooltip, spinnerLabel, o);
  }

  i.appendChild(o);

  let dropdown = new UTDropDownControl();
  let container = document.createElement("div");
  container.classList.add("sbc-settings-field");
  container.style.width = "45%";
  if (fullWidth) {
    container.style.width = "100%";
  }
  container.appendChild(i);
  container.appendChild(dropdown.getRootElement());
  container.setAttribute("id", id);
  dropdown.init();

  dropdown.setOptions(options);

  // Guard against controls that emit CHANGE while initial value is being bound.
  // We only want target callbacks from explicit init trigger or real user edits.
  let isInitializing = true;
  dropdown.addTarget(
    dropdown,
    (...args) => {
      if (isInitializing) {
        return;
      }
      target(...args);
    },
    EventType.CHANGE,
  );
  parentDiv.appendChild(container);
  dropdown.setIndexById(value);
  isInitializing = false;
  if (triggerOnInit) {
    dropdown._triggerActions(EventType.CHANGE);
  }
  return dropdown;
};

const createToggle = (parentDiv, label, id, value, target, tooltip = "") => {
  let toggle = new UTToggleCellView();
  let panel = createPanel();
  panel.id = id;

  // Create label container
  const labelContainer = document.createElement("div");
  labelContainer.style.display = "flex";
  labelContainer.style.alignItems = "center";

  // Add label text
  const labelSpan = document.createElement("span");
  labelSpan.textContent = label;
  labelContainer.appendChild(labelSpan);

  // Add tooltip icon if tooltip text is provided
  if (tooltip) {
    createTooltip(tooltip, labelSpan, labelContainer);
  }

  // Set label container as toggle label
  toggle.setLabel("");
  toggle.getRootElement().prepend(labelContainer);

  panel.appendChild(toggle.getRootElement());
  toggle.init();

  if (value) {
    toggle.toggle();
  }

  toggle.addTarget(toggle, target, EventType.TAP);
  parentDiv.appendChild(panel);
  return panel;
};

const createSettingsTile = (parentDiv, label, id, tooltip = "") => {
  if (document.contains(document.getElementById(id))) {
    document.getElementById(id).remove();
  }

  var tile = document.createElement("div");
  tile.setAttribute("id", id);
  tile.classList.add("tile");
  tile.classList.add("col-1-1");
  tile.classList.add("sbc-settings-wrapper");
  tile.classList.add("main-header");

  var tileheader = document.createElement("div");
  tileheader.classList.add("sbc-settings-header");
  var h1 = document.createElement("H1");
  h1.innerHTML = label;
  if (tooltip) {
    h1.classList.add("tooltip-container");
    h1.setAttribute("data-tooltip", tooltip);
  }
  tileheader.appendChild(h1);
  tile.appendChild(tileheader);
  var tileContent = document.createElement("div");
  tileContent.classList.add("sbc-settings-section");
  tile.appendChild(tileContent);
  parentDiv.appendChild(tile);
  return tileContent;
};

/**
 * Creates a styled SBC settings panel div for use in challenge hover and other UI contexts.
 * Matches the visual style of SBC settings without the tile wrapper.
 * @param {string} label - Panel header label/title
 * @param {string} id - Unique identifier for the panel div
 * @param {string} tooltip - Optional tooltip text for the header
 * @returns {Object} Object containing { container: styledDiv, contentSection: sectionForControls }
 */
const createSBCSettingsPanel = (label, id, tooltip = "") => {
  const container = document.createElement("div");
  container.setAttribute("id", id);
  container.classList.add("sbc-settings-wrapper");
  container.style.marginTop = "0";
  container.style.padding = "10px";
  container.style.paddingTop = "0";
  container.style.maxHeight = "400px";
  container.style.overflowY = "auto";

  const header = document.createElement("div");
  header.classList.add("sbc-settings-header");
  header.style.marginTop = "0";
  header.style.marginBottom = "5px";

  const headerTitle = document.createElement("h3");
  headerTitle.style.fontWeight = "bold";
  headerTitle.style.margin = "0";
  headerTitle.style.userSelect = "none";
  headerTitle.textContent = label;

  if (tooltip) {
    headerTitle.classList.add("tooltip-container");
    headerTitle.setAttribute("data-tooltip", tooltip);
  }

  header.appendChild(headerTitle);
  container.appendChild(header);

  const contentSection = document.createElement("div");
  contentSection.classList.add("sbc-settings-section");
  contentSection.style.fontSize = "0.85em";
  container.appendChild(contentSection);

  return { container, contentSection };
};

function Counter(selector, settings) {
  let shield = getElement(".ut-click-shield");
  if (!document.contains(document.getElementsByClassName("numCounter")[0])) {
    var counterContent = document.createElement("div");
    counterContent.classList.add("numCounter");
    counterContent.addEventListener("click", () => {
      createSbc = false;
      hideLoader();
    });
    shield.appendChild(counterContent);
  }
  this.settings = Object.assign(
    {
      digits: 5,
      delay: 250, // ms
      direction: "", // ltr is default
    },
    settings || {},
  );

  var scopeElm = document.querySelector(selector);

  // generate digits markup
  var digitsHTML = Array(this.settings.digits + 1).join(
    '<div><b data-value="0"></b></div>',
  );
  scopeElm.innerHTML = digitsHTML;

  this.DOM = {
    scope: scopeElm,
    digits: scopeElm.querySelectorAll("b"),
  };

  this.DOM.scope.addEventListener("transitionend", (e) => {
    if (e.pseudoElement === "::before" && e.propertyName == "margin-top") {
      e.target.classList.remove("blur");
    }
  });

  this.count();
}

Counter.prototype.count = function (newVal) {
  var countTo,
    className,
    settings = this.settings,
    digitsElms = this.DOM.digits;

  // update instance's value
  this.value = newVal || this.DOM.scope.dataset.value | 0;

  if (!this.value) return;

  // convert value into an array of numbers
  countTo = (this.value + "").split("");

  if (settings.direction == "rtl") {
    countTo = countTo.reverse();
    digitsElms = [].slice.call(digitsElms).reverse();
  }

  // loop on each number element and change it
  digitsElms.forEach(function (item, i) {
    if (+item.dataset.value != countTo[i] && countTo[i] >= 0)
      setTimeout(
        function (j) {
          var diff = Math.abs(countTo[j] - +item.dataset.value);
          item.dataset.value = countTo[j];
          if (diff > 3) item.className = "blur";
        },
        i * settings.delay,
        i,
      );
  });
};

function findSBCLogin(obj, keyToFind) {
  let results = [];

  function recursiveSearch(obj, parents = []) {
    if (typeof obj === "object" && obj !== null) {
      for (let key in obj) {
        if (key === keyToFind && obj[key] === true) {
          results.push({
            value: obj[key],
            parents: [...parents, key],
          });
        }
        recursiveSearch(obj[key], [...parents, key]);
      }
    }
  }

  recursiveSearch(obj);
  return results;
}
